window.COURSE = {"title": "Хмарні технології та сервіси", "lectures": [{"id": "w1l1", "num": 1, "week": 1, "title": "Вступ до DevOps: терміни, SDLC і моделі хмарних сервісів", "url": "lectures/week-1/lecture-1.html", "minutes": 42}, {"id": "w1l2", "num": 2, "week": 1, "title": "Linux: командний рядок, файлова система, користувачі, права, процеси", "url": "lectures/week-1/lecture-2.html", "minutes": 107}, {"id": "w1l3", "num": 3, "week": 1, "title": "Bash: скрипти, змінні, умови, цикли та функції", "url": "lectures/week-1/lecture-3.html", "minutes": 54}, {"id": "w1l4", "num": 4, "week": 1, "title": "Архітектура вебзастосунків: HTTP, REST API, N-tier і мікросервіси", "url": "lectures/week-1/lecture-4.html", "minutes": 38}, {"id": "w1l5", "num": 5, "week": 1, "title": "LAMP і SQL: Apache, Nginx, MySQL, запити, JOIN і транзакції", "url": "lectures/week-1/lecture-5.html", "minutes": 52}, {"id": "w2l6", "num": 6, "week": 2, "title": "Комп'ютерні мережі: OSI і TCP/IP, IPv4 і IPv6, DHCP, DNS, NAT, VPN, QoS", "url": "lectures/week-2/lecture-6.html", "minutes": 88}, {"id": "w2l7", "num": 7, "week": 2, "title": "Хмарні обчислення: модель NIST, IaaS/PaaS/SaaS і провайдери AWS, GCP, Azure", "url": "lectures/week-2/lecture-7.html", "minutes": 28}, {"id": "w2l8", "num": 8, "week": 2, "title": "Infrastructure as Code і Terraform: HCL, state, init → plan → apply", "url": "lectures/week-2/lecture-8.html", "minutes": 45}, {"id": "w2l9", "num": 9, "week": 2, "title": "Віртуалізація і контейнери: гіпервізор, namespaces, Docker і Dockerfile", "url": "lectures/week-2/lecture-9.html", "minutes": 36}, {"id": "w2l10", "num": 10, "week": 2, "title": "Системи контролю версій: Git, гілки, Git Flow і pull request", "url": "lectures/week-2/lecture-10.html", "minutes": 27}, {"id": "w3l11", "num": 11, "week": 3, "title": "CI/CD і Jenkins: конвеєр збирання, Jenkinsfile і Pipeline as Code", "url": "lectures/week-3/lecture-11.html", "minutes": 31}, {"id": "w3l12", "num": 12, "week": 3, "title": "GitHub Actions: workflow, jobs, runners, secrets і автоматичний деплой", "url": "lectures/week-3/lecture-12.html", "minutes": 35}], "search": [{"title": "Лекція 1 · Вступ до DevOps: терміни, SDLC і моделі хмарних сервісів", "section": "Вступ", "url": "lectures/week-1/lecture-1.html", "text": ""}, {"title": "Лекція 1 · Вступ до DevOps: терміни, SDLC і моделі хмарних сервісів", "section": "Чого ви навчитесь", "url": "lectures/week-1/lecture-1.html#goals", "text": "Чого ви навчитесь Пояснити, що таке DevOps і чому це культура + практики + інструменти , а не посада «адміна з Docker». Назвати 4 принципи CAMS і ключові DevOps-практики (CI, CD, IaC, моніторинг, контейнери). Сформулювати мету DevOps , переваги автоматизації та принципи continuous delivery ; пояснити, що таке pipeline . Знати, який інструмент (Jenkins, Ansible, Terraform, Nagios, Prometheus…) відповідає за який етап. Розрізняти IaaS, PaaS, SaaS і On-Premises за тим, хто чим керує. Порівняти Waterfall , ітеративні моделі та Agile (Scrum, Kanban, XP). Відрізнити бібліотеку від фреймворку і пояснити, що таке CRUD-застосунок. Розповісти історію DevOps, «три шляхи» і зв'язок з SRE, DevSecOps, GitOps. Описати етапи DevOps-циклу, середовища, правила CI, конвеєр розгортання, артефакти і SemVer. Порівняти стратегії розгортання: rolling, blue-green, canary, feature flags; пояснити відкат. Розрізнити push і pull у керуванні конфігурацією (Ansible vs Puppet/Chef) і три стовпи спостережуваності."}, {"title": "Лекція 1 · Вступ до DevOps: терміни, SDLC і моделі хмарних сервісів", "section": "Програмне забезпечення і CRUD", "url": "lectures/week-1/lecture-1.html#software", "text": "Програмне забезпечення і CRUD Програмне забезпечення (software) — це набір програм і пов'язаних даних , які кажуть комп'ютеру, що і як робити, разом із документацією. Без ПЗ комп'ютер — «просто меблі». Чому наголос на даних ? Майже кожен вебресурс (інтернет-магазин, соцмережа) зберігає дані в базі. Якщо впаде база — сайт формально працює, але стає марним. Тому DevOps-інженер відповідає не лише за код, а й за збереження та резервне копіювання даних. Визначення CRUD — Create, Read, Update, Delete. З будь-якою інформаційною сутністю (товар, користувач, пост) можна зробити лише ці 4 дії, тому більшість застосунків — це «CRUD-застосунки». Пізніше (лекція 4) побачимо, що CRUD напряму відображається на HTTP-методи POST/GET/PUT/DELETE."}, {"title": "Лекція 1 · Вступ до DevOps: терміни, SDLC і моделі хмарних сервісів", "section": "Що таке DevOps", "url": "lectures/week-1/lecture-1.html#devops", "text": "Що таке DevOps Визначення (AWS) DevOps — поєднання культурних філософій, практик та інструментів, яке підвищує здатність організації постачати застосунки та сервіси з високою швидкістю . Проблема: «стіна непорозуміння» Класично розробники (Dev) хочуть часто випускати зміни, а експлуатація (Ops) — щоб система була стабільною. Кожна група має власні інструменти й цілі. Розробники «перекидають через стіну» новий реліз, адміністратори його розгортають — і щось ламається. Agile свого часу зблизив бізнес і розробку; DevOps зближує розробку й експлуатацію . Навіщо DevOps. Agile зближує бізнес і розробку, DevOps — розробку й експлуатацію. Що потрібно від DevOps Робимо Замість Автоматизуємо процеси ручного виконання Автоматичний журнал змін (audit trail) бюрократії Співпрацюємо «перекидання через стіну» Спільна автоматизація повторення одного й того ж кожною командою Принципи CAMS Culture Культура Agile-підхід і спільна відповідальність за весь конвеєр постачання. Automation Автоматизація Вища швидкість і частота релізів, менше ручної праці. Measurement Вимірювання Збираємо метрики: усе в інфраструктурі виміряно і візуалізовано. Sharing Обмін Спільні цілі, знання та інструменти у Dev і Ops. DevOps-цикл і практики DevOps-цикл. Ліва петля — розробка, права — експлуатація; моніторинг повертає зворотний зв'язок у планування. Ключові DevOps-практики зі слайдів: Continuous Integration , Continuous Delivery , Infrastructure as Code (IaC) , моніторинг і логування, мікросервіси, віртуалізація та контейнеризація, безперервний моніторинг. Типові інструменти: Jenkins, TeamCity, Maven/Gradle, Docker, Vagrant, Terraform, Ansible/Chef/Puppet, SonarQube, Nagios/Zabbix, хмари AWS/Azure/GCP. Кожну практику ми розберемо в окремій лекції. Часто CAMS розширюють до CALMS : додається L — Lean (ощадливість): працювати малими порціями, прибирати «втрати» — очікування, ручні передачі, зайві погодження."}, {"title": "Лекція 1 · Вступ до DevOps: терміни, SDLC і моделі хмарних сервісів", "section": "Звідки взявся DevOps і на чому він тримається", "url": "lectures/week-1/lecture-1.html#origins", "text": "Звідки взявся DevOps і на чому він тримається Коротка історія 2008–2009. Бельгійський консультант Патрік Дебуа (Patrick Debois) обговорює «Agile infrastructure». На конференції O'Reilly Velocity 2009 інженери Flickr Джон Олспоу і Пол Гаммонд роблять доповідь «10+ Deploys per Day: Dev and Ops Cooperation at Flickr» — десять і більше релізів на день, коли решта індустрії випускала оновлення раз на кілька місяців. Жовтень 2009. Дебуа організовує в Генті першу конференцію DevOpsDays ; хештег #DevOps дає назву руху. 2010-ті. Книги Continuous Delivery (Jez Humble, David Farley, 2010), The Phoenix Project (2013), The DevOps Handbook (2016), Accelerate (2018, дослідження DORA) перетворюють практики на систему. Сьогодні DevOps — стандартний підхід: хмари, контейнери і CI/CD зробили автоматизацію доступною навіть маленьким командам. Конфлікт, який розв'язує DevOps Розробка (Dev) хоче швидко випускати нові функції експериментувати отримувати фідбек від користувачів оцінюється за кількістю зробленого Експлуатація (Ops) хоче стабільність і передбачуваність мінімум змін у production (кожна зміна — ризик) ретельні процедури погодження оцінюється за аптаймом Коли цілі протилежні, кожна сторона «перемагає» за рахунок іншої: релізи стають рідкісними і величезними, а тому — ризикованими; після збою починається пошук винних. DevOps дає спільну мету (швидко і надійно доставляти цінність користувачам) і спільні інструменти, тому зникає сенс тягнути ковдру на себе. Три шляхи DevOps (The Three Ways) Модель з The Phoenix Project і The DevOps Handbook пояснює, на яких ідеях побудовані всі практики: Шлях Суть Практики 1. Потік (Flow) швидкий рух роботи зліва направо: від ідеї до production малі партії змін, CI/CD, автоматизація, обмеження незавершеної роботи (WIP), видимість роботи на дошці 2. Зворотний зв'язок (Feedback) швидкий сигнал справа наліво: з production назад до розробників автотести, моніторинг і алерти, телеметрія, рев'ю коду, розбір інцидентів 3. Безперервне навчання (Continual learning and experimentation) культура, де помилки — привід вчитися, а експерименти заохочуються розбір інцидентів без пошуку винних (blameless postmortem), час на покращення, A/B-тести, хаос-інжиніри"}, {"title": "Лекція 1 · Вступ до DevOps: терміни, SDLC і моделі хмарних сервісів", "section": "Мета DevOps і як її виміряти", "url": "lectures/week-1/lecture-1.html#goal", "text": "Мета DevOps і як її виміряти Головне для тесту Мета DevOps — створити середовище, у якому надійніші застосунки випускаються швидше (release more reliable applications faster). Обидві частини важливі: швидкість без якості — не DevOps. Навіщо DevOps компанії (need for DevOps): частіші релізи ( increase deployment frequency ), менше збоїв після релізу ( lower failure rate of new releases ), коротший шлях від ідеї до production, швидше відновлення після аварії. Саме ці чотири речі міряє дослідницька програма Google DORA (DevOps Research and Assessment): Метрика DORA Що показує Куди прагнемо Deployment frequency як часто випускаємо в production частіше Lead time for changes час від коміту до production коротше Change failure rate частка релізів, що спричинили збій менше Time to restore (MTTR) скільки відновлюємось після збою швидше Що таке DevOps — і чим він не є Так Розробники й експлуатація працюють разом зі спільною відповідальністю. Культура + практики + інструменти. Контроль змін автоматизований (тести, журнал змін), а не скасований. Одна з моделей — невелика команда, що «володіє» своїм сервісом від коду до production ( you build it, you run it ). Ні Розробники виконують усю роботу Ops замість адмінів. Окрема «команда DevOps», що стоїть між Dev і Ops як нова стіна. Середовище без контролю змін. Реліз цінується більше за якість."}, {"title": "Лекція 1 · Вступ до DevOps: терміни, SDLC і моделі хмарних сервісів", "section": "Етапи DevOps-циклу детально", "url": "lectures/week-1/lecture-1.html#lifecycle", "text": "Етапи DevOps-циклу детально Нескінченна петля (див. схему вище) — не просто картинка. На кожному етапі є конкретні дії, артефакти й інструменти. У тестах питають, «що робиться на якому етапі» і «який інструмент для цього». Етап Що відбувається Результат Інструменти Plan вимоги, задачі, пріоритети, планування спринту беклог, задачі з критеріями готовності Jira, Trello, Azure Boards Code написання коду, рев'ю, гілки, pull request коміти в репозиторії Git, GitHub, GitLab, IDE Build компіляція, збір залежностей, пакування артефакт : .jar , пакет npm, Docker-образ Maven, Gradle, npm, Docker Test автотести: модульні, інтеграційні, end-to-end; аналіз якості й безпеки звіти, «зелена» або «червона» збірка JUnit, pytest, Selenium, SonarQube Release версіонування, збереження артефакту, схвалення релізу артефакт з версією в репозиторії Nexus, Artifactory, GitHub Releases, Docker Hub Deploy розгортання в середовище (staging, production) працююча версія Jenkins, GitHub Actions, Ansible, Kubernetes, Argo CD Operate експлуатація: масштабування, конфігурація, бекапи, оновлення доступний сервіс Terraform, Ansible, Kubernetes, хмарні консолі Monitor метрики, логи, алерти, відгуки користувачів дані для наступного Plan Prometheus, Grafana, Nagios, Zabbix, ELK Середовища (environments) Зміна проходить кілька середовищ, кожне ближче до реальності: Середовище Призначення Local / dev ноутбук розробника або спільний dev-стенд; часто ламається, це нормально Test / QA автоматичні й ручні тести Staging (pre-prod) максимально схоже на production: та сама конфігурація, версії, схожі дані. Остання перевірка перед релізом Production реальні користувачі й дані Ключова ідея DevOps: середовища мають бути однаковими і створюватися автоматично (IaC, контейнери). Інакше з'являється класичне «у мене на машині працює». Один і той самий артефакт збирається один раз і просувається між середовищами; змінюється лише конфігурація (змінні середовища, секрети)."}, {"title": "Лекція 1 · Вступ до DevOps: терміни, SDLC і моделі хмарних сервісів", "section": "Автоматизація: що вона дає", "url": "lectures/week-1/lecture-1.html#automation", "text": "Автоматизація: що вона дає Принцип «автоматизуй усе, що повторюється» — серце DevOps. Автоматизують збірку, тести, створення інфраструктури (IaC), налаштування серверів, деплой, моніторинг і сповіщення. Швидкість, надійність і узгодженість (speed, reliability, consistency): скрипт щоразу робить те саме однаково. Прибирає ручні помилки — забута команда чи опечатка більше не ламає production. Автоматизація не вносить ручних помилок, а усуває їх. Будь-хто може виконати задачу (enables anyone to perform tasks): знання «як розгорнути» записане в скрипті чи пайплайні, а не в голові одного адміна. Журнал змін (audit trail): видно, хто, що й коли запустив. Люди звільняються від рутини і розв'язують справжні проблеми."}, {"title": "Лекція 1 · Вступ до DevOps: терміни, SDLC і моделі хмарних сервісів", "section": "CI, Continuous Delivery і Continuous Deployment", "url": "lectures/week-1/lecture-1.html#cicd", "text": "CI, Continuous Delivery і Continuous Deployment CI → CD. Різниця між Delivery і Deployment — лише в останньому кроці: людина чи автомат вирішує випуск у production. Continuous Integration (CI) — розробники часто зливають код у спільний репозиторій; CI-сервер (наприклад, Jenkins) на кожну зміну збирає проєкт і проганяє тести, повертаючи швидкий зворотний зв'язок. Continuous Delivery — кожна успішна збірка автоматично доходить до staging і готова до релізу; у production — після ручного схвалення. Continuous Deployment — у production теж автоматично, без людини. До «сімейства continuous» також належать continuous testing (автотести на кожному етапі) і continuous monitoring (постійний нагляд за системою в production). Continuous Delivery: визначення і принципи Визначення (continuousdelivery.com, Jez Humble) Continuous Delivery — здатність безпечно, швидко і стабільно доставляти в production зміни будь-якого типу : нові функції, зміни конфігурації, виправлення помилок та експерименти (bug fixes and experiments). Build quality in — вбудовуйте якість: ловіть дефекти якомога раніше автотестами. Work in small batches — малі часті зміни дають швидкий зворотний зв'язок. Computers perform repetitive tasks, people solve problems — тобто Automate Everything : рутину робить машина. Relentlessly pursue continuous improvement — безперервне вдосконалення як частина щоденної роботи. Everyone is responsible — за якість і реліз відповідають усі, а не лише тестувальники чи Ops. Пастка в тестах Збір вимог (gathering requirements) і збір інформації (information gathering) — етапи аналізу в SDLC, а не ознаки continuous delivery. Ознаки CD — автоматизація всього, безперервне вдосконалення, виправлення помилок та експерименти малими релізами. Pipeline (конвеєр постачання) Pipeline у continuous delivery — це автоматизований робочий процес (workflow) : послідовність етапів, якими проходить кожна зміна — коміт → збірка → автотести → staging → реліз. Кожен етап дає зворотний зв'язок; якщо етап «червоний», зміна далі не йде. У Jenkins pipeline описують у Jenkinsfile (лекція 11), у GitHub Actions — у workflow-файлі YAML (лекція 12). Окремий деплой чи окремий крок — лише частина pipeline."}, {"title": "Лекція 1 · Вступ до DevOps: терміни, SDLC і моделі хмарних сервісів", "section": "Практики CI і конвеєр розгортання детально", "url": "lectures/week-1/lecture-1.html#ci-practices", "text": "Практики CI і конвеєр розгортання детально Правила Continuous Integration CI — це не просто «Jenkins запускає збірку». Це домовленість команди, без якої інструмент не допоможе (за Мартіном Фаулером): Єдиний репозиторій із усім, що потрібно для збірки: код, тести, скрипти, конфігурації. Автоматична збірка однією командою. Самотестована збірка : збірка включає автотести, і їх падіння = збірка провалена. Кожен комітить у головну гілку щонайменше раз на день . Довгі гілки — це відкладена «інтеграційна катастрофа». Кожен коміт запускає збірку на CI-сервері, а не лише на ноутбуці розробника. Зламану збірку лагодять негайно — це пріоритет номер один для всієї команди. Збірка швидка (в ідеалі до 10 хвилин), щоб зворотний зв'язок був миттєвим. Результат видно всім : статус збірки, хто що змінив. Конвеєр розгортання (deployment pipeline) Кожна зміна проходить ті самі етапи, і на кожному отримує дедалі більшу впевненість у якості. Що далі етап — то він повільніший і ближчий до production. commit ──► [Commit stage] ──► [Acceptance] ──► [Staging / ручні перевірки] ──► [Production] збірка автоматичні UAT, навантажувальні, реліз: модульні тести приймальні тести безпеки вручну (Delivery) статичний аналіз тести або автоматично ↓ артефакт v1.4.2 зберігається ОДИН раз і просувається далі (Deployment) Артефакт — результат збірки, який розгортають (Docker-образ, .jar , архів). Його збирають один раз і зберігають у репозиторії артефактів (Nexus, Artifactory, Docker Hub, GitHub Packages). Версіонування : популярне семантичне версіонування MAJOR.MINOR.PATCH — 2.4.1 → 2.4.2 (виправлення), 2.5.0 (нова сумісна функція), 3.0.0 (несумісні зміни). Fail fast : найшвидші перевірки стоять першими, щоб зламана зміна зупинилася якомога раніше."}, {"title": "Лекція 1 · Вступ до DevOps: терміни, SDLC і моделі хмарних сервісів", "section": "Стратегії розгортання і відкат", "url": "lectures/week-1/lecture-1.html#strategies", "text": "Стратегії розгортання і відкат Як оновити production так, щоб користувачі не помітили, а при проблемі можна було швидко повернутись? Стратегія Як працює Плюси Мінуси Recreate зупинити стару версію, запустити нову просто простій (downtime) Rolling update сервери оновлюються по черзі, частина завжди працює без простою, без додаткових ресурсів; типово в Kubernetes певний час працюють обидві версії; відкат теж поступовий Blue-green два однакові середовища: «синє» (поточне) і «зелене» (нове). Після перевірки зеленого балансувальник перемикає трафік миттєве перемикання і миттєвий відкат подвійні ресурси на час релізу Canary («канарка») нова версія спочатку отримує малу частку трафіку (1–5%); метрики в нормі → частка зростає ризик зачіпає мало користувачів потрібні добрі метрики і керування трафіком Feature flags (feature toggles) код нової функції вже в production, але вимкнений прапорцем; вмикається без деплою, для частини користувачів реліз коду відокремлено від запуску функції прапорці треба прибирати, інакше код ускладнюється Відкат (rollback) має бути таким самим автоматизованим, як і деплой: повторно розгорнути попередній артефакт, перемкнути трафік назад (blue-green) або вимкнути прапорець. Тому старі версії артефактів не видаляють одразу. Зміни бази даних роблять сумісними з обома версіями коду (спочатку додати колонку, прибрати стару — окремим пізнішим релізом). Зверніть увагу на назви: деплой (deployment) — технічне розгортання версії, реліз (release) — надання функції користувачам. З feature flags і blue-green це можуть бути різні моменти."}, {"title": "Лекція 1 · Вступ до DevOps: терміни, SDLC і моделі хмарних сервісів", "section": "Керування конфігурацією і моніторинг", "url": "lectures/week-1/lecture-1.html#config-monitoring", "text": "Керування конфігурацією і моніторинг Configuration management Інструменти керування конфігурацією описують бажаний стан серверів (встановлені пакети, файли конфігурації, запущені служби) і приводять сервери до нього. Головна властивість — ідемпотентність : повторний запуск не змінює того, що вже в потрібному стані. Інструмент Модель Агент Мова опису Ansible push : керуючий вузол підключається до серверів і виконує задачі без агента (agentless), працює через SSH YAML (playbooks) Puppet pull : агент на сервері періодично забирає конфігурацію з master потрібен агент Puppet DSL Chef pull потрібен агент (chef-client) Ruby (cookbooks, recipes) SaltStack push і pull агент (minion) або SSH YAML Моніторинг і спостережуваність (observability) Без моніторингу команда дізнається про збій від користувачів. Три «стовпи» спостережуваності: Metrics Метрики Числа в часі: завантаження CPU, кількість запитів за секунду, частка помилок, час відповіді. Дешево зберігати, зручно для графіків і алертів. Prometheus, Zabbix, CloudWatch. Logs Логи Текстові записи подій з деталями: «користувач 42 отримав помилку 500 при оплаті». Централізують у ELK/EFK (Elasticsearch + Logstash/Fluentd + Kibana), Loki. Traces Трасування Шлях одного запиту через багато мікросервісів з часом на кожному кроці. Jaeger, Zipkin, OpenTelemetry. Інструмент Що робить Nagios класичний моніторинг доступності: періодичні перевірки (checks) хостів і служб, сповіщення про збої Zabbix моніторинг серверів і мережі з агентами, шаблонами, графіками Prometheus збирає метрики (модель pull — сам опитує сервіси), зберігає часові ряди, мова запитів PromQL, Alertmanager Grafana дашборди і візуалізація для Prometheus, Loki, БД та інших джерел ELK / EFK збір, пошук і аналіз логів Що моніторити в першу чергу — «чотири золоті сигнали» Google SRE: затримка (latency), трафік , помилки , насиченість (saturation — наскільки ресурси близькі до межі). Алерт має вимагати дії людини; алерти, на які ніхто не реагує, лише привчають їх ігнорувати."}, {"title": "Лекція 1 · Вступ до DevOps: терміни, SDLC і моделі хмарних сервісів", "section": "Інструменти DevOps за етапами", "url": "lectures/week-1/lecture-1.html#tools", "text": "Інструменти DevOps за етапами У тестах часто питають «який інструмент для чого» і «які з цих інструментів популярні в DevOps». Правильними будуть усі інструменти з цієї таблиці; неправильними — офісні програми, мови програмування як такі, графічні редактори чи ОС. Знайте по 1–2 назви на кожен етап: Етап / задача Інструменти Планування задач Jira, Trello, Confluence Контроль версій (VCS) Git , GitHub, GitLab, Bitbucket Збірка Maven, Gradle (Java), npm (JavaScript) Тестування і якість коду Selenium, JUnit, SonarQube CI/CD Jenkins , GitHub Actions, GitLab CI, TeamCity Керування конфігурацією Ansible , Puppet, Chef Інфраструктура як код Terraform , AWS CloudFormation, Vagrant Контейнери і оркестрація Docker, Kubernetes Репозиторії артефактів Nexus, JFrog Artifactory, Docker Hub, GitHub Packages Секрети HashiCorp Vault, AWS Secrets Manager, GitHub Secrets Хмари AWS, Microsoft Azure, Google Cloud Моніторинг і логи Nagios , Zabbix, Prometheus (метрики) + Grafana (дашборди), ELK Мови скриптів у DevOps: найпопулярніша — Bash (стандарт на Linux-серверах, лекція 3); далі Python (складніша автоматизація, робота з API хмар), PowerShell (Windows), Groovy (Jenkinsfile). YAML і JSON — не мови програмування, а формати конфігурацій (Ansible, GitHub Actions, Kubernetes)."}, {"title": "Лекція 1 · Вступ до DevOps: терміни, SDLC і моделі хмарних сервісів", "section": "Хмари і моделі сервісів [X]aaS", "url": "lectures/week-1/lecture-1.html#cloud", "text": "Хмари і моделі сервісів [X]aaS Визначення NIST Хмарні обчислення — модель повсюдного, зручного мережевого доступу на вимогу до спільного пулу конфігурованих ресурсів (мережі, ВМ, сховища, застосунки, сервіси), які можна швидко виділити й звільнити з мінімальними зусиллями з управління. Економічний сенс: замість CapEx (капітальні витрати — купити сервери наперед) компанія платить OpEx (операційні витрати — оренда за фактом використання). Хто чим керує. Що вище модель — то менше контролю і менше турбот. Модель Що отримуєте Хто користувач Приклади IaaS — Infrastructure ВМ, мережа, диски. ОС і все вище — ваше адміністратори, DevOps AWS EC2, Azure VM, Google Compute Engine PaaS — Platform готове середовище запуску коду розробники Heroku, AWS Elastic Beanstalk, Google App Engine SaaS — Software готовий застосунок у браузері кінцеві користувачі Gmail, Google Docs, Office 365, Trello, Salesforce Мнемоніка зі слайдів: SaaS — Use it , PaaS — Build with it , IaaS — Move to it . Популярна аналогія — «піца як сервіс»: вдома робите все самі (On-Premises), купуєте напівфабрикат і печете (IaaS), замовляєте доставку (PaaS), йдете в піцерію (SaaS). Межа між PaaS і SaaS на практиці тонка. Як почати безкоштовно Великі провайдери дають free tier: AWS Free Tier, Google Cloud Free Tier, Microsoft Azure Free Account. Детальніше про хмари — у лекції 7."}, {"title": "Лекція 1 · Вступ до DevOps: терміни, SDLC і моделі хмарних сервісів", "section": "Бібліотека vs фреймворк", "url": "lectures/week-1/lecture-1.html#framework", "text": "Бібліотека vs фреймворк Фреймворк — готовий каркас програмних рішень (архітектура + базова функціональність). Перевага: усі системи на ньому мають однакову структуру. Бібліотека (library) Набір функцій для повторного використання. Ви викликаєте бібліотеку, керування повертається вам. Легко додати в наявний проєкт через API. Приклад: Chart.js — для графіків. Фреймворк (framework) Диктує архітектуру проєкту. Фреймворк викликає ваш код (інверсія керування). Зазвичай обирається на старті нового проєкту. Приклад: Angular — для вебзастосунків."}, {"title": "Лекція 1 · Вступ до DevOps: терміни, SDLC і моделі хмарних сервісів", "section": "SDLC і моделі розробки", "url": "lectures/week-1/lecture-1.html#sdlc", "text": "SDLC і моделі розробки SDLC (Software Development Life Cycle) — поділ роботи над ПЗ на фази для кращого планування: аналіз → проєктування → реалізація → тестування (+ розгортання і супровід). Будь-яка програма, мала чи велика, проходить ці кроки. Модель Ідея Коли доречна Waterfall (водоспад) Послідовні фази згори вниз: бізнес-вимоги → вимоги користувача → системні вимоги → архітектура → детальний дизайн → реалізація → тестування. Повернутися назад дорого. Вимоги стабільні й відомі наперед Ітеративна Кожна ітерація — закритий «міні-проєкт» (вимоги, дизайн, код, інтеграція, тести). Наприкінці — повністю протестована версія і відгук стейкхолдерів у план наступної ітерації. Вимоги уточнюються в процесі Еволюційне прототипування Прототип поступово доводиться до готового продукту. Нечіткі вимоги, потрібен ранній фідбек Agile Мінімізує ризик, контролюючи 4 змінні: ресурси, час, якість і особливо обсяг (scope) . Більшість сучасних продуктів Цінності Agile-маніфесту Люди і взаємодія важливіші за процеси та інструменти. Працюючий продукт важливіший за вичерпну документацію. Співпраця із замовником важливіша за узгодження контракту. Готовність до змін важливіша за дотримання плану. Популярні Agile-методології: Scrum (фіксовані спринти, ролі, церемонії), Kanban (безперервний потік задач на дошці з лімітом незавершеної роботи), XP — eXtreme Programming (інженерні практики: парне програмування, TDD, часті релізи)."}, {"title": "Лекція 1 · Вступ до DevOps: терміни, SDLC і моделі хмарних сервісів", "section": "Від хостингу 199x до DevOps-інженера", "url": "lectures/week-1/lecture-1.html#history", "text": "Від хостингу 199x до DevOps-інженера 199x — власне залізо. Компанія купує сервери, мережу, приміщення, наймає адмінів і платить за все, навіть якщо ресурс простоює. 2000-ні — спільні дата-центри. Оренда стійок, але сервери й ПЗ досі свої. Ера сервісів. Хмари, IaaS/PaaS/SaaS, автоматизація. Типова сучасна інфраструктура: балансувальник (NGINX/HAProxy) → кілька вебсерверів (httpd/Tomcat) → основна та резервна БД MySQL. Без моніторингу важко навіть зрозуміти, що «щось не так». DevOps-інженер потрібен практично на кожному середньому/великому проєкті: Linux, мережі, скрипти, хмари, IaC, контейнери, Git, CI/CD — саме ці теми й складають цей курс."}, {"title": "Лекція 1 · Вступ до DevOps: терміни, SDLC і моделі хмарних сервісів", "section": "Типові помилки", "url": "lectures/week-1/lecture-1.html#mistakes", "text": "Типові помилки Збір вимог і збір інформації — ознаки continuous delivery. Це етапи аналізу в SDLC. Ознаки CD: автоматизація всього, малі часті релізи, безперервне вдосконалення, доставка будь-яких змін (фічі, виправлення, експерименти). Автоматизація вносить нові ручні помилки. Навпаки, вона прибирає ручні помилки й дає швидкість, надійність, узгодженість і змогу будь-кому виконати задачу. Pipeline — це лише крок деплою. Pipeline — увесь автоматизований workflow від коміту до production: збірка, тести, артефакт, розгортання. Ansible потребує агента на кожному сервері. Ansible — agentless, push через SSH. Агенти потрібні Puppet і Chef (pull-модель). Для кожного середовища артефакт збирають заново. Артефакт збирають один раз і просувають між середовищами; змінюється лише конфігурація. DevOps — це посада або конкретний інструмент (Docker, Jenkins). DevOps — це культура + практики + інструменти. Інструменти лише реалізують принципи CAMS. Continuous Delivery і Continuous Deployment — синоніми. У Delivery реліз у production схвалює людина; у Deployment він автоматичний. У PaaS я налаштовую ОС і встановлюю runtime. ОС, middleware і runtime в PaaS — зона провайдера. Ваші — лише застосунок і дані. Керування ОС — це IaaS. DevOps — це коли розробники самі виконують усі задачі експлуатації. DevOps — це спільна робота Dev і Ops. Мета — швидші і надійніші релізи, а не перекладання роботи. Jenkins — інструмент контролю версій або моніторингу. Jenkins — сервер CI/CD . Контроль версій — Git; моніторинг — Nagios, Prometheus + Grafana. Фреймворк — це просто «велика бібліотека». Ключова різниця — хто кого викликає: бібліотеку викликаєте ви, фреймворк викликає ваш код."}, {"title": "Лекція 2 · Linux: командний рядок, файлова система, користувачі, права, процеси", "section": "Вступ", "url": "lectures/week-1/lecture-2.html", "text": ""}, {"title": "Лекція 2 · Linux: командний рядок, файлова система, користувачі, права, процеси", "section": "Чого ви навчитесь", "url": "lectures/week-1/lecture-2.html#goals", "text": "Чого ви навчитесь Розуміти, з чого складається Linux (ядро, оболонка, утиліти, дистрибутив) і як читати запрошення командного рядка. Знаходити довідку будь-якою з п'яти способів: man , --help , help , info , apropos , і знати, які «способи» лише виглядають правильними. Орієнтуватися в дереві каталогів за стандартом FHS: де конфіги, програми, логи, спільні файли, пристрої. Вільно працювати зі шляхами ( . , .. , ~ , абсолютні й відносні) і шаблонами ( * , ? , [ ] , { } ). Створювати, копіювати, переміщувати, перейменовувати і видаляти файли та каталоги, розрізняючи всі варіанти rm , rmdir , mkdir -p . Переглядати і шукати: cat , less , head , tail -f , find , locate , grep . Розуміти inode, жорсткі й символічні посилання, змінні середовища і PATH . Комбінувати команди через pipe, перенаправлення та ланцюжки. Керувати користувачами, групами, правами ( chmod числом і символами, umask , SUID/SGID/sticky). Стежити за процесами, пам'яттю, диском, службами й логами; встановлювати пакети; працювати з архівами і SSH."}, {"title": "Лекція 2 · Linux: командний рядок, файлова система, користувачі, права, процеси", "section": "Що таке Linux і чому саме він", "url": "lectures/week-1/lecture-2.html#why", "text": "Що таке Linux і чому саме він Операційна система (ОС) керує залізом і дає програмам спільні сервіси: процеси, пам'ять, файли, мережу, користувачів. Linux належить до сімейства Unix-подібних (*nix) систем. Ядро анонсував Лінус Торвальдс у 1991 році; з 1992 воно поширюється за ліцензією GNU GPL . З чого складається «Linux» Слово «Linux» у побуті означає цілу систему, але технічно це лише ядро. Те, з чим ви працюєте в терміналі, — це кілька шарів: Kernel Ядро Керує процесами, пам'яттю, драйверами, файловими системами, мережею. Програми звертаються до нього через системні виклики. Версія: uname -r . Shell Оболонка Програма, що читає ваші команди і запускає їх: bash , sh , zsh . Поточна: echo $SHELL (оболонка входу) або echo $0 . GNU utilities Утиліти ls , cp , grep , tar … — окремі програми-файли в /usr/bin . Тому кажуть «GNU/Linux». Distribution Дистрибутив Ядро + утиліти + пакетний менеджер + налаштування: Ubuntu, Debian, RHEL, CentOS, Fedora, Alpine. Безкоштовна і з відкритим кодом. Немає ліцензій на кожен сервер. Домінує на серверах і в хмарах : більшість вебсерверів, майже всі контейнери Docker і вузли Kubernetes працюють на Linux. Android теж побудований на ядрі Linux. Можна працювати без графічного інтерфейсу — тільки термінал. Для сервера це економія ресурсів і менша поверхня атаки. Linux vs Windows: ключові відмінності Linux Windows Одне дерево від кореня / ; диски монтуються в каталоги ( /mnt/usb ) Окремі диски з літерами C: , D: Розділювач шляху / \\ Регістр має значення : File.txt , file.txt і FILE.TXT — три різні файли Регістр не враховується Суперкористувач — root (UID 0) Administrator Виконуваність визначає атрибут x , розширення неважливе Розширення .exe , .bat , .cmd Змінна: $PATH , роздільник : Змінна: %PATH% , роздільник ; Довідка: man ls , ls --help Довідка: dir /? , help dir Приховані файли — ім'я починається з крапки: .bashrc Атрибут «прихований» у властивостях файла Дистрибутиви поділяються на сімейства, від яких залежить пакетний менеджер: Debian (Debian, Ubuntu, Mint) — пакети .deb , інструменти dpkg і apt ; Red Hat (RHEL, CentOS, Rocky, Fedora, Amazon Linux) — пакети .rpm , інструменти rpm і yum / dnf ; Alpine (популярний у Docker) — apk ."}, {"title": "Лекція 2 · Linux: командний рядок, файлова система, користувачі, права, процеси", "section": "Термінал, оболонка і синтаксис команди", "url": "lectures/week-1/lecture-2.html#cli", "text": "Термінал, оболонка і синтаксис команди Термінал (terminal emulator) — вікно, у якому ви набираєте текст. Оболонка (shell) — програма всередині нього, яка розбирає рядок і запускає команди. Найпоширеніша оболонка — bash (Bourne Again SHell). Коли ви підключаєтесь до сервера по SSH, термінал у вас локальний, а оболонка працює на сервері. Як читати запрошення (prompt) student@web01:~/projects$ # звичайний користувач root@web01:/etc# # root: символ # замість $ Частина Значення student ім'я поточного користувача (те саме, що whoami ) web01 ім'я машини ( hostname ) ~/projects поточний каталог; ~ — скорочення домашнього каталогу /home/student $ / # $ — звичайний користувач, # — root. Видно одразу, наскільки небезпечна наступна команда Анатомія команди ls -l -a --human-readable /var/log #│ └─┬─┘ └──────┬──────┘ └──┬───┘ #│ короткі довга опція аргумент (з чим працювати) #└─ ім'я команди (програма /usr/bin/ls або вбудована команда оболонки) Короткі опції починаються з одного дефіса і зазвичай складаються з однієї літери: -l . Їх можна об'єднувати: ls -l -a -h = ls -lah . Довгі опції починаються з двох дефісів: --all , --human-readable . Об'єднувати їх не можна. Опції з значенням : head -n 5 file , head -n5 file або head --lines=5 file — однаково. Аргументи — файли, каталоги, рядки. Порядок важливий: у cp , mv , ln спочатку джерело , потім призначення . Подвійний дефіс -- означає «опції скінчились»: rm -- -file.txt видалить файл, ім'я якого починається з дефіса. Пробіл — роздільник. Ім'я з пробілом беріть у лапки: cd \"My Documents\" або екрануйте: cd My\\ Documents . Гарячі клавіші, які економлять години Клавіші Дія Tab / Tab Tab доповнити ім'я команди або файла / показати всі варіанти ↑ ↓ гортати історію команд Ctrl + R пошук в історії за фрагментом Ctrl + C перервати поточну команду (надсилає сигнал SIGINT) Ctrl + Z призупинити команду (SIGTSTP); продовжити — fg або у фоні bg Ctrl + D кінець вводу (EOF); у порожньому рядку — вийти з оболонки Ctrl + L або clear очистити екран (у Windows — cls ) Ctrl + A / Ctrl + E курсор на початок / кінець рядка !! , sudo !! повторити попередню команду (наприклад, з sudo , якщо забули)"}, {"title": "Лекція 2 · Linux: командний рядок, файлова система, користувачі, права, процеси", "section": "Як отримати довідку про команду", "url": "lectures/week-1/lecture-2.html#help", "text": "Як отримати довідку про команду Це окреме питання тесту, і в ньому кілька правильних відповідей. Linux має кілька незалежних систем довідки: Спосіб Що показує Коли працює man ls Повну сторінку посібника (manual page) Для майже всіх програм. Основний спосіб ls --help Короткий перелік опцій, який друкує сама програма Для більшості GNU-утиліт help cd Довідку про вбудовану команду bash Лише для вбудованих: cd , echo , export , alias , history , read , type … info ls Документацію GNU у форматі info (з розділами і посиланнями) Для GNU-програм whatis ls Однорядковий опис Якщо база man-сторінок проіндексована apropos copy = man -k copy Пошук команд за ключовим словом в описах Коли не знаєте назви команди type cd Чим є ім'я: вбудована команда, alias, функція чи файл Щоб зрозуміти, де шукати довідку $ type cd cd is a shell builtin # вбудована → довідка через help cd $ type ls ls is aliased to `ls --color=auto' # alias $ type cp cp is /usr/bin/cp # окрема програма → man cp Як читати man-сторінку Розділи сторінки: NAME (назва і опис), SYNOPSIS (синтаксис: [ ] — необов'язкове, ... — можна повторювати), DESCRIPTION (опції), EXAMPLES , SEE ALSO . Навігація така сама, як у less : пробіл — сторінка вниз, b — вгору, /слово — пошук, n — наступний збіг, q — вихід. Посібник поділено на секції : 1 — команди користувача, 5 — формати файлів, 8 — команди адміністратора. man passwd покаже команду, а man 5 passwd — формат файла /etc/passwd . Пастки тесту <command> /? — це довідка у Windows (cmd), у Linux /? сприйметься як аргумент-шлях. <command> ? — у bash ? є шаблоном «один будь-який символ», а не запитом довідки. Команд guide і manual у Linux немає. Правильні способи: man , --help , help (для вбудованих), info , whatis , apropos ."}, {"title": "Лекція 2 · Linux: командний рядок, файлова система, користувачі, права, процеси", "section": "Структура каталогів (FHS)", "url": "lectures/week-1/lecture-2.html#fs", "text": "Структура каталогів (FHS) У Linux «майже все — файл»: звичайні файли, каталоги, пристрої ( /dev/sda ), інформація про процеси ( /proc ), навіть більшість команд — програми-файли. Розташування каталогів описує стандарт FHS (Filesystem Hierarchy Standard) , тому на будь-якому дистрибутиві конфіги шукають в одному місці. Одне дерево від кореня. Конфіги шукайте в /etc , логи — у /var/log , сайти Apache — у /var/www/html . Каталог Що там лежить Приклади / Корінь (root directory) — початок усього дерева. Не плутати з /root — /bin Основні виконувані файли (binaries) для всіх користувачів ls , cp , cat , bash /sbin Системні програми для адміністрування (system binaries), зазвичай потрібен root fdisk , reboot , ip , mkfs /usr/bin , /usr/sbin Більшість звичайних програм користувача і адміністратора python3 , git , vim , sshd /usr/local/bin Програми, встановлені вручну адміністратором (не пакетним менеджером) самостійно зібрані утиліти /usr/share Спільні (shared) файли, незалежні від архітектури : документація, man-сторінки, іконки, локалізації /usr/share/man , /usr/share/doc /lib , /usr/lib , /lib64 Спільні бібліотеки (shared libraries .so ) і модулі ядра libc.so.6 , /lib/modules /etc Системні конфігураційні файли (текстові) /etc/passwd , /etc/hosts , /etc/ssh/sshd_config , /etc/nginx/ /home Домашні каталоги звичайних користувачів /home/student /root Домашній каталог користувача root /root/.bashrc /var Змінні (variable) дані, що ростуть під час роботи /var/log — логи, /var/www — сайти, /var/lib/mysql — дані БД, /var/cache , /var/spool /tmp Тимчасові файли, часто очищаються при перезавантаженні; на каталозі стоїть sticky bit — /dev Файли пристроїв (devices) /dev/sda — диск, /dev/null — «чорна діра», /dev/zero , /dev/random /proc Віртуальна ФС: інформація про процеси і ядро «на льоту», на диску не займає місця /proc/cpuinfo , /proc/meminfo , /proc/1234/ /sys Віртуальна ФС з інформацією про пристрої і драйвери /sys/class/net /boot Файли завантаження: ядро, initramfs, завантажувач GRUB vmlinuz-6.8.0 /opt Додаткове (optional) стороннє ПЗ, що ставиться цілим пакетом /opt/google/chrome /mnt , /media Точки монтування: тимчасово вручну / знімні носії /media/usb /srv Дані служб, як"}, {"title": "Лекція 2 · Linux: командний рядок, файлова система, користувачі, права, процеси", "section": "Шляхи: абсолютні, відносні, . , .. , ~", "url": "lectures/week-1/lecture-2.html#paths", "text": "Шляхи: абсолютні, відносні, . , .. , ~ Абсолютний шлях починається з / і описує розташування від кореня — він однаковий, хоч би де ви були: /home/user1/docs/cv.txt . Відносний шлях не починається з / і рахується від поточного каталогу : якщо ви в /home/user1 , то docs/cv.txt — той самий файл. Позначення Значення Приклад (поточний каталог /home/user1/docs ) . поточний каталог ./script.sh = /home/user1/docs/script.sh .. батьківський каталог (на рівень вище) .. = /home/user1 , ../.. = /home ~ домашній каталог поточного користувача (значення $HOME ) ~/data = /home/user1/data ~user2 домашній каталог іншого користувача ~user2 = /home/user2 - (лише в cd ) попередній каталог, де ви були cd - — повернутися назад / корінь cd / Кожен каталог фізично містить записи . і .. — їх видно в ls -a . Тому cd . нічого не змінює (переходить у той самий каталог), а cd .. піднімається на рівень вище. Скісна риска в кінці ( ./ , ../ ) лише підкреслює, що це каталог: cd ./ = cd . , cd ../ = cd .. . Навігація: pwd і cd Команда Результат pwd надрукувати поточний каталог (print working directory) cd (без аргументів), cd ~ , cd $HOME перейти в домашній каталог cd /etc за абсолютним шляхом cd docs = cd ./docs у підкаталог поточного cd .. / cd ../.. на один / два рівні вгору cd ../user2 у сусідній каталог (з /home/user1 в /home/user2 ) cd - повернутися в попередній каталог Розбір питання: «перейти в каталог user2 з домашнього каталогу user1» Ви в /home/user1 , доступ до /home/user2 є. Спрацюють усі ці варіанти, бо вони ведуть в одне місце різними шляхами: cd /home/user2 # абсолютний шлях cd ../user2 # відносний: вгору до /home, потім у user2 cd ~user2 # домашній каталог користувача user2 cd ~/../user2 # ~ = /home/user1, далі вгору і в user2 Не спрацюють: cd user2 (шукає /home/user1/user2 ), cd /user2 (шукає в корені), cd ..\\user2 (зворотна риска — синтаксис Windows; bash прибере \\ як екранування і шукатиме ..user2 ), cd../user2 без пробілу (bash шукатиме команду з назвою cd../user2 і видасть command not found )."}, {"title": "Лекція 2 · Linux: командний рядок, файлова система, користувачі, права, процеси", "section": "Перегляд вмісту каталогу: ls у деталях", "url": "lectures/week-1/lecture-2.html#ls", "text": "Перегляд вмісту каталогу: ls у деталях $ ls -l drwxr-xr-x 2 student devs 4096 Mar 3 10:15 docs -rw-r--r-- 1 student devs 220 Mar 3 10:02 notes.txt lrwxrwxrwx 1 student devs 9 Mar 3 10:20 last -> notes.txt #│└───┬───┘ │ └──┬──┘ └┬─┘ └┬─┘ └────┬────┘ └──┬──┘ #│ права │ власник група розмір дата зміни ім'я #тип кількість жорстких посилань Опція Що робить -l довгий формат: тип, права, посилання, власник, група, розмір, дата, ім'я -a показати всі файли, включно з прихованими (на . ) і записами . та .. -A приховані теж, але без . і .. -h розміри у зручному вигляді (K, M, G) — разом з -l : ls -lh -R рекурсивно: вміст усіх підкаталогів -d показати сам каталог, а не його вміст: ls -ld /etc -t / -S сортувати за часом зміни / за розміром (найновіші/найбільші першими) -r зворотний порядок сортування: ls -ltr — найновіші внизу -i показати номер inode -1 по одному імені в рядку -F додати позначку типу: / каталог, * виконуваний, @ посилання -p додати / лише до каталогів -n як -l , але UID/GID числами -s розмір у блоках -X сортувати за розширенням --color=auto кольори за типами (часто вже в alias) Типові задачі з ls ls # файли й каталоги поточного каталогу (без прихованих) ls -la ~ # усе в домашньому, з прихованими і деталями ls /etc # вміст іншого каталогу ls F* # імена, що починаються з великої F ls [Ff]* # з F або f ls *.log # закінчуються на .log ls -d */ # лише каталоги ls -l | grep '^d' # лише каталоги (рядки, що починаються з d) ls -l | grep '^-' # лише звичайні файли ls -p | grep -v / # лише файли (прибрати рядки з / у кінці) ls -lhS # за розміром, у зручних одиницях ls -ltr /var/log # найсвіжіші логи внизу Пастки тесту з ls «Показати лише файли і каталоги» — звичайний ls (без -a , щоб не було прихованих і службових . / .. ). Якщо треба розрізнити тип — ls -F або ls -l . «Файли на літеру F» — ls F* , але не ls *F (це «закінчуються на F»), не ls F? (рівно два символи) і не ls -F (це опція позначення типів). У Windows аналог — dir ; у Linux такої команди за замовчуванням або немає, або вона не є стандартною відповіддю."}, {"title": "Лекція 2 · Linux: командний рядок, файлова система, користувачі, права, процеси", "section": "Шаблони імен (globbing) і розкриття фігурних дужок", "url": "lectures/week-1/lecture-2.html#globs", "text": "Шаблони імен (globbing) і розкриття фігурних дужок Шаблони розкриває оболонка ще до запуску команди: ls *.txt перетворюється на ls a.txt b.txt c.txt . Тому шаблони працюють з будь-якою командою: cp , rm , mv , cat . Шаблон Відповідає Приклад Збігається / ні * будь-яка кількість будь-яких символів (і нуль) F* F , File , F1.txt / file ? рівно один будь-який символ file?.txt file1.txt / file10.txt [abc] один символ з переліку [Ff]* File , file [a-z] , [0-9] один символ з діапазону log[0-9].txt log7.txt / logA.txt [!a] або [^a] один символ, крім указаних [!.]* імена, що не починаються з крапки {a,b,c} не шаблон, а розкриття : генерує всі варіанти, навіть якщо файлів немає mkdir {src,docs} створить обидва каталоги {1..5} послідовність touch f{1..3}.txt f1.txt f2.txt f3.txt * не збігається з прихованими файлами (на крапку). rm * не видалить .env . Якщо жоден файл не збігся, bash передає шаблон як є: ls *.xyz → No such file or directory . У лапках шаблони не розкриваються: ls \"*.txt\" шукає файл, ім'я якого буквально *.txt . Тому find -name \"*.txt\" пишуть у лапках — щоб шаблон отримав find , а не оболонка."}, {"title": "Лекція 2 · Linux: командний рядок, файлова система, користувачі, права, процеси", "section": "Створення файлів і каталогів", "url": "lectures/week-1/lecture-2.html#create", "text": "Створення файлів і каталогів Порожній файл: шість способів Команда Що відбувається Якщо файл уже існує touch text.t створює порожній файл вміст не чіпає, лише оновлює час доступу і зміни > text.t перенаправлення «нічого» у файл обнуляє вміст : > text.t вбудована команда : нічого не друкує → порожній файл обнуляє cat /dev/null > text.t копіює вміст «порожнього пристрою» обнуляє cp /dev/null text.t копіює порожній пристрій як файл обнуляє echo -n > text.t -n — без символу нового рядка обнуляє. Без -n файл матиме 1 байт ( \\n ) Не створюють файл: cat text.t (лише читає існуючий), new text.t , create text.t (таких команд немає), mkdir text.t (створить каталог з такою назвою), echo text.t (надрукує рядок на екран). mkdir : каталоги Команда Результат mkdir data = mkdir ./data каталог data у поточному каталозі mkdir ~/data , mkdir $HOME/data у домашньому каталозі, хоч би де ви були mkdir -p ~/data/info -p (parents) : створити весь ланцюжок; якщо data ще немає — створить і його. Без помилки, якщо каталог уже є mkdir data/info (без -p ) помилка No such file or directory , якщо data не існує mkdir -m 700 secret -m (mode) : одразу задати права (тут rwx------ ), не чекаючи chmod mkdir -v a b c -v (verbose) : повідомляти про кожен створений каталог; кілька аргументів — кілька каталогів mkdir -p project/{src,tests,docs} три підкаталоги одним рухом (розкриття фігурних дужок) Розбір двох питань тесту «Створити каталог data з поточного каталогу» : правильні mkdir data і mkdir ./data . mkdir /data створить його в корені (і без прав root не вийде), md data — команда Windows, mkdir -data сприйметься як набір опцій. «Створити підкаталоги data/info з домашнього каталогу» : mkdir -p data/info (якщо ви вже вдома) або mkdir -p ~/data/info (звідки завгодно). Варіант без -p спрацює лише тоді, коли data вже існує; mkdir data info створить два окремі каталоги поруч, а не вкладені."}, {"title": "Лекція 2 · Linux: командний рядок, файлова система, користувачі, права, процеси", "section": "Копіювання, переміщення, перейменування", "url": "lectures/week-1/lecture-2.html#copy", "text": "Копіювання, переміщення, перейменування cp — копіювати cp text.t info.t # копія файла під новим іменем; text.t лишається cp text.t ~/backup/ # копія в інший каталог з тим самим іменем cp a.txt b.txt docs/ # кілька файлів у каталог (останній аргумент — каталог) cp -r project project_bak # каталог з усім вмістом (-r або -R, recursive) cp -i text.t info.t # -i: спитати перед перезаписом існуючого info.t cp -n text.t info.t # -n: ніколи не перезаписувати cp -u src/* dst/ # -u: копіювати, лише якщо джерело новіше cp -p config.ini /tmp/ # -p: зберегти права, власника, час cp -a /var/www /backup/www # -a (archive) = -r + -p + посилання як посилання: для бекапів cp -v *.conf /etc/app/ # -v: друкувати, що скопійовано Без -r каталог не копіюється: cp: -r not specified; omitting directory . Існуючий файл призначення cp перезаписує мовчки . Інші способи отримати копію вмісту: cat text.t > info.t (вміст переходить, але права і час — ні; новий файл отримає типові права), dd if=text.t of=info.t , rsync text.t info.t . А от copy — команда Windows; mv перемістить, а не скопіює; ln створить посилання, а не незалежну копію. mv — перемістити або перейменувати У Linux немає окремої команди «перейменувати»: перейменування — це переміщення в той самий каталог під новим іменем. mv text.t info.t # перейменувати: text.t зникає, з'являється info.t mv text.t ~/ # перенести в домашній каталог (ім'я лишається) mv text.t $HOME/ # те саме через змінну mv text.t /home/user/ # те саме абсолютним шляхом (якщо ваш логін user) mv text.t ~/notes.txt # перенести і одразу перейменувати mv *.jpg photos/ # кілька файлів у каталог mv old_dir new_dir # каталоги переміщуються без -r mv -i a b # спитати перед перезаписом mv -n a b # не перезаписувати Якщо призначення — існуючий каталог , файл переїде всередину. Якщо такого каталогу немає — файл буде перейменовано. Тому mv text.t backup дає різний результат залежно від того, чи є каталог backup . Скісна риска в кінці ( backup/ ) захищає: якщо каталогу немає, буде помилка, а не перейменування. У межах однієї файлової системи mv не копіює дані, а лише змінює запис у каталозі, тому навіть гігабайтний файл переміщується миттєво. rename існує як окрема утиліта дл"}, {"title": "Лекція 2 · Linux: командний рядок, файлова система, користувачі, права, процеси", "section": "Видалення: rm , rmdir і всі сценарії з тесту", "url": "lectures/week-1/lecture-2.html#delete", "text": "Видалення: rm , rmdir і всі сценарії з тесту У терміналі немає кошика. Видалений файл зникає одразу, тому опції rm треба знати точно. Опція Значення -r , -R recursive : видаляти каталоги разом із вмістом -f force : не питати підтверджень, мовчати про неіснуючі файли, видаляти захищені від запису (якщо є право на каталог) -i interactive : питати про кожен файл -I спитати один раз, якщо файлів більше трьох або є -r -d видаляти порожні каталоги (як rmdir ) -v друкувати кожен видалений файл rmdir видаляє лише порожній каталог; якщо в ньому щось є — Directory not empty . rmdir -p a/b/c видалить c , потім b , потім a , якщо всі вони стануть порожніми. Задача Правильно Чому схожі варіанти не підходять Видалити всі файли з каталогу data rm data/* , rm -f data/* rm data — помилка (це каталог). Підкаталоги без -r не видаляться, з'явиться повідомлення про них. Приховані файли * не зачепить Видалити весь вміст data (з підкаталогами), сам каталог залишити rm -r data/* , rm -rf data/* ; разом із прихованими — find data -mindepth 1 -delete rm -r data видалить і сам каталог. rm data/* без -r не видалить підкаталоги Видалити порожній каталог data з домашнього rmdir ~/data , rm -d ~/data , rm -r ~/data rm ~/data без опцій — Is a directory . rmdir для непорожнього — помилка Видалити непорожній каталог data з домашнього rm -r ~/data , rm -rf ~/data , rm -R ~/data rmdir ~/data не спрацює. rm -r ~/data/* очистить вміст, але залишить каталог. rm -i ~/data без -r — Is a directory Видалити всі файли в поточному каталозі rm * , rm ./* , rm -f * rm . — помилка (не можна видалити . ). rm -r * зачепить і підкаталоги — це вже «все», а не «файли» Обережно rm -rf з помилкою в шляху — класична катастрофа. Пробіл у rm -rf / tmp/x видаляє корінь. Звичка: спочатку ls з тим самим шаблоном, потім rm . У скриптах — rm -rf \"${DIR:?}/\"* : якщо змінна порожня, bash зупиниться замість rm -rf /* ."}, {"title": "Лекція 2 · Linux: командний рядок, файлова система, користувачі, права, процеси", "section": "Перегляд вмісту файлів", "url": "lectures/week-1/lecture-2.html#view", "text": "Перегляд вмісту файлів Команда Що робить Корисні опції cat file виводить весь файл на екран (concatenate — також склеює кілька файлів: cat a b > ab ) -n номери рядків, -A показати невидимі символи tac file те саме, але рядки у зворотному порядку — less file посторінковий перегляд з прокруткою вгору-вниз і пошуком; не читає весь файл одразу, тому підходить для гігабайтних логів пробіл / b , /текст , n , G у кінець, g на початок, q вихід; less +F — як tail -f more file старший посторінковий переглядач: в основному вниз пробіл — сторінка, q — вихід head file перші 10 рядків -n 20 , -c 100 (байти) tail file останні 10 рядків -n 50 ; -f стежити за файлом наживо; -F — те саме, але переживе ротацію логу nl file виводить з номерами рядків — wc file рахує рядки, слова, байти -l рядки, -w слова, -c байти file name визначає тип вмісту — cat text.t # показати вміст less /var/log/syslog # гортати великий лог head -n 5 /etc/passwd # перші 5 рядків tail -n 100 -f /var/log/nginx/access.log # останні 100 і далі наживо; вихід Ctrl+C sed -n '10,20p' file # рядки з 10 по 20 head -n 20 file | tail -n 11 # те саме без sed wc -l /etc/passwd # скільки облікових записів Пастка: echo не читає файли echo text.t друкує рядок «text.t», а не вміст файла. Вміст покажуть cat , less , more (а також head / tail частково). type text.t у Windows показує вміст, а в bash повідомить, що такої команди немає. Текстові редактори в терміналі На сервері графічного редактора немає, тож треба вміти хоча б відкрити, змінити і зберегти файл. nano — простий nano file — відкрити редагуєте одразу Ctrl + O , Enter — зберегти Ctrl + X — вийти підказки внизу екрана ( ^ = Ctrl) vi / vim — є всюди vi file — відкрити в командному режимі i — режим вставки, редагуєте Esc — назад у командний :w зберегти, :q вийти, :wq або :x — обидва, :q! — вийти без збереження dd — видалити рядок, /текст — пошук, u — скасувати"}, {"title": "Лекція 2 · Linux: командний рядок, файлова система, користувачі, права, процеси", "section": "Inode, жорсткі й символічні посилання", "url": "lectures/week-1/lecture-2.html#links", "text": "Inode, жорсткі й символічні посилання Щоб зрозуміти посилання, треба знати, як файл зберігається на диску. Файл складається з трьох частин: Блоки даних — сам вміст. Inode (index node) — службовий запис із номером: розмір, власник, права, час, адреси блоків даних і лічильник посилань . Імені файла в inode немає . Запис у каталозі — пара «ім'я → номер inode». Каталог — це просто таблиця таких пар. Жорстке посилання — друге ім'я того самого inode. Символічне — окремий маленький файл, у якому записано шлях до іншого імені. Синтаксис: спочатку оригінал, потім посилання ln text.t text.lnk # ЖОРСТКЕ посилання text.lnk на text.t ln -s text.t text.lnk # СИМВОЛІЧНЕ (soft) посилання text.lnk → text.t ln -s /opt/app/v2 current # типовий прийом: current вказує на активну версію ln -sf /opt/app/v3 current # -f: перезаписати існуюче посилання ls -li # -i покаже номери inode: у жорстких посилань вони однакові readlink -f current # куди насправді вказує символічне посилання unlink text.lnk # видалити посилання (або просто rm text.lnk) Запам'ятати порядок допомагає cp : «що» → «куди». ln text.lnk text.t з переставленими аргументами спробує створити text.t як посилання на неіснуючий text.lnk і видасть помилку (бо text.t вже існує або text.lnk немає). Властивість Жорстке ( ln ) Символічне ( ln -s ) Що це ще одне ім'я того самого inode окремий файл-«ярлик» зі шляхом Номер inode той самий, що в оригіналу власний Видалили оригінал дані живі, поки є хоч одне ім'я (лічильник посилань > 0) посилання «зламане» (dangling), вказує в нікуди Між файловими системами / розділами ні так На каталог ні (заборонено) так Вигляд у ls -l звичайний файл, лічильник посилань 2+ l на початку і name -> target Права спільні з оригіналом (це той самий inode) завжди rwxrwxrwx , реально діють права цілі Тепер зрозуміло, чому в ls -l є колонка «кількість посилань»: для каталогу вона дорівнює 2 + кількість підкаталогів (сам запис, запис . всередині, і .. у кожному підкаталозі)."}, {"title": "Лекція 2 · Linux: командний рядок, файлова система, користувачі, права, процеси", "section": "Пошук файлів: find , locate , which , whereis", "url": "lectures/week-1/lecture-2.html#find", "text": "Пошук файлів: find , locate , which , whereis find — пошук обходом дерева Синтаксис: find [де шукати] [умови] [дія] . find реально обходить каталоги, тому знаходить усе актуальне, але на всьому диску працює повільно. Умова / дія Значення Приклад -name ім'я за шаблоном, з урахуванням регістру find / -name text.t , find . -name \"*.log\" -iname те саме без урахування регістру find . -iname \"readme*\" -type f / d / l лише файли / каталоги / посилання find /etc -type d -name \"ssh*\" -size розмір: +100M більше, -1k менше find /var -size +500M -mtime , -mmin змінено N днів / хвилин тому ( -7 — за останні 7) find /var/log -mtime +30 -user , -group за власником / групою find /home -user anna -perm за правами find / -perm -4000 — файли з SUID -empty порожні файли й каталоги find . -empty -delete -maxdepth N не глибше N рівнів find . -maxdepth 1 -type f — лише файли поточного каталогу -path шаблон для усього шляху , а не імені find / -path \"*/conf/*.xml\" -exec cmd {} \\; виконати команду для кожного знайденого ( {} — ім'я) find . -name \"*.tmp\" -exec rm {} \\; -delete видалити знайдене find /tmp -mtime +7 -delete find / -name text.t 2>/dev/null # по всій ФС, без засмічення «Permission denied» find . -name text.t # у поточному каталозі та всіх підкаталогах find ~ -type f -name \"*.pdf\" -size +10M find /var/log -name \"*.gz\" -mtime +30 -delete find . -type f -name \"*.sh\" -exec chmod +x {} \\; Чому find / -path text.t нічого не знайде -path порівнює шаблон з повним шляхом, наприклад /home/anna/text.t . Рядок text.t без зірочки ніколи не дорівнює шляху, що починається з / . Працювало б find / -path \"*/text.t\" . Для пошуку за іменем потрібен -name . locate — пошук у базі locate text.t шукає не на диску, а в заздалегідь створеній базі імен (оновлюється щодня через cron або вручну sudo updatedb ). Тому працює миттєво, але може не знайти файл, створений після останнього оновлення бази, і показати вже видалений. locate шукає підрядок у повному шляху: locate \"text.t\" знайде і /home/a/text.t , і /tmp/mytext.txt . На мінімальних системах пакет ( mlocate / plocate ) треба встановити окремо. Де лежить програма: which , whereis , type Команда Що шукає Приклад виводу which python3 який виконуваний"}, {"title": "Лекція 2 · Linux: командний рядок, файлова система, користувачі, права, процеси", "section": "Пошук тексту у файлах: grep", "url": "lectures/week-1/lecture-2.html#grep", "text": "Пошук тексту у файлах: grep grep шаблон файли друкує рядки, де є збіг. Шаблон — регулярний вираз. Опція Значення -i без урахування регістру -r / -R рекурсивно по каталогах -n номери рядків -v інвертувати: рядки без збігу -c лише кількість рядків зі збігом -l лише імена файлів, де є збіг -w лише ціле слово ( -w cat не знайде category ) -E розширені регулярні вирази ( | , + , ? , () ), колишній egrep -o друкувати лише збіг, а не весь рядок -A 3 / -B 3 / -C 3 3 рядки після / до / навколо збігу Регулярний вираз Значення Приклад ^ / $ початок / кінець рядка grep '^root' /etc/passwd ; grep -v '^#' — прибрати коментарі . будь-який один символ h.t → hat, hot * попередній символ 0 або більше разів (не те саме, що * у шаблонах імен!) ab*c → ac, abc, abbbc [abc] , [0-9] один символ з набору [0-9][0-9]* — число a|b (з -E ) або grep -E 'error|fail' grep -rin \"error\" /var/log # усі помилки в логах, з файлом і номером рядка grep -c \"Failed password\" /var/log/auth.log # скільки невдалих входів grep -v '^#' /etc/ssh/sshd_config | grep -v '^$' # конфіг без коментарів і порожніх рядків ps aux | grep nginx # фільтр виводу іншої команди grep -l \"DB_PASSWORD\" -r /var/www # у яких файлах є пароль БД"}, {"title": "Лекція 2 · Linux: командний рядок, файлова система, користувачі, права, процеси", "section": "Змінні середовища і PATH", "url": "lectures/week-1/lecture-2.html#env", "text": "Змінні середовища і PATH Змінна середовища — пара «ім'я = значення», яку оболонка передає кожній запущеній програмі. Ім'я пишуть без $ , а значення отримують з $ . Змінна Значення Приклад PATH список каталогів через : , де оболонка шукає команди /usr/local/bin:/usr/bin:/bin HOME домашній каталог /home/anna USER ім'я користувача anna SHELL оболонка входу /bin/bash PWD / OLDPWD поточний / попередній каталог /etc LANG мова і кодування en_US.UTF-8 PS1 формат запрошення \\u@\\h:\\w\\$ echo $PATH # показати значення PATH echo \"$HOME\" # у подвійних лапках змінна підставляється echo '$HOME' # в одинарних — ні, надрукує $HOME буквально printenv PATH # те саме, без $ env # усі змінні середовища set # усі змінні оболонки і функції MYVAR=hello # змінна оболонки (без пробілів навколо =) export MYVAR # зробити її змінною середовища для дочірніх програм export PATH=\"$PATH:$HOME/bin\" # додати каталог у кінець PATH unset MYVAR # видалити змінну Як працює пошук команди через PATH Ви вводите python3 . Bash перевіряє, чи це alias, функція або вбудована команда. Якщо ні — проходить каталогами з PATH зліва направо: /usr/local/bin/python3 ? /usr/bin/python3 ? Запускає перший знайдений . Не знайшов — command not found . Поточний каталог . у PATH навмисно не входить (інакше зловмисник міг би підкласти у ваш каталог файл ls ). Тому свій скрипт запускають з явним шляхом: ./script.sh , /home/anna/script.sh або bash script.sh . Де зберігати налаштування назавжди export діє лише до закриття терміналу. Щоб зберегти, додайте рядок у ~/.bashrc (для інтерактивних оболонок) або ~/.profile / ~/.bash_profile (для оболонки входу) і перечитайте файл: source ~/.bashrc (або . ~/.bashrc ). Для всіх користувачів — /etc/environment і /etc/profile.d/*.sh . Пастка: синтаксис змінних у різних ОС Linux/bash: echo $PATH або echo ${PATH} . Windows cmd: echo %PATH% . PowerShell: $env:PATH . Варіанти echo %PATH , echo #PATH (після # — коментар, буде порожній рядок), echo /PATH/ (просто текст) у bash надрукують не значення змінної. Псевдоніми та історія alias ll='ls -alF' # створити alias (до кінця сесії; назавжди — у ~/.bashrc) alias # показати всі unalias ll # прибрати history # пронумерований список команд !42 # по"}, {"title": "Лекція 2 · Linux: командний рядок, файлова система, користувачі, права, процеси", "section": "Потоки, pipes і перенаправлення", "url": "lectures/week-1/lecture-2.html#pipes", "text": "Потоки, pipes і перенаправлення Кожна програма в Linux при запуску отримує три відкриті потоки з номерами (файлові дескриптори): 0 · stdin Стандартний вхід Звідки програма читає дані. За замовчуванням — клавіатура. 1 · stdout Стандартний вивід Куди пише звичайний результат. За замовчуванням — екран. 2 · stderr Потік помилок Куди пише повідомлення про помилки. Теж екран, але це окремий потік, тому його можна перенаправити окремо. Два механізми. Pipe з'єднує програми, перенаправлення змінює, куди йде результат. Запис Що робить cmd1 | cmd2 pipe : stdout cmd1 → stdin cmd2 . Обидві програми працюють одночасно cmd > f = cmd 1> f stdout у файл; файл створюється або перезаписується cmd >> f stdout дописується в кінець файла cmd < f stdin береться з файла: mysql shop < dump.sql , wc -l < file cmd 2> f лише помилки (stderr) у файл; звичайний вивід лишається на екрані cmd 2>> f помилки дописуються у файл cmd > f 2>&1 stdout у файл, а stderr — туди ж, куди зараз іде stdout. Порядок важливий cmd &> f скорочення bash для «обидва потоки у файл» cmd 2> /dev/null викинути помилки («чорна діра») cmd > /dev/null 2>&1 повністю беззвучний запуск (типово в cron) cmd | tee f / tee -a f показати на екрані і записати (дописати) у файл cmd 2>&1 | grep err пропустити через pipe і помилки теж (pipe за замовчуванням бере лише stdout) Чому порядок у > f 2>&1 важливий 2>&1 означає «направ потік 2 туди, куди зараз указує потік 1». Bash читає перенаправлення зліва направо: ls /etc /nope > out.txt 2>&1 # 1 → файл; потім 2 → туди ж (файл). Обидва у файлі ✔ ls /etc /nope 2>&1 > out.txt # 2 → куди зараз 1 (екран); потім 1 → файл. Помилка на екрані ✘ Що означає «Redirect 2>abc» Потік помилок (stderr, дескриптор 2) записується у файл з назвою abc , файл перезаписується. Звичайний вивід (stdout) не змінюється і йде на екран. Це не «записати у файл 2», не «дописати» (для дописування — 2>> ) і не «вивід на вхід команди abc» (це був би pipe). Here-document і here-string cat > /etc/motd <<EOF # here-doc: кілька рядків на stdin до слова EOF Welcome to $HOSTNAME Maintenance: Sunday 02:00 EOF grep -c a <<< \"banana\" # here-string: рядок на stdin → 1"}, {"title": "Лекція 2 · Linux: командний рядок, файлова система, користувачі, права, процеси", "section": "Ланцюжки команд і коди завершення", "url": "lectures/week-1/lecture-2.html#chains", "text": "Ланцюжки команд і коди завершення Кожна команда, завершуючись, повертає код виходу (exit status): 0 — успіх, будь-яке інше число (1–255) — помилка. Останній код зберігається в $? . ls /etc > /dev/null; echo $? # 0 ls /nope 2> /dev/null; echo $? # 2 grep -q root /etc/passwd; echo $? # 0 — знайдено (-q: нічого не друкувати) Запис Коли виконується cmd2 Дані передаються? cmd1 ; cmd2 завжди, після завершення cmd1 ні cmd1 && cmd2 лише якщо cmd1 успішна (код 0) — логічне «І» ні cmd1 || cmd2 лише якщо cmd1 завершилась помилкою — логічне «АБО» ні cmd1 & cmd2 одразу: cmd1 запускається у фоні, cmd2 — паралельно ні cmd1 | cmd2 одночасно так : stdout → stdin mkdir -p /opt/app && cd /opt/app # перейти, тільки якщо каталог створено ping -c1 db.local >/dev/null || echo \"БД недоступна\" apt update && apt upgrade -y # оновити, тільки якщо список пакетів отримано make build && echo OK || echo FAIL # типова конструкція «успіх / провал» (cd /tmp && tar czf backup.tgz data) # дужки: підоболонка, ваш поточний каталог не зміниться Фонові задачі ./long_job.sh & # запустити у фоні; bash надрукує [1] 12345 (номер задачі і PID) jobs # список фонових задач поточної оболонки fg %1 # повернути задачу 1 на передній план bg %1 # продовжити призупинену (Ctrl+Z) задачу у фоні nohup ./job.sh > job.log 2>&1 & # не завершуватись при закритті терміналу"}, {"title": "Лекція 2 · Linux: командний рядок, файлова система, користувачі, права, процеси", "section": "Обробка тексту в конвеєрах", "url": "lectures/week-1/lecture-2.html#text", "text": "Обробка тексту в конвеєрах Сила командного рядка — у поєднанні маленьких програм. Кожна робить одну річ і читає stdin, тому їх можна ланцюжити. Команда Що робить Приклад sort сортує рядки; -n числово, -r зворотно, -k2 за 2-ю колонкою, -t: роздільник, -u унікальні sort -t: -k3 -n /etc/passwd uniq прибирає сусідні повтори (тому спочатку sort ); -c рахує sort | uniq -c cut вирізає колонки: -d роздільник, -f номери полів, -c символи cut -d: -f1,7 /etc/passwd tr замінює або видаляє символи tr 'a-z' 'A-Z' , tr -d '\\r' sed потоковий редактор: заміна, видалення рядків sed 's/http:/https:/g' file ; sed -i змінює файл на місці awk обробка колонок, умови, підрахунки awk '{print $1}' access.log xargs перетворює рядки зі stdin на аргументи команди find . -name \"*.tmp\" | xargs rm diff різниця між файлами diff -u old.conf new.conf Розібраний приклад: 5 IP-адрес з найбільшою кількістю запитів awk '{print $1}' /var/log/nginx/access.log | sort | uniq -c | sort -rn | head -5 # │ перша колонка = IP │ групуємо │ рахуємо │ за спаданням │ топ-5 # Вивід: # 1532 203.0.113.7 # 877 198.51.100.23 # ... Ще кілька реальних конвеєрів cut -d: -f1 /etc/passwd | sort # усі користувачі за абеткою grep -v nologin /etc/passwd | cut -d: -f1 # користувачі, які можуть входити du -sh /var/* 2>/dev/null | sort -rh | head # найбільші каталоги у /var ps aux --sort=-%mem | head -6 # 5 процесів, що найбільше їдять пам'ять history | awk '{print $2}' | sort | uniq -c | sort -rn | head # ваші улюблені команди"}, {"title": "Лекція 2 · Linux: командний рядок, файлова система, користувачі, права, процеси", "section": "Користувачі та групи", "url": "lectures/week-1/lecture-2.html#users", "text": "Користувачі та групи Linux — багатокористувацька ОС: на одному сервері працюють люди і служби, і кожен процес виконується від імені певного користувача. Кожен користувач і група мають ім'я та числовий ідентифікатор ( UID / GID ). Ядро бачить лише числа, імена — для людей. Тип UID Призначення root 0 суперкористувач: обходить перевірки прав системні 1–999 (у RHEL 1–999, у Debian 100–999) облікові записи служб: www-data , nginx , mysql , sshd . Зазвичай без пароля і з оболонкою /usr/sbin/nologin звичайні 1000+ люди Користувач має одну основну (primary) групу — її отримують нові файли — і може мати кілька додаткових (secondary) . Три файли облікових записів Файл Вміст Хто читає /etc/passwd облікові записи (без паролів) усі (права 644 ) — програмам треба перетворювати UID на імена /etc/shadow хеші паролів і правила їх зміни лише root (права 640 або 000 ) /etc/group групи і їхні учасники усі Рядок /etc/passwd — 7 полів через двокрапку: anna:x:1001:1001:Anna Koval,,,:/home/anna:/bin/bash │ │ │ │ │ │ └ 7. оболонка входу │ │ │ │ │ └ 6. домашній каталог │ │ │ │ └ 5. коментар (GECOS): повне ім'я тощо │ │ │ └ 4. GID основної групи │ │ └ 3. UID │ └ 2. x = пароль винесено в /etc/shadow └ 1. ім'я користувача Рядок /etc/shadow : anna:$6$Qx9...$kP2...:19850:0:99999:7::: — ім'я, хеш пароля (префікс показує алгоритм: $6$ — SHA-512, $y$ — yescrypt, $5$ — SHA-256, $1$ — застарілий MD5; між $ — сіль), день останньої зміни (у днях від 1.01.1970), мін./макс. термін дії, попередження. ! або * на місці хеша — вхід паролем заблоковано. «Пароль у Linux шифрується і зберігається в…» Правильно: /etc/shadow . Точніше, там зберігається не зашифрований пароль, а його хеш із сіллю: розшифрувати назад неможливо, система порівнює хеш введеного пароля. /etc/passwd у сучасних системах містить лише x . /etc/password , /etc/users , /etc/secret — таких стандартних файлів немає; /etc/group — групи. Команди керування whoami # хто я id # uid=1001(anna) gid=1001(anna) groups=1001(anna),27(sudo) id vivek # UID, GID і всі групи іншого користувача groups anna # лише групи who / w # хто зараз у системі / і що робить last # історія входів sudo groupadd developers # створити групу sudo useradd -m -s /bin/bash -G"}, {"title": "Лекція 2 · Linux: командний рядок, файлова система, користувачі, права, процеси", "section": "Права доступу до файлів", "url": "lectures/week-1/lecture-2.html#perms", "text": "Права доступу до файлів Кожен файл має власника (u — user) , групу (g — group) і права для інших (o — others) . Для кожної категорії — три права: r (read, 4), w (write, 2), x (execute, 1). Число для категорії — сума прав. Як читати права. Три трійки rwx → три цифри. -rwxr-xr-- = 754 . Усі вісім комбінацій Цифра Двійково Права Значення 0 000 --- нічого 1 001 --x лише виконання 2 010 -w- лише запис 3 011 -wx запис + виконання 4 100 r-- лише читання 5 101 r-x читання + виконання 6 110 rw- читання + запис 7 111 rwx усе Що означають права для файла і для каталогу Право Для файла Для каталогу r читати вміст ( cat , cp ) бачити список імен ( ls ) w змінювати вміст створювати, видаляти, перейменовувати файли в каталозі (навіть чужі, якщо немає sticky bit) x запускати як програму входити ( cd ) і звертатися до файлів за іменем Наслідки, про які часто питають: видалити файл можна без права w на сам файл, якщо є w і x на каталог ( rm лише спитає підтвердження). «Темний каталог» chmod a-r+x darkcat : ls darkcat → Permission denied , але cat darkcat/known.txt працює, якщо знаєте ім'я. Для запуску скрипта потрібні і x , і r : інтерпретатор bash мусить прочитати текст. Бінарній програмі вистачає x . Розібрані приклади Число Рядок Типове використання 755 rwxr-xr-x каталоги, скрипти і програми: усі запускають, змінює лише власник 744 rwxr--r-- скрипт, який запускає лише власник , інші можуть читати 700 rwx------ приватний скрипт або каталог ( ~/.ssh ) 644 rw-r--r-- звичайні файли, вебсторінки 640 rw-r----- конфіг із паролем, який читає група служби 600 rw------- приватний SSH-ключ, файли з секретами 775 rwxrwxr-x спільний каталог команди 777 rwxrwxrwx усім усе — майже завжди помилка безпеки «Зробити script.sh виконуваним лише для власника» Аналізуйте кожну цифру окремо. 744 — власник rwx , решта лише r → ✔. 700 і chmod u+x (якщо в інших x не було) — теж ✔. 755 — x отримують група й інші → ✘. 777 → ✘. 144 — власник має лише x без r ; bash не зможе прочитати текст скрипта → ✘. 155 — у групи й інших є x → ✘. chmod : числова і символьна форма Символьна форма: хто ( u , g , o , a = усі) + дія ( + додати, - забрати, = встановити точно) + права ( r , w , x ). chmod 755 deploy.sh # числ"}, {"title": "Лекція 2 · Linux: командний рядок, файлова система, користувачі, права, процеси", "section": "Процеси: перегляд і керування", "url": "lectures/week-1/lecture-2.html#proc", "text": "Процеси: перегляд і керування Процес — запущена програма. Кожен має PID (ідентифікатор), PPID (PID батька), власника, стан і пріоритет. Перший процес системи — systemd (або init ) з PID 1; решта — його нащадки ( pstree покаже дерево). $ ps aux | head -3 USER PID %CPU %MEM VSZ RSS TTY STAT START TIME COMMAND root 1 0.0 0.3 167744 12800 ? Ss 09:12 0:02 /sbin/init www-data 812 0.3 1.2 220104 49152 ? S 09:13 0:10 nginx: worker process Команда Призначення ps aux (BSD-стиль) / ps -ef (System V) знімок усіх процесів. a — усіх користувачів, u — з власником і %CPU/%MEM, x — і без терміналу ps -u anna , ps -p 812 процеси користувача / конкретний PID top , htop інтерактивно в реальному часі. У top : P сорт. за CPU, M за пам'яттю, k вбити, q вихід pgrep nginx , pidof nginx знайти PID за іменем kill PID надіслати сигнал (за замовчуванням 15 SIGTERM — «завершись коректно») kill -9 PID SIGKILL — примусово, процес не може перехопити; файли можуть лишитися незбереженими killall nginx , pkill -f \"python app.py\" сигнал усім процесам за іменем / за командним рядком nice -n 10 cmd , renice 5 -p PID пріоритет від −20 (найвищий) до 19 (найнижчий) uptime час роботи і load average за 1, 5, 15 хв (середня кількість процесів, що чекають CPU; порівнюйте з кількістю ядер) Сигнал Номер Звідки Значення SIGHUP 1 kill -HUP «термінал закрито»; багато демонів (nginx) по ньому перечитують конфіг SIGINT 2 Ctrl + C переривання SIGKILL 9 kill -9 негайне знищення, не перехоплюється SIGTERM 15 kill без опцій ввічливе прохання завершитись SIGSTOP / SIGTSTP 19 / 20 Ctrl + Z (20) призупинити; продовжити — SIGCONT (18) Стани процесу в колонці STAT : R — виконується, S — спить (чекає події), D — непереривне очікування (зазвичай диск), T — зупинений, Z — зомбі (завершився, але батько не забрав код виходу)."}, {"title": "Лекція 2 · Linux: командний рядок, файлова система, користувачі, права, процеси", "section": "Пам'ять, диск і відомості про систему", "url": "lectures/week-1/lecture-2.html#mem", "text": "Пам'ять, диск і відомості про систему Оперативна пам'ять $ free -h total used free shared buff/cache available Mem: 7.7Gi 2.1Gi 1.2Gi 150Mi 4.4Gi 5.3Gi Swap: 2.0Gi 0B 2.0Gi free — зовсім не використана пам'ять. Вона мала, і це нормально: Linux використовує вільну пам'ять під кеш диска ( buff/cache ) і віддає її програмам за потреби. available — скільки реально можна віддати новим програмам. Саме на цю колонку дивіться, оцінюючи нестачу пам'яті. Swap — область підкачки на диску; активне використання swap означає, що RAM не вистачає. Команда Що показує про RAM free -h ( -m у МБ) підсумок: total / used / free / cache / available cat /proc/meminfo детальні лічильники ядра (MemTotal, MemAvailable, Cached…) top , htop рядки MiB Mem і MiB Swap у шапці + споживання кожним процесом vmstat 1 пам'ять, swap, CPU кожну секунду «Як переглянути стан RAM» Відповідь тесту — free . Також правильні за змістом top , vmstat , cat /proc/meminfo . Не підходять: mem (такої стандартної команди немає), ps (процеси, а не загальний стан пам'яті), more (переглядач тексту), man (довідка), df (диск, а не RAM). Диск Команда Що показує df -h місце на файлових системах (розділах): розмір, зайнято, вільно, точка монтування. df -i — вільні inode du -sh dir скільки займає каталог ; du -sh * — кожен елемент поточного каталогу lsblk дерево дисків і розділів mount , findmnt що куди змонтовано; постійні монтування — у /etc/fstab Відомості про систему Команда Що показує uname -a / uname -r ядро, архітектура, ім'я хоста / лише версія ядра cat /etc/os-release назва і версія дистрибутиву hostname , hostnamectl ім'я машини lscpu , cat /proc/cpuinfo , nproc процесор, кількість ядер date , timedatectl дата, час, часовий пояс"}, {"title": "Лекція 2 · Linux: командний рядок, файлова система, користувачі, права, процеси", "section": "Служби і логи (systemd)", "url": "lectures/week-1/lecture-2.html#services", "text": "Служби і логи (systemd) Демони (служби, що працюють у фоні: nginx, sshd, mysqld) у сучасних дистрибутивах запускає і контролює systemd . Опис служби — «юніт» ( /lib/systemd/system/nginx.service ). systemctl status nginx # стан, PID, останні рядки логу sudo systemctl start nginx # запустити зараз sudo systemctl stop nginx # зупинити sudo systemctl restart nginx # перезапустити (з розривом з'єднань) sudo systemctl reload nginx # перечитати конфіг без зупинки (якщо служба підтримує) sudo systemctl enable nginx # автозапуск при старті системи (enable --now — і запустити) sudo systemctl disable nginx # прибрати з автозапуску systemctl list-units --type=service --state=running journalctl -u nginx -f # лог служби наживо journalctl -p err -b # помилки з моменту завантаження dmesg | tail # повідомлення ядра (диски, драйвери, OOM killer) Не плутайте: start — запустити зараз , enable — запускати при завантаженні . На старих системах — service nginx start і chkconfig . Лог Що в ньому /var/log/syslog (Debian) / /var/log/messages (RHEL) загальні системні повідомлення /var/log/auth.log / /var/log/secure входи, sudo , SSH /var/log/nginx/ , /var/log/apache2/ , /var/log/httpd/ журнали вебсерверів ( access.log , error.log ) /var/log/dmesg , /var/log/kern.log ядро Щоб логи не заповнили диск, logrotate щодня перейменовує їх ( syslog.1 , syslog.2.gz …) і стискає старі."}, {"title": "Лекція 2 · Linux: командний рядок, файлова система, користувачі, права, процеси", "section": "Встановлення програм: пакетні менеджери", "url": "lectures/week-1/lecture-2.html#packages", "text": "Встановлення програм: пакетні менеджери Програми встановлюють з репозиторіїв — серверів дистрибутиву з перевіреними пакетами. Пакетний менеджер сам завантажує залежності . Встановлювати може лише root (через sudo ). Дія Debian / Ubuntu ( apt ) RHEL / CentOS / Fedora ( dnf , раніше yum ) Оновити список пакетів apt update dnf makecache (робиться автоматично) Оновити встановлені пакети apt upgrade dnf upgrade / yum update Встановити apt install nginx dnf install nginx Видалити / з конфігами apt remove nginx / apt purge nginx dnf remove nginx Пошук / інформація apt search , apt show dnf search , dnf info Встановлені apt list --installed , dpkg -l dnf list installed , rpm -qa Встановити локальний файл dpkg -i app.deb rpm -ivh app.rpm Конфіг репозиторіїв /etc/apt/sources.list , /etc/apt/sources.list.d/ /etc/yum.repos.d/ Пастка: apt update не оновлює програми, лише список доступних версій. Тому в скриптах пишуть apt update && apt install -y pkg . Нижчий рівень — dpkg / rpm — не розв'язує залежності сам."}, {"title": "Лекція 2 · Linux: командний рядок, файлова система, користувачі, права, процеси", "section": "Архіви і стиснення", "url": "lectures/week-1/lecture-2.html#archives", "text": "Архіви і стиснення tar склеює багато файлів в один архів (tape archive), а стиснення додається опцією. Опція tar Значення c / x / t create — створити / extract — розпакувати / list — переглянути вміст f file — далі ім'я архіву (ставлять останньою перед іменем) v verbose — друкувати файли z / j / J стиснення gzip ( .tar.gz , .tgz ) / bzip2 ( .tar.bz2 ) / xz ( .tar.xz ) -C dir розпакувати в указаний каталог tar -czvf site-backup.tar.gz /var/www/html # створити стиснений архів tar -tzvf site-backup.tar.gz # подивитися вміст, не розпаковуючи tar -xzvf site-backup.tar.gz -C /tmp/restore # розпакувати в /tmp/restore gzip big.log # стиснути файл → big.log.gz (оригінал зникає) gunzip big.log.gz # розпакувати (= gzip -d) zcat big.log.gz | grep ERROR # читати стиснений лог без розпакування zip -r site.zip site/ ; unzip site.zip"}, {"title": "Лекція 2 · Linux: командний рядок, файлова система, користувачі, права, процеси", "section": "Мережеві команди (детально — у лекції 6)", "url": "lectures/week-1/lecture-2.html#netcmd", "text": "Мережеві команди (детально — у лекції 6) Команда Призначення ip a ( ip addr show ) інтерфейси та IP-адреси (застаріле: ifconfig ) ip r таблиця маршрутизації, шлюз за замовчуванням ss -tulpn які порти слухаються і якими процесами (застаріле: netstat -tulpn ) ping -c 4 host перевірити досяжність (ICMP) curl -I https://site , wget URL HTTP-запит (лише заголовки) / завантажити файл dig site , nslookup site DNS-запит scp file user@host:/path , rsync -avz src/ host:dst/ копіювання по SSH; rsync передає лише зміни /etc/hosts , /etc/resolv.conf локальні імена / адреси DNS-серверів"}, {"title": "Лекція 2 · Linux: командний рядок, файлова система, користувачі, права, процеси", "section": "Вхід по SSH-ключах", "url": "lectures/week-1/lecture-2.html#ssh", "text": "Вхід по SSH-ключах SSH (Secure Shell) — протокол захищеного віддаленого доступу, типово TCP-порт 22 . Замінив незахищений Telnet (порт 23), який передавав паролі відкритим текстом. Використовує асиметричне шифрування : приватний ключ лишається у вас, публічний кладемо на сервер у ~/.ssh/authorized_keys . Пара ключів. Приватний ключ нікому не передаємо; на сервер потрапляє лише публічний. ssh-keygen -t ed25519 -C \"anna@laptop\" # сучасний тип ключа (або -t rsa -b 4096) ssh-copy-id user@192.168.0.10 # додати публічний ключ на сервер # те саме вручну: cat ~/.ssh/id_ed25519.pub | ssh user@192.168.0.10 \"mkdir -p ~/.ssh && cat >> ~/.ssh/authorized_keys\" ssh user@192.168.0.10 # вхід ssh -i ~/.ssh/deploy_key -p 2222 user@host # з указаним ключем і нестандартним портом ssh user@host 'df -h' # виконати одну команду віддалено Як це працює Клієнт підключається; сервер показує свій ключ хоста . При першому підключенні ви підтверджуєте його відбиток, і він записується в ~/.ssh/known_hosts . Якщо згодом ключ зміниться — SSH попередить про можливу атаку «людина посередині». Встановлюється зашифрований канал. Сервер перевіряє, чи є ваш публічний ключ в authorized_keys , і просить довести володіння приватним: клієнт підписує випадкові дані приватним ключем, сервер перевіряє підпис публічним. Сам приватний ключ мережею не передається. Права обов'язкові: chmod 700 ~/.ssh , chmod 600 ~/.ssh/id_ed25519 ~/.ssh/authorized_keys . Із ширшими правами SSH відмовиться використовувати ключ. Посилення сервера в /etc/ssh/sshd_config : PasswordAuthentication no , PermitRootLogin no , після змін — sudo systemctl reload sshd (не закриваючи поточну сесію, поки не перевірите вхід у новій). Щоб не вводити хост і ключ щоразу — ~/.ssh/config : Host web HostName 203.0.113.10 User deploy Port 2222 IdentityFile ~/.ssh/deploy_key # тепер просто: ssh web"}, {"title": "Лекція 2 · Linux: командний рядок, файлова система, користувачі, права, процеси", "section": "Шпаргалка пасток: Windows-синтаксис у тестах про Linux", "url": "lectures/week-1/lecture-2.html#traps", "text": "Шпаргалка пасток: Windows-синтаксис у тестах про Linux Багато неправильних варіантів у тестах — це справжні команди Windows. Вони виглядають знайомо, але в bash не працюють або роблять інше. Задача Linux (правильно) Windows cmd (пастка) список файлів ls dir копіювати cp copy , xcopy перемістити / перейменувати mv move , ren видалити файл / каталог rm / rmdir , rm -r del , erase / rd /s створити каталог mkdir md вміст файла cat , less , more type очистити екран clear cls довідка man cmd , cmd --help , help cmd /? змінна $PATH %PATH% роздільник шляху / \\ процеси / завершити ps , top / kill tasklist / taskkill мережеві налаштування ip a ( ifconfig ) ipconfig маршрут пакетів traceroute tracert Інші типові пастки: переставлені аргументи ( ln link target ), пропущений ключ ( mkdir без -p , rm без -r ), неіснуючі команди з «логічними» назвами ( mem , guide , create , rename як «стандартна» відповідь), шаблон у неправильному місці ( *F замість F* ) і плутанина $USER / $HOME ."}, {"title": "Лекція 2 · Linux: командний рядок, файлова система, користувачі, права, процеси", "section": "Типові помилки", "url": "lectures/week-1/lecture-2.html#mistakes", "text": "Типові помилки chmod 777 «щоб точно запрацювало». Це дає запис усім користувачам — діра в безпеці. Видавайте мінімум: файли 644, каталоги і скрипти 755, секрети 600, а власника задавайте через chown . У символьній формі a означає «інші». u — власник, g — група, o — інші, a — усі (all) одразу. usermod -G group user додає групу. Без -a він замінює список груп. Правильно: usermod -aG group user . Скрипт script.sh не запускається «бо нема .exe». Потрібен атрибут x ( chmod +x ) і шлях: ./script.sh — поточний каталог не входить у PATH . cmd1 && cmd2 або cmd1 ; cmd2 передає вивід першої команди другій. Дані передає лише | . Інші оператори тільки визначають, чи і коли запуститься друга команда. 2> file — «записати у файл 2». Цифра — номер потоку: 2> перенаправляє stderr (помилки). Усе разом — > file 2>&1 або &> file . rm -i data видалить каталог з підтвердженням. -i лише вмикає запитання. Для каталогу все одно потрібен -r (з вмістом) або -d / rmdir (порожній). rm -r data/* видаляє каталог data . Він видаляє вміст , а сам data лишається (і приховані файли теж). Каталог разом із вмістом — rm -r data . apt update оновлює програми. Він оновлює лише список пакетів. Програми оновлює apt upgrade . Мало «free» у free -h — сервер задихається. Linux тримає вільну пам'ять у кеші диска. Дивіться на available і на використання swap. kill -9 — звичайний спосіб зупинити процес. Спочатку kill PID (SIGTERM): процес закриє файли і з'єднання. -9 — останній засіб. Sticky bit ставиться як chmod g+t . Sticky bit — біт для «інших»: chmod +t dir (або o+t , числом — 1777 ). У ls -l видно t в останній позиції."}, {"title": "Лекція 3 · Bash: скрипти, змінні, умови, цикли та функції", "section": "Вступ", "url": "lectures/week-1/lecture-3.html", "text": ""}, {"title": "Лекція 3 · Bash: скрипти, змінні, умови, цикли та функції", "section": "Чого ви навчитесь", "url": "lectures/week-1/lecture-3.html#goals", "text": "Чого ви навчитесь Створити і запустити bash-скрипт (shebang, права, позиційні параметри). Правильно працювати зі змінними: присвоєння без пробілів, різниця \"подвійних\" і 'одинарних' лапок. Використовувати спецзмінні $0 $1 $# $@ $? $$ та підстановку команд. Писати умови if [ … ] з правильними операторами для чисел і рядків. Писати цикли for , while , until і функції з local -змінними. Розуміти різницю між ./script.sh , bash script.sh і source script.sh , коди виходу і «суворий режим» set -euo pipefail . Використовувати розкриття параметрів ( ${var:-default} , ${f%.txt} ), масиви, [[ ]] і (( )) . Читати файли рядок за рядком, розбирати опції через getopts , прибирати за собою через trap . Ставити скрипти в cron і писати практичні скрипти: бекап з ротацією, моніторинг диска, перевірку сайтів."}, {"title": "Лекція 3 · Bash: скрипти, змінні, умови, цикли та функції", "section": "Оболонки і чому bash", "url": "lectures/week-1/lecture-3.html#shells", "text": "Оболонки і чому bash Shell (оболонка) — програма, що приймає ваші команди і запускає їх. У Linux є багато оболонок: sh (Bourne), csh , ksh , tcsh , zsh , але найпопулярніша — bash (Bourne Again Shell) . Вона сумісна з sh , взяла найкраще з ksh і csh та відповідає стандарту POSIX . Bash чи Python? Питання з чату лекції. Bash «склеює» POSIX-утиліти ( grep , cp , systemctl …) і є майже в будь-якій системі, а Python може бути не встановлений (у мінімальних образах на кшталт Alpine навіть bash буває відсутній — там sh ). Для коротких сценаріїв розгортання — bash, для складної логіки й обробки даних — Python."}, {"title": "Лекція 3 · Bash: скрипти, змінні, умови, цикли та функції", "section": "Перший скрипт", "url": "lectures/week-1/lecture-3.html#first", "text": "Перший скрипт Перший рядок — shebang #!/bin/bash : він каже ОС, яким інтерпретатором виконувати файл. #!/bin/bash # hello.sh — коментар починається з # name=\"DevOps\" echo \"Hello, $name! Сьогодні: $(date +%F)\" chmod +x hello.sh # дати право на виконання ./hello.sh # запуск із поточного каталогу bash hello.sh # або явно через інтерпретатор"}, {"title": "Лекція 3 · Bash: скрипти, змінні, умови, цикли та функції", "section": "Як запускається скрипт: shebang, підоболонка, source, коди виходу", "url": "lectures/week-1/lecture-3.html#run", "text": "Як запускається скрипт: shebang, підоболонка, source, коди виходу Чотири способи запуску і різниця між ними Спосіб Потрібне право x ? Хто виконує Де виконується ./deploy.sh так інтерпретатор з shebang ( #!/bin/bash ) новий дочірній процес (підоболонка) /opt/scripts/deploy.sh так те саме, абсолютний шлях дочірній процес bash deploy.sh ні (досить r ) явно вказаний bash, shebang ігнорується дочірній процес source deploy.sh або . deploy.sh ні поточна оболонка у поточному процесі Різниця між підоболонкою і source принципова. Дочірній процес отримує копію змінних середовища; усе, що скрипт змінить (змінні, поточний каталог), зникне після його завершення. source виконує команди у вашій оболонці, тож зміни лишаються — тому так перечитують ~/.bashrc або підвантажують файл зі змінними: $ cat setenv.sh export APP_ENV=staging cd /opt/app $ ./setenv.sh ; echo \"$APP_ENV\" ; pwd # порожньо; каталог не змінився $ source setenv.sh ; echo \"$APP_ENV\" ; pwd # staging; /opt/app Shebang #!/bin/bash — конкретний шлях до bash. #!/usr/bin/env bash — знайти bash у PATH ; переносніше (macOS, NixOS, bash у /usr/local/bin ). #!/bin/sh — POSIX-оболонка. У Debian/Ubuntu це dash , який не знає bash-розширень ( [[ ]] , масиви, {1..5} ): скрипт з bash-синтаксисом під sh впаде з помилками. Shebang має бути першим рядком , без пробілів перед #! . Файл, створений у Windows, може мати кінці рядків \\r\\n — тоді Linux шукатиме інтерпретатор bash\\r і видасть bad interpreter . Лікується sed -i 's/\\r$//' script.sh або dos2unix . Коди завершення: exit Скрипт, як і будь-яка команда, повертає код виходу: exit 0 — успіх, exit 1 (або 2–255) — помилка. Без явного exit повертається код останньої виконаної команди . CI-системи (Jenkins, GitHub Actions) вважають крок проваленим саме за ненульовим кодом. Код Значення за домовленістю 0 успіх 1 загальна помилка 2 неправильне використання (помилкові аргументи, синтаксис) 126 команду знайдено, але вона не виконувана (немає права x ) 127 команду не знайдено ( command not found ) 128 + N процес завершено сигналом N: 130 — Ctrl+C (SIGINT, 2), 137 — kill -9 (9) «Суворий режим» і налагодження #!/usr/bin/env bash set -euo pipefail # -e вийти, щойно будь-яка команда поверне не"}, {"title": "Лекція 3 · Bash: скрипти, змінні, умови, цикли та функції", "section": "Змінні та лапки", "url": "lectures/week-1/lecture-3.html#vars", "text": "Змінні та лапки Змінні не оголошуються — створюються при присвоєнні. Значення завжди зберігаються як рядки ; арифметика перетворює їх на числа. Присвоєння — без пробілів навколо = : count=0 . Звернення — через $ : $count або ${count} . Тип не фіксований: count=0 , потім count=Sunday — легально, але погана практика. Одна змінна — один тип даних. \\ — символ екранування: зберігає буквальне значення наступного символу ( \\$ виведе знак долара). \"Подвійні лапки\" Змінні підставляються . var=\"test string\" echo \"Value: $var\" # Value: test string 'Одинарні лапки' Усе буквально , без підстановки. var=\"test string\" echo 'Value: $var' # Value: $var Рядки з пробілами чи спецсимволами обов'язково беріть у лапки. Ввести значення з клавіатури — команда read : read -p \"Введіть ім'я: \" user echo \"Привіт, $user\" Змінні середовища Є локальні змінні (лише в поточній оболонці) і змінні середовища (environment) , які задає система і успадковують дочірні процеси. Перелік — команда env ; створити свою — export NAME=value . Змінна Що містить PATH Список каталогів через : , де шукаються команди HOME , PWD Домашній і поточний каталог USER , LOGNAME Поточний користувач HOSTNAME , SHELL Ім'я машини, шлях до оболонки PS1 Вигляд запрошення: \\u користувач, \\w каталог, \\W його остання частина, \\t час, \\d дата, \\$ символ запрошення Ініціалізаційні файли: /etc/profile , /etc/profile.d/ , ~/.bash_profile (login-оболонка), ~/.bashrc і /etc/bashrc (інтерактивна), ~/.bash_logout (вихід)."}, {"title": "Лекція 3 · Bash: скрипти, змінні, умови, цикли та функції", "section": "Розкриття параметрів і масиви", "url": "lectures/week-1/lecture-3.html#expansion", "text": "Розкриття параметрів і масиви Bash уміє обробляти значення змінних прямо при підстановці, без виклику зовнішніх програм. Ці конструкції постійно зустрічаються в скриптах розгортання і Dockerfile. Вираз Результат Приклад ( file=/var/log/app.log.gz ) ${var:-default} значення, а якщо змінна порожня або не задана — default (змінна не змінюється) ${BRANCH:-main} ${var:=default} те саме, але ще й присвоює default змінній : ${PORT:=8080} ${var:?повідомлення} якщо порожня — вийти з помилкою rm -rf \"${DIR:?DIR not set}/\"* ${#var} довжина рядка ${#file} → 19 ${var#шаблон} / ${var##шаблон} прибрати найкоротший / найдовший збіг з початку ${file##*/} → app.log.gz (як basename ) ${var%шаблон} / ${var%%шаблон} прибрати найкоротший / найдовший збіг з кінця ${file%/*} → /var/log (як dirname ); ${file%%.*} → /var/log/app ${var/старе/нове} , ${var//старе/нове} замінити перший / усі збіги ${file//\\//_} → _var_log_app.log.gz ${var:зсув:довжина} підрядок ${file:5:3} → log ${var^^} / ${var,,} усі літери великі / малі ${ENV^^} → PROD for f in *.jpeg; do mv -- \"$f\" \"${f%.jpeg}.jpg\" # масове перейменування розширення done backup=\"db_$(date +%F).sql\" # db_2026-11-07.sql echo \"Архів: ${backup%.sql}.tar.gz\" Масиви servers=(web1 web2 db1) # індексований масив echo \"${servers[0]}\" # web1 (індекси з нуля) echo \"${servers[@]}\" # усі елементи echo \"${#servers[@]}\" # кількість: 3 servers+=(cache1) # додати елемент for s in \"${servers[@]}\"; do ssh \"$s\" uptime; done declare -A port # асоціативний масив (bash 4+) port[http]=80; port[https]=443 echo \"${port[https]}\" # 443 for k in \"${!port[@]}\"; do echo \"$k → ${port[$k]}\"; done Чому \"${arr[@]}\" у лапках: кожен елемент передається окремим словом, навіть якщо містить пробіл. ${arr[*]} склеює все в один рядок."}, {"title": "Лекція 3 · Bash: скрипти, змінні, умови, цикли та функції", "section": "Спеціальні змінні і підстановка команд", "url": "lectures/week-1/lecture-3.html#special", "text": "Спеціальні змінні і підстановка команд Змінна Значення $0 Ім'я скрипта $1 … $9 , ${10} Позиційні параметри (аргументи) $# Кількість аргументів \"$*\" Усі аргументи одним рядком \"$@\" Усі аргументи окремими рядками (безпечно для циклів) $? Код завершення останньої команди: 0 — успіх , інше — помилка $$ PID поточного процесу #!/bin/bash # ./args.sh one two → 2 / ./args.sh / one echo $# echo $0 echo $1 Підстановка команд вставляє вивід команди у змінну. Старий синтаксис — зворотні лапки `cmd` (не плутати з одинарною лапкою!), сучасний і зручніший — $(cmd) : list=`ls -l` # як на слайдах files=$(ls | wc -l) # рекомендований синтаксис, можна вкладати echo \"Файлів: $files\""}, {"title": "Лекція 3 · Bash: скрипти, змінні, умови, цикли та функції", "section": "Арифметика", "url": "lectures/week-1/lecture-3.html#math", "text": "Арифметика Вирази обчислюються через $(( вираз )) (старий варіант — $[ вираз ] ) або команду let . Bash працює лише з цілими числами — дробових немає. echo $(( 100 / 3 )) # 33 — ціла частина! myvar=\"56\" echo $(( myvar + 12 )) # 68 myvar=$(( myvar + 1 )) # інкремент let COUNTER=COUNTER+1 # те саме через let"}, {"title": "Лекція 3 · Bash: скрипти, змінні, умови, цикли та функції", "section": "Умови: if і вирази test", "url": "lectures/week-1/lecture-3.html#if", "text": "Умови: if і вирази test if / elif / else / fi. Гілки elif і else необов'язкові. if [ \"$myvar\" -eq 3 ]; then echo \"myvar = 3 як число\" elif [ \"$myvar\" = \"3\" ]; then echo \"myvar = 3 як рядок\" else echo \"інше\" fi if [ -z \"$1\" ]; then echo \"Порожній параметр\"; exit 1; fi Синтаксис [ — це команда, тому пробіли обов'язкові : після [ , перед ] і навколо операторів. [ $a -eq 1 ] ✓, [$a -eq 1] ✗. Якщо then / do на тому ж рядку — перед ним ставте ; . Порівняння Числа Рядки дорівнює / не дорівнює -eq / -ne = або == / != більше / більше або рівно -gt / -ge > (за алфавітом) менше / менше або рівно -lt / -le < (за алфавітом) довжина > 0 / = 0 — -n str / -z str Також є файлові оператори : -d (це каталог), -f (звичайний файл), -e (існує), та логічні : ! , && , || ."}, {"title": "Лекція 3 · Bash: скрипти, змінні, умови, цикли та функції", "section": "Три види умов: [ ] , [[ ]] , (( ))", "url": "lectures/week-1/lecture-3.html#tests", "text": "Три види умов: [ ] , [[ ]] , (( )) Після if може стояти будь-яка команда : bash дивиться лише на її код виходу (0 — «істина»). [ — це звичайна команда (синонім test ), яка повертає 0 або 1. Тому if grep -q nginx /etc/passwd; then … — повноцінна умова без жодних дужок. [ … ] (test) [[ … ]] (( … )) Що це команда POSIX, працює в sh ключове слово bash арифметичний вираз bash Для чого рядки, числа ( -eq ), файли рядки, шаблони, регулярні вирази, файли лише цілі числа Порівняння чисел [ \"$a\" -gt 5 ] [[ $a -gt 5 ]] (( a > 5 )) — звичні знаки Логічні І / АБО [ … ] && [ … ] (застаріле -a , -o ) [[ … && … ]] (( a > 1 && a < 9 )) Лапки навколо змінних обов'язкові бажані, але порожня змінна не ламає синтаксис не потрібні, $ можна не писати Шаблони ні [[ $f == *.log ]] — Регулярні вирази ні [[ $v =~ ^[0-9]+$ ]] — Знаки < > треба екранувати \\> , інакше це перенаправлення у файл! порівнюють рядки за абеткою порівнюють числа Чому лапки в [ ] обов'язкові name=\"\" [ $name = \"admin\" ] # перетворюється на [ = \"admin\" ] → помилка «unary operator expected» [ \"$name\" = \"admin\" ] # [ \"\" = \"admin\" ] → коректно, хибність file=\"my report.txt\" [ -f $file ] # [ -f my report.txt ] → «too many arguments» [ -f \"$file\" ] # правильно Пастка: рядки vs числа a=\"010\"; b=\"10\" [ \"$a\" -eq \"$b\" ] && echo \"рівні як числа\" # виведе [ \"$a\" = \"$b\" ] && echo \"рівні як рядки\" # не виведе [ \"$a\" > \"$b\" ] # НЕ порівняння: створить файл з ім'ям «10»! Повний перелік операторів test Оператор Істина, якщо… -e f файл існує (будь-якого типу) -f f / -d f / -L f звичайний файл / каталог / символічне посилання -r f / -w f / -x f поточний користувач може читати / писати / виконувати -s f файл існує і не порожній f1 -nt f2 / f1 -ot f2 f1 новіший / старіший за f2 -z s / -n s рядок порожній / непорожній s1 = s2 , s1 != s2 рядки рівні / різні n1 -eq n2 , -ne , -lt , -le , -gt , -ge числові =, ≠, <, ≤, >, ≥ ! вираз заперечення Розібраний приклад: перевірка аргументів скрипта #!/usr/bin/env bash # ./resize.sh <файл> <ширина> if [[ $# -ne 2 ]]; then echo \"Використання: $0 <файл> <ширина>\" >&2 # повідомлення про помилку — у stderr exit 2 fi file=$1; width=$2 [[ -f $file ]] || { echo \"Файл $file не знайдено\" >&2; exit 1; } [[ $wi"}, {"title": "Лекція 3 · Bash: скрипти, змінні, умови, цикли та функції", "section": "Цикли", "url": "lectures/week-1/lecture-3.html#loops", "text": "Цикли Цикл Виконується Приклад for … in для кожного елемента списку файли, аргументи, сервери while поки умова істинна лічильник, читання рядків until поки умова хибна (до моменту, коли стане істинною) чекати, поки сервіс підніметься for x in one two three; do echo \"number $x\" done for f in /etc/r*; do # перебір файлів за маскою if [ -d \"$f\" ]; then echo \"$f (dir)\"; else echo \"$f\"; fi done COUNTER=0 while [ $COUNTER -lt 10 ]; do # 0..9 echo \"The counter is $COUNTER\" COUNTER=$(( COUNTER + 1 )) done n=0 until [ $n -eq 10 ]; do # теж 0..9 echo $n; n=$(( n + 1 )) done Серед елементів мови також є select (меню вибору), функції та перехоплення сигналів trap (наприклад, прибрати тимчасові файли при Ctrl+C)."}, {"title": "Лекція 3 · Bash: скрипти, змінні, умови, цикли та функції", "section": "Цикли детальніше: діапазони, читання файлів, break і continue", "url": "lectures/week-1/lecture-3.html#loops-more", "text": "Цикли детальніше: діапазони, читання файлів, break і continue Різні форми for for i in 1 2 3 4 5; do echo $i; done # явний список for i in {1..5}; do echo $i; done # діапазон (розкриття дужок) for i in {0..20..5}; do echo $i; done # з кроком: 0 5 10 15 20 for i in $(seq 1 5); do echo $i; done # через seq (діапазон можна задати змінними) for (( i=0; i<5; i++ )); do echo $i; done # C-стиль: 0..4 for arg in \"$@\"; do echo \"Аргумент: $arg\"; done # усі аргументи скрипта for f in *.log; do gzip \"$f\"; done # файли за шаблоном for u in $(cut -d: -f1 /etc/passwd); do …; done # вивід команди (розбивається за пробілами!) {1..$n} не працює : розкриття дужок відбувається раніше за підстановку змінних. Для змінних меж — seq 1 \"$n\" або C-стиль. Читання файла рядок за рядком while IFS= read -r line; do echo \"Рядок: $line\" done < servers.txt # IFS= — не обрізати пробіли на краях; -r — не трактувати \\ як екранування # CSV: ім'я;група while IFS=';' read -r name group; do sudo useradd -m -G \"$group\" \"$name\" done < users.csv Чому не for line in $(cat file) : такий цикл розбиває текст за будь-якими пробілами , а не за рядками, і рядок «John Smith» стане двома ітераціями. break , continue і нескінченні цикли for f in /var/log/*.log; do [[ -s $f ]] || continue # порожній — пропустити, перейти до наступного grep -q \"FATAL\" \"$f\" && { echo \"Знайдено в $f\"; break; } # знайшли — вийти з циклу done # чекати, поки сервіс підніметься, але не довше 30 спроб attempt=0 until curl -fsS http://localhost:8080/health >/dev/null; do (( ++attempt >= 30 )) && { echo \"Сервіс не стартував\" >&2; exit 1; } sleep 2 done echo \"Сервіс готовий після $attempt спроб\" while true; do date; sleep 60; done # нескінченний цикл, вихід — Ctrl+C або break select : просте меню PS3=\"Оберіть середовище: \" select env in dev staging prod; do [[ -n $env ]] && { echo \"Деплой у $env\"; break; } done"}, {"title": "Лекція 3 · Bash: скрипти, змінні, умови, цикли та функції", "section": "Функції та область видимості", "url": "lectures/week-1/lecture-3.html#functions", "text": "Функції та область видимості За замовчуванням змінні в bash глобальні : функція, що змінює myvar , змінить її для всього скрипта. Щоб змінна жила лише у функції — оголосіть її local . Без local myvar=\"hello\" myfunc() { myvar=\"one two three\" for x in $myvar; do echo $x; done } myfunc echo \"$myvar / $x\" # one two three / three З local myvar=\"hello\" myfunc() { local x local myvar=\"one two three\" for x in $myvar; do echo $x; done } myfunc echo \"$myvar / $x\" # hello / (x порожня) Що повертає функція? Питання з чату: return N повертає лише код завершення 0–255 (читається через $? ), як у будь-якої команди. Щоб повернути дані, функція виводить їх через echo , а викликач забирає через $(…) : get_ip() { hostname -I | awk '{print $1}'; } is_root() { [ \"$(id -u)\" -eq 0 ]; } # код 0 = «істина» ip=$(get_ip) if is_root; then echo \"root on $ip\"; else echo \"not root\"; fi"}, {"title": "Лекція 3 · Bash: скрипти, змінні, умови, цикли та функції", "section": "Ввід, вивід, опції скрипта і trap", "url": "lectures/week-1/lecture-3.html#io", "text": "Ввід, вивід, опції скрипта і trap read і printf read -p \"Ім'я: \" name # з підказкою read -s -p \"Пароль: \" pass; echo # -s: не показувати ввід read -t 10 -p \"Продовжити? [y/N] \" ans || ans=n # -t: тайм-аут 10 с read -r a b c <<< \"1 2 3\" # розбити рядок на змінні printf \"%-10s %5d\\n\" \"nginx\" 812 # форматований вивід: ширина колонок, числа printf \"%.2f\\n\" 3.14159 # 3.14 — printf уміє дроби, а $(( )) ні echo -e \"рядок1\\nрядок2\" # -e: інтерпретувати \\n, \\t echo \"Помилка!\" >&2 # повідомлення про помилку — у stderr Дробові обчислення: echo \"scale=2; 7/2\" | bc → 3.50 або awk 'BEGIN{print 7/2}' → 3.5 . Розбір опцій: getopts #!/usr/bin/env bash # ./backup.sh -d /var/www -k 7 -v dir=/var/www; keep=5; verbose=0 while getopts \"d:k:vh\" opt; do # двокрапка після літери = опція зі значенням case $opt in d) dir=$OPTARG ;; k) keep=$OPTARG ;; v) verbose=1 ;; h) echo \"Usage: $0 [-d dir] [-k days] [-v]\"; exit 0 ;; *) exit 2 ;; esac done shift $((OPTIND - 1)) # прибрати оброблені опції; решта — у \"$@\" (( verbose )) && echo \"dir=$dir keep=$keep\" shift shift зсуває позиційні параметри вліво: $2 стає $1 , а $# зменшується на 1. Зручно для обробки аргументів у циклі while (( $# )); do …; shift; done . trap : прибирання при виході і сигналах tmp=$(mktemp -d) # безпечний тимчасовий каталог trap 'rm -rf \"$tmp\"' EXIT # виконається при будь-якому виході зі скрипта trap 'echo \"Перервано\"; exit 130' INT TERM curl -fsSL https://example.com/app.tar.gz -o \"$tmp/app.tar.gz\" tar -xzf \"$tmp/app.tar.gz\" -C /opt/app # tmp буде видалено навіть якщо tar впаде або натиснуть Ctrl+C Логування в скриптах LOG=/var/log/deploy.log log() { printf '[%s] %s\\n' \"$(date '+%F %T')\" \"$*\" | tee -a \"$LOG\"; } die() { log \"ПОМИЛКА: $*\"; exit 1; } log \"Початок деплою\" systemctl restart nginx || die \"nginx не перезапустився\" exec > >(tee -a \"$LOG\") 2>&1 # з цього місця весь вивід скрипта дублюється в лог"}, {"title": "Лекція 3 · Bash: скрипти, змінні, умови, цикли та функції", "section": "case і обробка тексту", "url": "lectures/week-1/lecture-3.html#extra", "text": "case і обробка тексту case — вибір із кількох варіантів case \"$1\" in start) systemctl start nginx ;; stop) systemctl stop nginx ;; restart) systemctl restart nginx ;; *) echo \"Usage: $0 {start|stop|restart}\"; exit 1 ;; esac Кожна гілка закінчується ;; , *) — «усе інше», блок закривається словом esac (case навпаки, як fi для if ). У гілках можна писати шаблони і кілька варіантів через | : case \"$answer\" in [Yy]|[Yy]es) echo \"Продовжуємо\" ;; [Nn]*) echo \"Скасовано\"; exit 0 ;; \"\") echo \"Порожня відповідь\" ;; *) echo \"Не зрозумів\" ;; esac case \"$file\" in *.tar.gz|*.tgz) tar -xzf \"$file\" ;; *.zip) unzip \"$file\" ;; esac Обробка тексту: grep, sed, awk, cut grep -c \"ERROR\" app.log # скільки рядків з ERROR sed 's/http:/https:/g' site.conf # замінити текст (вивід на екран) sed -i 's/8080/80/' app.conf # -i — змінити файл на місці awk '{print $1}' access.log | sort | uniq -c | sort -nr | head # топ IP-адрес у лозі cut -d: -f1 /etc/passwd # лише імена користувачів sed , awk , cut , sort , uniq детально розібрано в лекції 2 (розділ «Обробка тексту в конвеєрах»). Короткі правила для awk : $1 , $2 — поля рядка (за замовчуванням розділені пробілами), -F: — інший роздільник, NR — номер рядка, NF — кількість полів, $NF — останнє поле. awk -F: '$3 >= 1000 {print $1, $6}' /etc/passwd # звичайні користувачі та їхні домашні каталоги awk '{sum += $10} END {print sum/1024/1024 \" MB\"}' access.log # сумарний обсяг відповідей sed -n '/BEGIN/,/END/p' file # рядки між маркерами sed -i.bak 's/^PermitRootLogin.*/PermitRootLogin no/' /etc/ssh/sshd_config # змінити з резервною копією .bak"}, {"title": "Лекція 3 · Bash: скрипти, змінні, умови, цикли та функції", "section": "cron детально", "url": "lectures/week-1/lecture-3.html#cron", "text": "cron детально Демон cron щохвилини перевіряє таблиці задач (crontab) і запускає те, чий час настав. ┌───────────── хвилина (0–59) │ ┌─────────── година (0–23) │ │ ┌───────── день місяця (1–31) │ │ │ ┌─────── місяць (1–12 або jan–dec) │ │ │ │ ┌───── день тижня (0–7, де 0 і 7 — неділя, або sun–sat) │ │ │ │ │ * * * * * команда Запис Значення * будь-яке значення */15 кожні 15 одиниць (хвилин, годин…) 1-5 діапазон (пн–пт у полі дня тижня) 1,15 перелік 0 2 * * * щодня о 02:00 30 8 * * 1-5 о 08:30 у будні 0 0 1 * * опівночі першого числа кожного місяця */5 * * * * кожні 5 хвилин @reboot , @daily , @hourly , @weekly спеціальні рядки: після старту системи, раз на день тощо crontab -e # редагувати свою таблицю crontab -l # переглянути crontab -r # видалити ВСЮ таблицю (обережно, легко сплутати з -e) sudo crontab -u www-data -l # таблиця іншого користувача ls /etc/cron.d /etc/cron.daily # системні задачі (у /etc/crontab є ще поле користувача) Чому скрипт працює вручну, але не в cron Cron запускає команди з мінімальним середовищем: короткий PATH (часто лише /usr/bin:/bin ), поточний каталог — домашній, без змінних з ~/.bashrc . Тому в crontab пишіть абсолютні шляхи до скриптів і програм, задавайте потрібні змінні у скрипті й обов'язково перенаправляйте вивід у лог ( >> /var/log/job.log 2>&1 ) — інакше помилок не побачите. Знак % у crontab має спеціальне значення, його екранують: date +\\%F . Альтернатива cron у сучасних дистрибутивах — systemd timers ( systemctl list-timers ): логи в journald, залежності від інших служб, пропущені запуски наздоганяються після ввімкнення."}, {"title": "Лекція 3 · Bash: скрипти, змінні, умови, цикли та функції", "section": "Практика: мінімальний deployment-скрипт", "url": "lectures/week-1/lecture-3.html#deploy", "text": "Практика: мінімальний deployment-скрипт Результат курсу — уміти написати bash-скрипт розгортання. Ось шаблон, що поєднує все з лекції: аргументи, перевірки, функції, коди завершення. #!/bin/bash # deploy.sh <git-url> [branch] — розгорнути сайт у /var/www/html/app set -e # зупинитись на першій помилці REPO=\"$1\"; BRANCH=\"${2:-main}\"; TARGET=/var/www/html/app log() { echo \"[$(date +%T)] $*\"; } if [ $# -lt 1 ]; then echo \"Usage: $0 <git-url> [branch]\"; exit 1 fi if [ \"$(id -u)\" -ne 0 ]; then echo \"Run as root (sudo)\"; exit 1 fi if [ -d \"$TARGET/.git\" ]; then log \"Оновлюю код ($BRANCH)\" git -C \"$TARGET\" pull origin \"$BRANCH\" else log \"Клоную $REPO\" git clone -b \"$BRANCH\" \"$REPO\" \"$TARGET\" fi chown -R apache:apache \"$TARGET\" systemctl restart httpd log \"Готово, код завершення: $?\""}, {"title": "Лекція 3 · Bash: скрипти, змінні, умови, цикли та функції", "section": "Розібрані скрипти для реальних задач", "url": "lectures/week-1/lecture-3.html#examples", "text": "Розібрані скрипти для реальних задач 1. Резервна копія з ротацією #!/usr/bin/env bash # backup.sh — архів каталогу сайту і дамп БД; зберігати останні 7 днів set -euo pipefail SRC=/var/www/html DEST=/backup KEEP_DAYS=7 STAMP=$(date +%F_%H%M) mkdir -p \"$DEST\" tar -czf \"$DEST/site_$STAMP.tar.gz\" -C \"$SRC\" . mysqldump --single-transaction shop | gzip > \"$DEST/db_$STAMP.sql.gz\" find \"$DEST\" -name \"*.gz\" -mtime +\"$KEEP_DAYS\" -delete # ротація: старші за 7 днів echo \"Бекап $STAMP готовий: $(du -sh \"$DEST\" | cut -f1)\" # crontab: 0 3 * * * /opt/scripts/backup.sh >> /var/log/backup.log 2>&1 2. Попередження про заповнений диск #!/usr/bin/env bash LIMIT=85 df -P -x tmpfs -x devtmpfs | tail -n +2 | while read -r fs size used avail pct mount; do usage=${pct%\\%} # \"91%\" → 91 if (( usage >= LIMIT )); then echo \"УВАГА: $mount заповнено на $usage% ($fs)\" >&2 fi done 3. Перевірка доступності сайтів #!/usr/bin/env bash urls=(\"https://example.com\" \"https://example.org/health\") fail=0 for u in \"${urls[@]}\"; do code=$(curl -s -o /dev/null -w '%{http_code}' --max-time 5 \"$u\" || echo 000) if [[ $code == 2* ]]; then printf '%-35s OK (%s)\\n' \"$u\" \"$code\" else printf '%-35s FAIL (%s)\\n' \"$u\" \"$code\"; fail=1 fi done exit $fail # ненульовий код — сигнал для CI або моніторингу 4. Створення користувачів зі списку #!/usr/bin/env bash # users.txt: по одному логіну в рядку [[ $EUID -eq 0 ]] || { echo \"Потрібен root\" >&2; exit 1; } while IFS= read -r u; do [[ -z $u || $u == \\#* ]] && continue # пропустити порожні рядки і коментарі if id \"$u\" &>/dev/null; then echo \"$u вже існує\" else useradd -m -s /bin/bash \"$u\" && echo \"створено $u\" fi done < users.txt"}, {"title": "Лекція 3 · Bash: скрипти, змінні, умови, цикли та функції", "section": "Типові помилки", "url": "lectures/week-1/lecture-3.html#mistakes", "text": "Типові помилки Скрипт, запущений як ./setenv.sh , змінить змінні й каталог поточного терміналу. Він працює в дочірньому процесі, і зміни зникають. Щоб змінити поточну оболонку — source setenv.sh або . setenv.sh . [ \"$a\" > \"$b\" ] порівнює рядки. У [ ] знак > — перенаправлення у файл. Пишіть [[ $a > $b ]] або [ \"$a\" \\> \"$b\" ] ; для чисел — -gt або (( a > b )) . for i in {1..$n} пройде від 1 до n. Розкриття дужок відбувається до підстановки змінних. Використовуйте seq 1 \"$n\" або for ((i=1; i<=n; i++)) . for line in $(cat file) читає файл по рядках. Він розбиває текст за будь-якими пробілами. По рядках: while IFS= read -r line; do …; done < file . Скрипт з #!/bin/sh може використовувати [[ ]] і масиви. У Debian/Ubuntu sh — це dash без bash-розширень. Для них потрібен #!/bin/bash . Задача в cron бачить той самий PATH , що й ваш термінал. Середовище cron мінімальне. Пишіть абсолютні шляхи і перенаправляйте вивід у лог. name = \"Ivan\" — з пробілами. Bash сприйме name як команду. Правильно: name=\"Ivan\" . [ \"$a\" = 10 ] для порівняння чисел / -eq для рядків. Числа: -eq -ne -lt -le -gt -ge . Рядки: = != -z -n . «010» і «10» рівні як числа, але не як рядки. Змінна без лапок: [ -z $1 ] , rm $file . Якщо значення порожнє або з пробілами — синтаксична помилка чи видалення не того. Пишіть \"$1\" , \"$file\" . echo $(( 7 / 2 )) дасть 3.5. Bash рахує лише цілі: результат 3 . Для дробів — bc або awk . return \"текст\" поверне рядок із функції. return — тільки код 0–255. Дані — через echo і $(func) ."}, {"title": "Лекція 4 · Архітектура вебзастосунків: HTTP, REST API, N-tier і мікросервіси", "section": "Вступ", "url": "lectures/week-1/lecture-4.html", "text": ""}, {"title": "Лекція 4 · Архітектура вебзастосунків: HTTP, REST API, N-tier і мікросервіси", "section": "Чого ви навчитесь", "url": "lectures/week-1/lecture-4.html#goals", "text": "Чого ви навчитесь Описати шлях запиту від введення адреси в браузері до відображення сторінки. Пояснити властивості HTTP (request-response, stateless) і роль cookies. Розрізняти HTTP-методи, GET vs POST у формах, URL vs URI. Порівняти 2-tier, 3-tier і N-tier архітектури, frontend і backend, монолітну та мікросервісну. Спроєктувати REST-ендпоінти для CRUD і викликати їх через curl . Пояснити HTTPS/TLS, різницю між вебсервером і сервером застосунку, роль балансувальника, кешу і CDN. Знати коди статусу HTTP і заголовки, читати вивід curl -v , розрізняти версії HTTP/1.1, 2 і 3. Пояснити сесії і кукі (HttpOnly, Secure, SameSite), Basic, Bearer/JWT, OAuth і CORS. Спроєктувати REST API з правильними методами і кодами відповіді; знати SOAP, GraphQL, gRPC. Порівняти моноліт і мікросервіси, синхронну й асинхронну взаємодію, правила Twelve-Factor. Розрізняти forward і reverse proxy, балансування L4 і L7, описати TLS-рукостискання і ланцюжок сертифікатів."}, {"title": "Лекція 4 · Архітектура вебзастосунків: HTTP, REST API, N-tier і мікросервіси", "section": "Клієнт-сервер і веб", "url": "lectures/week-1/lecture-4.html#client-server", "text": "Клієнт-сервер і веб Модель клієнт-сервер розділяє систему на клієнтів і сервери, що спілкуються мережею. Клієнт ініціює сеанс і надсилає запити; сервер чекає запитів від будь-яких клієнтів і відповідає. Мобільні застосунки — теж клієнти: вони звертаються до вебсерверів і вебсервісів. Вебсайт переважно показує інформацію (контент однаковий для всіх), вебзастосунок — інтерактивний: користувач створює і змінює дані (той самий CRUD з лекції 1). Hypertext Гіпертекст Нелінійний текст із посиланнями на інші тексти (термін Теда Нельсона, ~1965). Hypermedia Гіпермедіа Гіпертекст, що містить не лише текст, а й графіку, відео, звук. HTTP HyperText Transfer Protocol Протокол обміну гіпертекстом за схемою «запит — відповідь»."}, {"title": "Лекція 4 · Архітектура вебзастосунків: HTTP, REST API, N-tier і мікросервіси", "section": "Як працює HTTP-запит", "url": "lectures/week-1/lecture-4.html#http-flow", "text": "Як працює HTTP-запит Шлях запиту. Спочатку ім'я перетворюється на IP (DNS), потім іде HTTP-запит, сервер загортає дані в HTTP-відповідь. Властивості HTTP Request-response: транзакцію завжди починає клієнт, сервер генерує відповідь. Ідентифікація ресурсу: кожен запит містить URI. Stateless (без стану): сервер не пам'ятає попередніх запитів — кожен запит незалежний. Метадані: заголовки (headers) передають інформацію про дані — тип вмісту, довжину, кукі, авторизацію. GET /index.html HTTP/1.1 ← рядок запиту: метод, шлях, версія Host: shop.com ← заголовки Accept: text/html HTTP/1.1 200 OK ← рядок статусу Content-Type: text/html; charset=utf-8 Set-Cookie: session=abc123 <html>…</html> ← тіло відповіді Класи кодів статусу: 2xx — успіх (200 OK, 201 Created), 3xx — перенаправлення (301, 302), 4xx — помилка клієнта (400, 401, 403, 404), 5xx — помилка сервера (500, 502, 503). URL, URI, URN URI — рядок, що ідентифікує ресурс. URL — підвид URI, що вказує, де ресурс і як до нього дістатися (схема + адреса). URN — ідентифікує ресурс за ім'ям . Кожен URL — це URI, але не кожен URI — URL."}, {"title": "Лекція 4 · Архітектура вебзастосунків: HTTP, REST API, N-tier і мікросервіси", "section": "HTTP детально: коди статусу, заголовки, версії", "url": "lectures/week-1/lecture-4.html#http-deep", "text": "HTTP детально: коди статусу, заголовки, версії Коди статусу, які треба знати Код Назва Коли 1xx — інформаційні : 100 Continue, 101 Switching Protocols (перехід на WebSocket) 200 OK успіх, дані в тілі 201 Created ресурс створено (відповідь на POST), часто з заголовком Location 204 No Content успіх без тіла (типово для DELETE) 301 / 308 Moved Permanently / Permanent Redirect ресурс переїхав назавжди (http → https), браузер і пошуковики запам'ятовують 302 / 307 Found / Temporary Redirect тимчасовий редирект (після логіну) 304 Not Modified ресурс не змінився з минулого запиту — бери з кешу 400 Bad Request некоректний запит (зламаний JSON, бракує поля) 401 Unauthorized не автентифіковано: немає або неправильний логін/токен 403 Forbidden автентифіковано, але прав немає (або права файлів на сервері) 404 Not Found ресурсу немає 405 Method Not Allowed метод не підтримується для цього ресурсу 409 Conflict конфлікт стану (такий email уже є) 429 Too Many Requests перевищено ліміт запитів (rate limiting) 500 Internal Server Error необроблена помилка в коді сервера 502 Bad Gateway проксі отримав погану відповідь від бекенду або не зміг з'єднатися 503 Service Unavailable сервіс перевантажений або на обслуговуванні 504 Gateway Timeout проксі не дочекався відповіді бекенду Швидке правило: 4xx — «винен клієнт» (повторення того самого запиту не допоможе), 5xx — «винен сервер» (можна повторити пізніше). Різниця 401/403: 401 — «хто ви?», 403 — «я знаю, хто ви, але вам не можна». Важливі заголовки Заголовок Де Призначення Host запит ім'я сайту; обов'язковий в HTTP/1.1, саме за ним працюють віртуальні хости на одній IP User-Agent запит браузер / клієнт Accept / Content-Type запит / обидва який формат клієнт приймає / в якому форматі тіло ( application/json , text/html , multipart/form-data ) Content-Length обидва розмір тіла в байтах Authorization запит Basic … або Bearer <token> Cookie / Set-Cookie запит / відповідь передача і встановлення кукі Location відповідь адреса редиректу або створеного ресурсу Cache-Control , ETag , Last-Modified відповідь правила кешування і «відбиток» версії ресурсу X-Forwarded-For запит (від проксі) справжня IP клієнта за балансувальником Strict-Transport"}, {"title": "Лекція 4 · Архітектура вебзастосунків: HTTP, REST API, N-tier і мікросервіси", "section": "HTTP-методи", "url": "lectures/week-1/lecture-4.html#methods", "text": "HTTP-методи Методи («дієслова») показують, що зробити з ресурсом: GET , POST , PUT , PATCH , DELETE , HEAD , OPTIONS , TRACE , CONNECT . Метод може бути безпечним (не змінює дані), ідемпотентним (повтор дає той самий результат) і кешованим . Метод Дія (CRUD) Безпечний Ідемпотентний GET Read — отримати так так POST Create — створити ні ні PUT Update — замінити повністю ні так PATCH Update — змінити частину полів ні не гарантовано DELETE Delete — видалити ні так HEAD як GET, але без тіла відповіді так так GET vs POST у HTML-формах Звичайна HTML-форма вміє лише GET і POST . Дані форми завжди передаються як словник ключ=значення (ключ — атрибут name поля), пари з'єднуються через & : view=home&op=translate&sl=en&tl=uk&text=advertisement . GET Дані в URI (рядок запиту після ? ). Обмеження довжини URI (~2048 символів у багатьох браузерах). Видно в адресному рядку, історії, логах → не для паролів. Можна зберегти в закладки. POST Дані в тілі (body) запиту. Розмір тіла протоколом не обмежений. Не видно в URL (але без HTTPS не зашифровано!). Для створення ресурсів, логіну, завантаження файлів. Інструктор у чаті наголосив: на практиці найчастіше трапляються GET і POST, але правильний REST-стиль використовує всі базові методи — цього очікують у командах."}, {"title": "Лекція 4 · Архітектура вебзастосунків: HTTP, REST API, N-tier і мікросервіси", "section": "Cookies: стан поверх stateless-протоколу", "url": "lectures/week-1/lecture-4.html#cookies", "text": "Cookies: стан поверх stateless-протоколу"}, {"title": "Лекція 4 · Архітектура вебзастосунків: HTTP, REST API, N-tier і мікросервіси", "section": "Сесії, автентифікація і CORS", "url": "lectures/week-1/lecture-4.html#auth", "text": "Сесії, автентифікація і CORS Як stateless-протокол «пам'ятає» користувача Користувач надсилає логін і пароль ( POST /login ). Сервер перевіряє їх, створює сесію (запис у Redis або БД з ID сесії) і відповідає Set-Cookie: session=9f2c…; HttpOnly; Secure; SameSite=Lax . Браузер автоматично додає Cookie: session=9f2c… до кожного наступного запиту на цей домен. Сервер за ID знаходить сесію і знає, хто це. Вихід — сесію видаляють. Атрибут cookie Значення Expires / Max-Age строк життя; без них — «сесійна» кукі до закриття браузера HttpOnly JavaScript не бачить кукі — захист від крадіжки через XSS Secure передається лише по HTTPS SameSite=Lax|Strict|None чи надсилати кукі з запитами з інших сайтів — захист від CSRF Domain , Path для яких адрес діє кукі Способи автентифікації в API Спосіб Як працює Коли Basic Auth Authorization: Basic base64(login:password) . Base64 — кодування, а не шифрування! лише поверх HTTPS, прості внутрішні сервіси API key статичний ключ у заголовку ( X-API-Key ) машина-машина, публічні API Bearer token / JWT Authorization: Bearer eyJhbGci… ; JWT — підписаний токен з даними (хто, до коли діє), сервер перевіряє підпис без звернення до БД SPA, мобільні застосунки, мікросервіси OAuth 2.0 / OpenID Connect вхід через стороннього провайдера («Увійти через Google»), застосунок отримує токен доступу, а не пароль сторонні інтеграції, SSO CORS Браузер за замовчуванням не дає JavaScript зі сторінки https://app.example.com читати відповіді API з іншого походження (origin = схема + хост + порт), наприклад https://api.example.com . CORS (Cross-Origin Resource Sharing) — механізм, яким сервер API дозволяє це заголовком Access-Control-Allow-Origin: https://app.example.com . Для «складних» запитів (PUT, DELETE, власні заголовки) браузер спершу надсилає попередній запит OPTIONS (preflight). Помилка CORS видна лише в браузері: curl її не відтворить, бо CORS — правило браузера, а не сервера."}, {"title": "Лекція 4 · Архітектура вебзастосунків: HTTP, REST API, N-tier і мікросервіси", "section": "2-tier, 3-tier, N-tier", "url": "lectures/week-1/lecture-4.html#tiers", "text": "2-tier, 3-tier, N-tier 2-tier: клієнт (браузер) ↔ вебсервер (який сам працює і з даними). 3-tier: клієнт ↔ сервер застосунку ↔ окремий сервер БД. N-tier: додаткові рівні — балансувальники навантаження, кілька серверів застосунку, кеші. Масштабується горизонтально. Класичний вебзастосунок (3-tier): БД зберігає дані, вебсервер містить бізнес-логіку і шар доступу до даних і динамічно генерує HTML . Явного поділу на frontend/backend немає — усе на сервері."}, {"title": "Лекція 4 · Архітектура вебзастосунків: HTTP, REST API, N-tier і мікросервіси", "section": "Frontend, backend і AJAX", "url": "lectures/week-1/lecture-4.html#front-back", "text": "Frontend, backend і AJAX Backend (server-side) Код виконується на сервері під керуванням вебсервера. Мови: Perl, PHP, Python, Java, C#, Ruby, JavaScript (Node.js). БД: Oracle, MS SQL, MySQL, PostgreSQL, DB2, Firebird… Frontend (client-side) Код виконується на машині клієнта в браузері: HTML, CSS, JavaScript і фреймворки. AJAX (Asynchronous JavaScript and XML) — підхід, що дозволив розділити логіку між frontend і backend. Розроблений Microsoft у 1999, назву дав Джессі Джеймс Гаррет у 2005. JavaScript у браузері надсилає запит асинхронно і оновлює частину сторінки без її перезавантаження . Сьогодні замість XMLHttpRequest використовують fetch або бібліотеки на кшталт axios, а для двостороннього каналу в реальному часі — WebSocket. За словами інструктора, AJAX не застарів — змінилися бібліотеки, а призначення в цих технологій різне. Формати даних JSON { \"id\": 3, \"title\": \"DevOps\", \"tags\": [\"ci\", \"cd\"] } XML <book id=\"3\"> <title>DevOps</title> </book>"}, {"title": "Лекція 4 · Архітектура вебзастосунків: HTTP, REST API, N-tier і мікросервіси", "section": "API і REST", "url": "lectures/week-1/lecture-4.html#rest", "text": "API і REST API (Application Programming Interface) — набір функцій і процедур, через які одна програма отримує доступ до даних і можливостей іншої програми, сервісу чи ОС. REST (Representational State Transfer) — архітектурний стиль вебсервісів. Кожна одиниця інформації однозначно визначається URL (URL фактично стає «первинним ключем»), а дії задаються HTTP-методами ; операції — без стану . Запит Що робить GET /book/3 отримати книгу №3 GET /book/3/page/35 сторінка 35 книги 3 (вкладені ресурси) POST /book додати книгу (дані в тілі) PUT /book/3 замінити книгу 3 (дані в тілі) PATCH /book/3 змінити окремі поля DELETE /book/3 видалити книгу 3 Виклик API через curl # GET — список ресурсів curl https://api.example.com/clubs # POST з JSON-тілом curl -X POST https://api.example.com/signin \\ -H \"Content-Type: application/json\" \\ -d '{\"email\": \"test@gmail.com\", \"password\": \"user\"}' # запит з токеном авторизації, -i показує заголовки відповіді curl -i -H \"Authorization: Bearer <token>\" -X GET https://api.example.com/user/32 Ключі curl: -X — метод, -H — заголовок, -d — тіло, -i — показати заголовки відповіді. Зручно поєднувати з jq для читабельного JSON."}, {"title": "Лекція 4 · Архітектура вебзастосунків: HTTP, REST API, N-tier і мікросервіси", "section": "REST детально: принципи, проєктування API, альтернативи", "url": "lectures/week-1/lecture-4.html#rest-deep", "text": "REST детально: принципи, проєктування API, альтернативи Шість обмежень REST (Рой Філдінг, 2000) Обмеження Суть Client-server інтерфейс і зберігання даних розділені, розвиваються незалежно Stateless кожен запит містить усе потрібне для обробки (токен, параметри); сервер не тримає стан клієнта між запитами — тому серверів можна додавати скільки завгодно Cacheable відповіді позначають, чи можна їх кешувати Uniform interface ресурси ідентифікуються URI, дії — стандартні HTTP-методи, представлення — JSON/XML Layered system клієнт не знає, чи говорить напряму із сервером, чи через проксі, CDN, балансувальник Code on demand (необов'язкове) сервер може передати клієнту код для виконання (JavaScript) Проєктування ендпоінтів: повний CRUD Операція Запит Успішна відповідь Типові помилки Список GET /api/v1/products?category=2&page=2&limit=20 200 + масив 400 (неправильний параметр) Один ресурс GET /api/v1/products/42 200 + об'єкт 404 Створити POST /api/v1/products + JSON 201 Created + Location: /api/v1/products/43 400, 409, 422 Замінити PUT /api/v1/products/42 + повний JSON 200 або 204 404, 400 Частково змінити PATCH /api/v1/products/42 + {\"price\": 990} 200 404, 400 Видалити DELETE /api/v1/products/42 204 No Content 404 Домовленості: іменники в множині ( /products , не /getProducts ), дія — це метод, а не частина URL; вкладеність для зв'язків ( /orders/7/items ); фільтри, сортування і пагінація — у параметрах запиту; версія API в шляху ( /v1/ ) або заголовку. POST /api/v1/products Content-Type: application/json { \"name\": \"Pixel 9\", \"price\": 899, \"category_id\": 2 } HTTP/1.1 201 Created Location: /api/v1/products/43 { \"id\": 43, \"name\": \"Pixel 9\", \"price\": 899, \"category_id\": 2 } Ідемпотентність на практиці Мережа ненадійна: клієнт може не отримати відповідь і повторити запит. Повторний PUT /products/42 із тими самими даними дає той самий стан — безпечно. Повторний POST /orders створить друге замовлення — тому платіжні API приймають заголовок Idempotency-Key , щоб розпізнати повтор. DELETE ідемпотентний за станом: після першого виклику ресурсу немає, і після другого теж (хоча код відповіді може бути 404). Альтернативи REST Підхід Суть Де SOAP XML-повідомлення за суворою схемою ("}, {"title": "Лекція 4 · Архітектура вебзастосунків: HTTP, REST API, N-tier і мікросервіси", "section": "Моноліт vs мікросервіси", "url": "lectures/week-1/lecture-4.html#micro", "text": "Моноліт vs мікросервіси Монолітна архітектура Один застосунок: інтерфейс, логіка і доступ до даних в одній програмі на одній платформі. Просто розробити і розгорнути на старті. Важко масштабувати частинами; одна помилка може покласти все. Мікросервіси Набір малих незалежних сервісів (користувачі, замовлення, оплата), кожен зі своєю БД, спілкуються через API. Масштабуються і розгортаються окремо. Складніше: мережа, моніторинг, оркестрація → тут і потрібні Docker та CI/CD."}, {"title": "Лекція 4 · Архітектура вебзастосунків: HTTP, REST API, N-tier і мікросервіси", "section": "Моноліт і мікросервіси детально", "url": "lectures/week-1/lecture-4.html#micro-deep", "text": "Моноліт і мікросервіси детально Моноліт Мікросервіси Структура один застосунок, одна кодова база, одна БД багато маленьких сервісів, кожен зі своєю відповідальністю і, в ідеалі, своєю БД Розгортання увесь застосунок разом кожен сервіс незалежно, багато разів на день Масштабування копіюємо весь застосунок лише ті сервіси, що навантажені Технології одна мова/фреймворк свої для кожного сервісу Збій помилка може покласти все ізольований (якщо правильно спроєктовано) Складність простий старт, локальні виклики функцій мережеві виклики, розподілені транзакції, моніторинг, трасування — потрібна зріла DevOps-культура Коли обирати новий продукт, мала команда великий продукт, багато команд, різне навантаження на частини Як сервіси спілкуються Синхронно : REST або gRPC — сервіс чекає відповіді. Просто, але ланцюжок викликів падає, якщо падає будь-яка ланка. Асинхронно : через брокер повідомлень ( RabbitMQ , Apache Kafka , AWS SQS) — сервіс публікує подію «замовлення створено», інші обробляють, коли зможуть. Сервіси слабше зв'язані, піки навантаження згладжуються. API Gateway — єдина точка входу для клієнтів: маршрутизація до сервісів, автентифікація, rate limiting (Kong, AWS API Gateway, Nginx). Service discovery — сервіси знаходять один одного за іменем, а не фіксованою IP (DNS у Kubernetes, Consul). Twelve-Factor App: як писати застосунки для хмари Набір правил від Heroku, на яких тримаються контейнери і PaaS. Найважливіші для DevOps: Одна кодова база в Git — багато розгортань (dev, staging, prod). Залежності оголошені явно ( requirements.txt , package.json ), нічого не береться «з системи». Конфігурація — у змінних середовища , а не в коді (паролі БД, адреси сервісів). Зовнішні служби (БД, черга, кеш) — підключувані ресурси за URL. Build, release, run — суворо розділені етапи. Процеси без стану (stateless); стан — у БД або кеші. Логи — потік у stdout , а збирає їх середовище виконання. Dev/prod parity — середовища якомога схожі."}, {"title": "Лекція 4 · Архітектура вебзастосунків: HTTP, REST API, N-tier і мікросервіси", "section": "HTTPS, вебсервер і сервер застосунку, балансування, кеш", "url": "lectures/week-1/lecture-4.html#infra", "text": "HTTPS, вебсервер і сервер застосунку, балансування, кеш HTTPS і TLS HTTPS — це HTTP поверх TLS (застаріла назва — SSL). Типові порти: HTTP — 80 , HTTPS — 443 . TLS дає три речі: шифрування трафіку, цілісність (дані не підмінили дорогою) і автентифікацію сервера через сертифікат, підписаний центром сертифікації (CA). Безкоштовні сертифікати видає Let's Encrypt. Під час TLS-рукостискання (handshake) браузер перевіряє сертифікат і узгоджує ключ сеансу; далі дані йдуть зашифровано. Хто що робить на сервері Роль Що робить Приклади Вебсервер приймає HTTP(S), віддає статику (HTML, CSS, картинки) Apache httpd, NGINX Сервер застосунку / runtime виконує бізнес-логіку (код backend) Tomcat (Java), Gunicorn (Python), Node.js, PHP-FPM Reverse proxy / балансувальник стоїть перед серверами, завершує TLS, розподіляє запити NGINX, HAProxy, AWS ELB Балансування навантаження і масштабування Балансувальник розподіляє запити між кількома однаковими серверами за алгоритмом: round robin (по черзі), least connections (туди, де менше з'єднань), IP hash (один клієнт — завжди один сервер). Health check прибирає з ротації сервер, що не відповідає. Щоб додавати сервери горизонтально, застосунок має бути stateless : сесії зберігають не в пам'яті сервера, а в спільному сховищі (Redis, БД). Кешування і CDN Кеш браузера — керується заголовками відповіді ( Cache-Control , ETag ). CDN (Content Delivery Network: Cloudflare, Amazon CloudFront) — копії статичних файлів на серверах по всьому світу, ближче до користувача: швидше і менше навантаження на ваш сервер. Серверний кеш (Redis, Memcached) — готові результати важких запитів до БД."}, {"title": "Лекція 4 · Архітектура вебзастосунків: HTTP, REST API, N-tier і мікросервіси", "section": "Проксі, балансування L4/L7 і TLS детально", "url": "lectures/week-1/lecture-4.html#proxy-tls", "text": "Проксі, балансування L4/L7 і TLS детально Forward proxy стоїть біля клієнтів і ходить в інтернет від їхнього імені фільтрація, кешування, приховування клієнтів корпоративний проксі, Squid Reverse proxy стоїть перед серверами і приймає запити від імені сервісу TLS-термінація, балансування, кеш, захист бекендів Nginx, HAProxy, Traefik, Cloudflare Балансування L4 (транспортне) Балансування L7 (прикладне) На що дивиться IP і порт (TCP/UDP) вміст HTTP: шлях, заголовки, кукі Можливості дуже швидко, будь-який TCP-протокол (БД, SMTP) маршрутизація /api → API-сервіс, /static → CDN; TLS-термінація, переписування заголовків Приклади AWS Network Load Balancer, HAProxy у режимі tcp AWS Application Load Balancer, Nginx, Traefik Sticky sessions (прив'язка сесії) — балансувальник відправляє клієнта завжди на той самий сервер (за кукі або IP). Це милиця для застосунків, що тримають сесію в пам'яті; краще зробити застосунок stateless. TLS-рукостискання (TLS 1.3, спрощено) ClientHello : клієнт називає підтримувані версії й шифри, ім'я сайту (SNI) і свою частину обміну ключами. ServerHello + сертифікат : сервер обирає шифр, надсилає свою частину обміну ключами і сертифікат . Клієнт перевіряє сертифікат : підпис довіреного центру сертифікації (CA), ім'я домену, строк дії, чи не відкликано. Обидві сторони обчислюють спільний сеансовий ключ (алгоритм Діффі–Геллмана); далі дані шифруються швидким симетричним шифром (AES, ChaCha20). Ланцюжок довіри : сертифікат сайту підписаний проміжним CA, той — кореневим CA, який вбудовано в ОС або браузер. Якщо сервер не віддає проміжний сертифікат, частина клієнтів побачить помилку. Перевірити: openssl s_client -connect example.com:443 -servername example.com ; строк дії: … | openssl x509 -noout -dates . TLS-термінація на балансувальнику: шифрування знімається на вході, а до бекендів трафік іде по внутрішній мережі (іноді знову шифрується — end-to-end TLS). Так сертифікат зберігається в одному місці, а не на кожному сервері."}, {"title": "Лекція 4 · Архітектура вебзастосунків: HTTP, REST API, N-tier і мікросервіси", "section": "Типові помилки", "url": "lectures/week-1/lecture-4.html#mistakes", "text": "Типові помилки 401 і 403 — одне й те саме. 401 — не автентифіковано (хто ви?), 403 — автентифіковано, але немає прав. Basic Auth шифрує пароль. Base64 — лише кодування, його декодує будь-хто. Basic Auth безпечний тільки поверх HTTPS. POST ідемпотентний, бо «просто надсилає дані». Повторний POST зазвичай створює ще один ресурс. Ідемпотентні GET, PUT, DELETE, HEAD. Помилку CORS можна відтворити через curl. CORS — правило браузера. curl отримає відповідь, а браузер не дасть JavaScript її прочитати без заголовка Access-Control-Allow-Origin. HTTPS — окремий протокол замість HTTP. Це той самий HTTP, загорнутий у шифрований канал TLS (порт 443). POST безпечний, бо дані «сховані». POST лише не показує дані в URL. Без HTTPS тіло запиту передається відкритим текстом, як і кукі. Сервер сам пам'ятає, що я залогінений. HTTP stateless. «Пам'ять» забезпечують cookies/токени, які клієнт надсилає з кожним запитом. URL і URI — різні непов'язані речі. URL — підмножина URI: ідентифікатор, що ще й вказує розташування ресурсу. Видаляти через GET /deleteBook?id=3 — нормально. Технічно можливо, але порушує семантику: GET має бути безпечним (його кешують, префетчать). Для видалення — DELETE /book/3 ."}, {"title": "Лекція 5 · LAMP і SQL: Apache, Nginx, MySQL, запити, JOIN і транзакції", "section": "Вступ", "url": "lectures/week-1/lecture-5.html", "text": ""}, {"title": "Лекція 5 · LAMP і SQL: Apache, Nginx, MySQL, запити, JOIN і транзакції", "section": "Чого ви навчитесь", "url": "lectures/week-1/lecture-5.html#goals", "text": "Чого ви навчитесь Пояснити, з чого складається LAMP і чим від нього відрізняється LEMP. Орієнтуватися в конфігурації Apache: httpd.conf , DocumentRoot , <Directory> , <VirtualHost> , модулі. Розуміти, навіщо mod_rewrite , .htaccess і директива AllowOverride . Знайти й прочитати логи Apache ( ErrorLog , CustomLog ). Відтворити послідовність розгортання PHP-застосунку на CentOS і зробити бекап БД. Розрізняти групи SQL-команд ( DDL, DML, DCL ) і писати базові запити: SELECT … WHERE з BETWEEN , IN , LIKE , IS NULL , а також GROUP BY і JOIN . Безпечно змінювати конфіг ( configtest → reload ), порівняти Apache і Nginx, PHP-FPM, налаштувати HTTPS і діагностувати 403/404/500/502. Знати групи SQL (DDL, DML, DQL, DCL, TCL), типи даних і обмеження, створювати таблиці з ключами. Писати SELECT з WHERE ( BETWEEN , IN , LIKE , IS NULL ), ORDER BY, LIMIT, агрегатами, GROUP BY і HAVING; передбачати результат на прикладі. Розрізняти INNER, LEFT, RIGHT, FULL і CROSS JOIN; писати підзапити, UNION. Розуміти DELETE vs TRUNCATE vs DROP, транзакції й ACID, GRANT/REVOKE, індекси і захист від SQL-ін'єкцій."}, {"title": "Лекція 5 · LAMP і SQL: Apache, Nginx, MySQL, запити, JOIN і транзакції", "section": "Що таке LAMP", "url": "lectures/week-1/lecture-5.html#stack", "text": "Що таке LAMP LAMP реалізує 3-рівневу архітектуру з лекції 4: клієнт (браузер) → сервер застосунку (вебсервер) → сервер БД . LAMP = Linux + Apache + MySQL + PHP (історично P — також Perl або Python). Apache HTTP Server Вебсервер Виріс із NCSA HTTPd (Роб МакКул). Назву пояснюють як «a patchy server» — сервер із латками. За статистикою зі слайдів (2018) — 43% активних сайтів. MySQL СКБД Створена MySQL AB (1995), у 2008 куплена Sun, у 2010 разом із Sun — Oracle. Сумісний форк — MariaDB. PHP Скриптова мова Расмус Лердорф, 1994. Ключові версії: PHP 5 (2004), PHP 7 (2015), PHP 8 (2020). Популярний фреймворк — Laravel. Чому LAMP досі вивчають? У чаті лекції було гаряче обговорення «застарілості». Позиція інструктора: стек простий, дає швидкий результат і показує принципи, які потім переносяться на NGINX, Node.js чи Java/Tomcat. Близько третини сайтів працює на WordPress, тобто на LAMP. На практиці часто комбінують Apache + NGINX (NGINX спереду як проксі)."}, {"title": "Лекція 5 · LAMP і SQL: Apache, Nginx, MySQL, запити, JOIN і транзакції", "section": "Конфігурація Apache", "url": "lectures/week-1/lecture-5.html#config", "text": "Конфігурація Apache Apache налаштовується директивами в текстових файлах. Головний файл — httpd.conf (у CentOS: /etc/httpd/conf/httpd.conf ; у Debian/Ubuntu: /etc/apache2/apache2.conf + каталоги sites-enabled , mods-enabled ). Типи файлів (MIME) читаються з mime.types (директива TypesConfig ). Віртуальні хости і модулі рекомендують виносити в окремі файли. Директива Призначення DocumentRoot Каталог, з якого віддаються файли. Шлях з URL додається до нього: /var/www/html + /shop/index.php <Directory> Група директив для каталогу, його підкаталогів і файлів <VirtualHost> Налаштування окремого сайту — кілька доменів на одному сервері LoadModule Підключити модуль (кожен модуль має свої директиви) AllowOverride Які директиви дозволено перевизначати в .htaccess ErrorLog , CustomLog , LogFormat Журнал помилок, журнал доступу та його формат <VirtualHost *:80> ServerName shop.example.com DocumentRoot /var/www/html/opencart/upload <Directory /var/www/html/opencart/upload> AllowOverride All # дозволити .htaccess (потрібно для mod_rewrite) Require all granted </Directory> ErrorLog /var/log/httpd/shop-error.log CustomLog /var/log/httpd/shop-access.log combined </VirtualHost> Модулі Apache має модульну архітектуру : ядро — mod_core , решта підключаються через LoadModule . Часто використовувані: ssl , rewrite , proxy , userdir , headers , php . mod_rewrite — переписує URL «на льоту» за правилами на основі регулярних виразів (PCRE). Може мапити URL на файл, робити редирект або внутрішній проксі-запит. Директиви: RewriteEngine , RewriteRule , RewriteCond , RewriteBase , RewriteMap , RewriteOptions . Саме він робить «гарні» URL типу /product/42 замість index.php?route=product&id=42 . mod_proxy — перетворює Apache на проксі/шлюз, підтримує протоколи і алгоритми балансування навантаження. RewriteEngine On RewriteCond %{REQUEST_FILENAME} !-f # якщо такого файла немає… RewriteRule ^product/([0-9]+)$ index.php?id=$1 [L] # …передати в PHP .htaccess і AllowOverride .htaccess («розподілений конфіг») — файл із директивами в каталозі сайту, що діє на цей каталог і всі вкладені. Потрібен, коли власник сайту не має root-доступу до сервера. Директива AllowOverride визначає, що з нього застосову"}, {"title": "Лекція 5 · LAMP і SQL: Apache, Nginx, MySQL, запити, JOIN і транзакції", "section": "Практика: розгортання OpenCart на CentOS", "url": "lectures/week-1/lecture-5.html#deploy", "text": "Практика: розгортання OpenCart на CentOS На лекції розгортали інтернет-магазин OpenCart 2.x. Послідовність — типова для будь-якого PHP-застосунку. Підготовка ОС (лише для навчального стенда!). Вимкнути firewalld і SELinux, підключити репозиторій EPEL, за проблем із DNS прописати nameserver 8.8.8.8 у /etc/resolv.conf . MySQL. Додати репозиторій MySQL, встановити mysql-community-server , увімкнути автозапуск і запустити, знайти тимчасовий пароль у /var/log/mysqld.log , запустити mysql_secure_installation . Користувач і БД. Створити користувача, видати права, створити БД з кодуванням UTF-8. Apache + PHP. Встановити httpd і пакети PHP ( php-mysql , php-gd , php-mbstring …), увімкнути автозапуск; для mod_rewrite змінити AllowOverride None → All . Код застосунку. Завантажити архів ( wget ), розпакувати ( unzip ), скопіювати в /var/www/html , створити config.php з config-dist.php , віддати файли користувачу apache . Веб-інсталятор. Відкрити http://IP/opencart/upload/install/ , ввести параметри БД; після встановлення видалити каталог install/ . # сервіси керуються через systemctl systemctl enable --now mysqld # автозапуск + старт (enable і start в одній команді) systemctl status mysqld grep password /var/log/mysqld.log # тимчасовий пароль root mysql_secure_installation yum -y install httpd php php-mysql php-gd php-mbstring php-xml systemctl enable --now httpd cp -r opencart /var/www/html/ chmod -R 775 /var/www/html/opencart chown -R apache:apache /var/www/html/opencart systemctl restart httpd CREATE USER 'shop'@'localhost' IDENTIFIED BY 'StrongPass!1'; -- локальний доступ CREATE USER 'shop'@'%' IDENTIFIED BY 'StrongPass!1'; -- з будь-якого хоста GRANT ALL ON opencart.* TO 'shop'@'localhost'; CREATE DATABASE opencart CHARACTER SET utf8 COLLATE utf8_bin; SHOW DATABASES; 'user'@'localhost' і 'user'@'%' — різні облікові записи MySQL: перший підключається лише з цього ж сервера, другий — з будь-якої адреси. На слайдах права видаються як GRANT ALL ON *.* (на всі БД) — для стенда ок, для production давайте права лише на потрібну БД. Нюанси зі слайдів Старий OpenCart 2.x не працював з новим механізмом автентифікації MySQL 8 і з режимом sql_mode = 'MYSQL40' , тому на лекції кори"}, {"title": "Лекція 5 · LAMP і SQL: Apache, Nginx, MySQL, запити, JOIN і транзакції", "section": "Експлуатація вебсервера: перевірка конфігу, Nginx, PHP-FPM, HTTPS, діагностика", "url": "lectures/week-1/lecture-5.html#ops", "text": "Експлуатація вебсервера: перевірка конфігу, Nginx, PHP-FPM, HTTPS, діагностика Безпечна зміна конфігурації sudo apachectl configtest # або httpd -t / apache2ctl -t: перевірити синтаксис → \"Syntax OK\" sudo systemctl reload httpd # перечитати конфіг без розриву поточних з'єднань sudo systemctl restart httpd # повний перезапуск (з розривом) apachectl -S # які віртуальні хости завантажено і з яких файлів apachectl -M # список модулів # Debian/Ubuntu: a2ensite shop.conf, a2enmod rewrite, a2dismod …, потім reload apache2 Правило: спочатку configtest, потім reload . Помилка в конфігу при restart зупинить сервер і всі сайти на ньому, а reload з помилкою залишить працювати стару конфігурацію. Apache vs Nginx Apache httpd Nginx Модель обробки MPM на вибір: prefork (процес на з'єднання, потрібен для старого mod_php), worker (потоки), event (сучасний за замовчуванням) асинхронна подієва: кілька worker-процесів обслуговують тисячі з'єднань PHP вбудований модуль mod_php або PHP-FPM лише через PHP-FPM (FastCGI) Децентралізований конфіг .htaccess у каталогах немає, лише центральні файли (швидше) Типова роль сервер застосунку, хостинг з .htaccess статика, reverse proxy , балансувальник, TLS-термінація LEMP = Linux + Nginx («engine-x») + MySQL + PHP. Популярна схема: Nginx на портах 80/443 віддає статику і проксіює запити на Apache або PHP-FPM на локальному порту. server { listen 80; server_name shop.example.com; root /var/www/shop; location / { try_files $uri $uri/ /index.php?$args; } location ~ \\.php$ { include fastcgi_params; fastcgi_pass unix:/run/php/php8.3-fpm.sock; # PHP виконує окремий сервіс php-fpm fastcgi_param SCRIPT_FILENAME $document_root$fastcgi_script_name; } } HTTPS за хвилину sudo apt install certbot python3-certbot-apache # або python3-certbot-nginx sudo certbot --apache -d shop.example.com # безкоштовний сертифікат Let's Encrypt + налаштування VirtualHost :443 sudo certbot renew --dry-run # перевірити автопродовження (сертифікат діє 90 днів) Діагностика типових помилок Симптом Найчастіша причина Де дивитися Сайт не відкривається взагалі служба не запущена, порт закритий фаєрволом / Security Group systemctl status httpd , ss -tlnp | grep :80 , firewall-cmd --li"}, {"title": "Лекція 5 · LAMP і SQL: Apache, Nginx, MySQL, запити, JOIN і транзакції", "section": "Резервні копії БД", "url": "lectures/week-1/lecture-5.html#backup", "text": "Резервні копії БД mysqldump --all-databases > dump.sql # усі БД mysqldump -u root -p opencart > opencart.sql # одна БД mysql -u root -p opencart < opencart.sql # відновлення Зверніть увагу на напрямок перенаправлення з лекції 2: > — вивантажити дамп у файл, < — подати файл на вхід клієнту mysql . Як робити бекапи правильно mysqldump --single-transaction --routines --triggers shop | gzip > shop_$(date +%F).sql.gz # --single-transaction: узгоджений знімок InnoDB без блокування таблиць на час дампу gunzip < shop_2026-11-07.sql.gz | mysql -u root -p shop # відновлення зі стисненого дампу mysqldump -u root -p shop product category > two_tables.sql # лише окремі таблиці mysqldump --no-data shop > schema.sql # лише структура (DDL) Правило 3-2-1 : три копії даних, на двох різних носіях, одна — поза основним майданчиком (інший регіон хмари, об'єктне сховище S3). Автоматизуйте : cron або systemd timer + ротація старих копій (скрипт у лекції 3). Перевіряйте відновлення : бекап, з якого жодного разу не відновлювались, — лише надія. Регулярно розгортайте дамп у тестову БД. Не зберігайте пароль у командному рядку (його видно в ps та історії): використовуйте ~/.my.cnf з правами 600 . У хмарі для керованих БД (AWS RDS, Cloud SQL) бекапи і point-in-time recovery вмикаються налаштуванням."}, {"title": "Лекція 5 · LAMP і SQL: Apache, Nginx, MySQL, запити, JOIN і транзакції", "section": "SQL: реляційна модель і групи команд", "url": "lectures/week-1/lecture-5.html#sql", "text": "SQL: реляційна модель і групи команд SQL (Structured Query Language) — декларативна мова роботи з реляційними БД: MySQL/MariaDB, PostgreSQL, MS SQL Server, Oracle, SQLite. «Декларативна» означає, що ви описуєте що отримати, а як саме шукати, вирішує СКБД. Реляційна модель Table / relation Таблиця Набір однотипних записів, напр. product . Row / record / tuple Рядок Один запис: один товар. Column / field / attribute Стовпець Властивість із типом даних: price DECIMAL(10,2) . Primary key Первинний ключ Унікально ідентифікує рядок, не може бути NULL . Часто id INT AUTO_INCREMENT . Foreign key Зовнішній ключ Стовпець, що посилається на первинний ключ іншої таблиці; СКБД не дасть послатися на неіснуючий рядок. NULL Відсутнє значення «Невідомо / немає». Це не 0 і не порожній рядок. Групи команд SQL Група Для чого Команди DDL — Data Definition Language структура: БД, таблиці, індекси, представлення CREATE , ALTER , DROP , TRUNCATE , RENAME DML — Data Manipulation Language дані в таблицях INSERT , UPDATE , DELETE (і SELECT у класифікації, де немає окремої DQL) DQL — Data Query Language вибірка даних SELECT DCL — Data Control Language права доступу GRANT , REVOKE TCL — Transaction Control Language транзакції BEGIN / START TRANSACTION , COMMIT , ROLLBACK , SAVEPOINT Підручники розходяться, куди віднести SELECT : до DML (класичний поділ на чотири групи) або в окрему DQL. Якщо в тесті є варіант DQL — SELECT відносять туди; якщо ні — до DML. TRUNCATE змінює дані, але належить до DDL : він перестворює таблицю, а не видаляє рядки по одному. Типи даних (MySQL) Тип Для чого Приклад INT , BIGINT , TINYINT цілі числа різного розміру stock INT DECIMAL(p,s) точні дробові (гроші): p цифр, з них s після коми price DECIMAL(10,2) FLOAT , DOUBLE наближені дробові (не для грошей) координати, вимірювання VARCHAR(n) / CHAR(n) рядок змінної / фіксованої довжини name VARCHAR(100) TEXT довгий текст опис товару DATE , DATETIME , TIMESTAMP дата / дата й час created_at DATETIME BOOLEAN у MySQL — синонім TINYINT(1) : 0 або 1 is_active BOOLEAN Навчальна схема: магазин Усі приклади нижче виконуються на цих двох таблицях. Зверніть увагу на «незручні» дані: товар без категорії і категорія без товарів — "}, {"title": "Лекція 5 · LAMP і SQL: Apache, Nginx, MySQL, запити, JOIN і транзакції", "section": "SELECT і фільтрація WHERE", "url": "lectures/week-1/lecture-5.html#select", "text": "SELECT і фільтрація WHERE Повна структура запиту і порядок виконання SELECT [DISTINCT] стовпці, вирази AS псевдонім -- 5. що показати FROM таблиця [JOIN інша ON умова] -- 1. звідки WHERE умова на рядки -- 2. фільтр рядків GROUP BY стовпці -- 3. групування HAVING умова на групи -- 4. фільтр груп ORDER BY стовпці [ASC|DESC] -- 6. сортування LIMIT n [OFFSET m]; -- 7. обмеження кількості Записують у такому порядку, а виконується запит у порядку номерів у коментарях. Звідси правило: у WHERE не можна використати псевдонім з SELECT чи агрегатну функцію (вони ще не обчислені), а в ORDER BY — можна. Базові вибірки SELECT * FROM product; -- усі стовпці й рядки SELECT name, price * 0.9 AS sale_price FROM product; -- вираз з псевдонімом SELECT DISTINCT category_id FROM product; -- унікальні значення: 1, 2, 3, 4, NULL SELECT name, price FROM product ORDER BY price DESC LIMIT 3; ORDER BY price DESC LIMIT 3 name price ThinkPad X1 1800 MacBook Air 1200 iPhone 15 1000 ORDER BY без вказівки напрямку сортує за зростанням ( ASC ). Без ORDER BY порядок рядків не гарантовано . Кілька ключів: ORDER BY category_id, price DESC . Пагінація: LIMIT 10 OFFSET 20 — рядки 21–30. Оператори в WHERE з результатами Умова Результат на нашій таблиці Важливо price > 1000 ThinkPad X1, MacBook Air операції: = <> != < > <= >= ; <> — стандартне «не дорівнює» price BETWEEN 900 AND 1200 MacBook Air, Galaxy S24, iPhone 15 обидві межі включно : те саме, що price >= 900 AND price <= 1200 price BETWEEN 1200 AND 900 жодного рядка спочатку має йти менша межа price NOT BETWEEN 100 AND 1000 ThinkPad, MacBook, USB-C Hub, Laptop Stand поза діапазоном category_id IN (1, 3) ThinkPad, MacBook, iPad 10 перелік через кому; те саме, що category_id = 1 OR category_id = 3 name LIKE 'i%' iPhone 15, iPad 10 % — будь-яка кількість будь-яких символів (і нуль) name LIKE '%Hub' USB-C Hub закінчується на Hub name LIKE '%Book%' MacBook Air містить Book (у MySQL за замовчуванням без урахування регістру) name LIKE 'iPa_ 10' iPad 10 _ — рівно один символ category_id IS NULL Laptop Stand category_id = NULL поверне 0 рядків stock = 0 OR price < 50 MacBook Air, USB-C Hub, Laptop Stand AND виконується раніше за OR : ставте дужки Задача з"}, {"title": "Лекція 5 · LAMP і SQL: Apache, Nginx, MySQL, запити, JOIN і транзакції", "section": "Агрегатні функції, GROUP BY і HAVING", "url": "lectures/week-1/lecture-5.html#group", "text": "Агрегатні функції, GROUP BY і HAVING Функція Що рахує На нашій таблиці COUNT(*) кількість рядків 7 COUNT(category_id) кількість не-NULL значень стовпця 6 COUNT(DISTINCT category_id) кількість різних не-NULL значень 4 SUM(stock) сума 97 AVG(price) середнє (NULL ігноруються) 775 MIN(price) / MAX(price) мінімум / максимум 35 / 1800 Групування SELECT category_id, COUNT(*) AS cnt, AVG(price) AS avg_price, SUM(stock) AS total_stock FROM product GROUP BY category_id; category_id cnt avg_price total_stock NULL 1 35 20 1 2 1500 5 2 2 950 19 3 1 450 3 4 1 40 50 GROUP BY збирає рядки з однаковим значенням у групу, і агрегатні функції рахуються для кожної групи окремо . Усі рядки з NULL потрапляють в одну групу. Правило: у SELECT разом з агрегатами можна писати лише стовпці з GROUP BY (MySQL у старих режимах це дозволяв, але повертав випадкове значення). WHERE vs HAVING SELECT category_id, COUNT(*) AS cnt FROM product WHERE price > 100 -- 1) спершу відкидаємо дешеві товари (рядки) GROUP BY category_id HAVING COUNT(*) >= 2; -- 2) потім залишаємо лише групи з 2+ товарами -- результат: (1, 2), (2, 2) WHERE фільтрує рядки виконується до групування агрегатні функції в ньому заборонені: WHERE COUNT(*) > 1 — помилка HAVING фільтрує групи виконується після GROUP BY умови з агрегатами: HAVING AVG(price) > 500"}, {"title": "Лекція 5 · LAMP і SQL: Apache, Nginx, MySQL, запити, JOIN і транзакції", "section": "JOIN, підзапити, UNION", "url": "lectures/week-1/lecture-5.html#join", "text": "JOIN, підзапити, UNION JOIN з'єднує рядки двох таблиць за умовою, зазвичай «зовнішній ключ = первинний ключ». Види JOIN. Зафарбовано рядки, що потраплять у результат. «Ліва» таблиця (A) — та, що стоїть у FROM. INNER JOIN — лише пари, що знайшлися в обох таблицях SELECT p.name AS product, c.name AS category FROM product p INNER JOIN category c ON p.category_id = c.id; -- слово INNER можна не писати: JOIN = INNER JOIN 6 рядків: Laptop Stand (без категорії) і Monitors (без товарів) відсутні. LEFT JOIN — усі рядки лівої таблиці SELECT c.name AS category, p.name AS product FROM category c LEFT JOIN product p ON p.category_id = c.id; category product Laptops ThinkPad X1 Laptops MacBook Air Phones Galaxy S24 Phones iPhone 15 Tablets iPad 10 Accessories USB-C Hub Monitors NULL Так знаходять «сирітські» записи: категорії без товарів — … LEFT JOIN … WHERE p.id IS NULL . Інші види RIGHT JOIN — дзеркально: усі рядки правої таблиці. product p RIGHT JOIN category c = category c LEFT JOIN product p . FULL OUTER JOIN — усі рядки обох таблиць (у MySQL немає, емулюють LEFT JOIN … UNION … RIGHT JOIN ; у PostgreSQL є). CROSS JOIN — декартів добуток: кожен рядок з кожним (7 × 5 = 35 рядків). Виходить і тоді, коли забули умову ON . Self join — таблиця з'єднується сама з собою (співробітник і його керівник у тій самій таблиці). Підзапити -- товари, дорожчі за середню ціну (775): ThinkPad, MacBook, Galaxy, iPhone SELECT name, price FROM product WHERE price > (SELECT AVG(price) FROM product); -- категорії, в яких є хоч один товар на складі SELECT name FROM category c WHERE EXISTS (SELECT 1 FROM product p WHERE p.category_id = c.id AND p.stock > 0); -- товари з категорій, назва яких починається на P або T SELECT name FROM product WHERE category_id IN (SELECT id FROM category WHERE name LIKE 'P%' OR name LIKE 'T%'); UNION UNION об'єднує результати двох запитів з однаковою кількістю й типами стовпців і прибирає дублікати ; UNION ALL залишає дублікати (і працює швидше). SELECT name FROM category UNION SELECT name FROM product; -- спільний список назв"}, {"title": "Лекція 5 · LAMP і SQL: Apache, Nginx, MySQL, запити, JOIN і транзакції", "section": "Зміна даних і структури, транзакції, права, індекси", "url": "lectures/week-1/lecture-5.html#modify", "text": "Зміна даних і структури, транзакції, права, індекси INSERT, UPDATE, DELETE INSERT INTO category (id, name) VALUES (6, 'Cameras'); INSERT INTO product (name, price, category_id) VALUES ('Sony A7', 2100, 6), ('GoPro 12', 400, 6); UPDATE product SET price = price * 0.9 WHERE category_id = 1; -- знижка 10% на ноутбуки UPDATE product SET stock = 0; -- УВАГА: без WHERE — уся таблиця DELETE FROM product WHERE stock = 0 AND price < 100; DELETE FROM product; -- без WHERE — усі рядки Звичка, що рятує дані: перед UPDATE / DELETE запустіть SELECT з тією самою умовою WHERE і перевірте, які рядки зачепить. Клієнт mysql --safe-updates відмовляється виконувати їх без WHERE по ключу. DELETE vs TRUNCATE vs DROP DELETE FROM t TRUNCATE TABLE t DROP TABLE t Група DML DDL DDL Що видаляє рядки (усі або за WHERE ) усі рядки таблицю повністю: дані + структуру WHERE можна не можна — Швидкість повільно (по рядку, з журналом) дуже швидко швидко Лічильник AUTO_INCREMENT не скидається скидається — Відкат у транзакції (InnoDB) так ні (неявний COMMIT) ні ALTER TABLE ALTER TABLE product ADD COLUMN created_at DATETIME DEFAULT CURRENT_TIMESTAMP; ALTER TABLE product MODIFY name VARCHAR(150) NOT NULL; ALTER TABLE product RENAME COLUMN stock TO quantity; -- MySQL 8+ ALTER TABLE product DROP COLUMN created_at; ALTER TABLE product ADD INDEX idx_price (price); Транзакції і ACID Транзакція — група операцій, що виконується як одне ціле: або всі, або жодна. Класичний приклад — переказ грошей: списати з одного рахунку й зарахувати на інший. START TRANSACTION; UPDATE account SET balance = balance - 100 WHERE id = 1; UPDATE account SET balance = balance + 100 WHERE id = 2; COMMIT; -- зафіксувати; при помилці замість COMMIT — ROLLBACK (скасувати все) Властивість Значення A tomicity — атомарність усе або нічого C onsistency — узгодженість після транзакції дані відповідають усім правилам (ключі, обмеження) I solation — ізоляція паралельні транзакції не бачать проміжних станів одна одної D urability — довговічність після COMMIT дані збережено навіть при збої живлення У MySQL транзакції підтримує рушій InnoDB (за замовчуванням з версії 5.5); старий MyISAM — ні. За замовчуванням увімкнено autocommit : кожна окрема"}, {"title": "Лекція 5 · LAMP і SQL: Apache, Nginx, MySQL, запити, JOIN і транзакції", "section": "Типові помилки", "url": "lectures/week-1/lecture-5.html#mistakes", "text": "Типові помилки WHERE email = NULL знайде рядки без email. Порівняння з NULL дає UNKNOWN, тож 0 рядків. Правильно: IS NULL / IS NOT NULL . BETWEEN 2 AND 4 не включає межі. Включає обидві: це >= 2 AND <= 4 . І менша межа має йти першою. WHERE COUNT(*) > 1 відфільтрує групи. Агрегати в WHERE заборонені — фільтр груп пишуть у HAVING після GROUP BY . TRUNCATE — це DML, як DELETE. TRUNCATE належить до DDL: швидко перестворює таблицю, без WHERE, скидає AUTO_INCREMENT і не відкочується. COUNT(column) завжди дорівнює кількості рядків. COUNT(column) не рахує NULL; кількість рядків — COUNT(*) . Після зміни конфігу Apache — одразу restart . Спочатку apachectl configtest , потім reload : помилка в конфігу при restart зупинить усі сайти. WHERE email = NULL знайде записи без email. З NULL порівнюють лише через IS NULL / IS NOT NULL . BETWEEN не включає межі, або порядок меж не важливий. BETWEEN 2 AND 4 включає 2 і 4; нижня межа має бути першою. Правила .htaccess «не працюють», хоча файл на місці. Перевірте AllowOverride для каталогу (при None файл ігнорується) і чи завантажено mod_rewrite . Після змін у конфігу — systemctl restart httpd . Сайт видає 403/500 — одразу chmod -R 777 . Спершу error_log . Зазвичай досить віддати файли користувачу вебсервера ( chown -R apache:apache ) з правами 755/644. Вимкнути firewall і SELinux на production, як на лабі. На production відкривають лише потрібні порти (80/443) і налаштовують SELinux-контексти, а не вимикають захист. Забути видалити install/ після встановлення CMS. Каталог інсталятора дозволяє перевстановити сайт і перезаписати БД — його видаляють одразу."}, {"title": "Лекція 6 · Комп'ютерні мережі: OSI і TCP/IP, IPv4 і IPv6, DHCP, DNS, NAT, VPN, QoS", "section": "Вступ", "url": "lectures/week-2/lecture-6.html", "text": ""}, {"title": "Лекція 6 · Комп'ютерні мережі: OSI і TCP/IP, IPv4 і IPv6, DHCP, DNS, NAT, VPN, QoS", "section": "Чого ви навчитесь", "url": "lectures/week-2/lecture-6.html#goals", "text": "Чого ви навчитесь Пояснити кожен рівень OSI і TCP/IP : функцію, протоколи, одиницю даних (PDU) і пристрої. Розрізняти адреси MAC , IP і порт , пояснити роботу ARP і знати основні порти напам'ять. Описати TCP (рукостискання, гарантії) і UDP, а також види передачі: unicast, broadcast, multicast, anycast. Переводити IPv4 у двійковий вигляд, рахувати за IP і маскою адресу мережі, broadcast, діапазон і кількість хостів, ділити мережу на підмережі. Знати класи IPv4, приватні та всі спеціальні діапазони: loopback, APIPA, multicast, Class E, 0.0.0.0. Скорочувати і розгортати IPv6, знати типи адрес (link-local, unique local, global, multicast), EUI-64, SLAAC, NDP і механізми переходу (dual stack, 6to4, Teredo/Miredo, NAT64). Розібрати DHCP (DORA, scope, lease, reservation, relay) і DNS (ієрархія, рекурсія, типи записів). Пояснити NAT (static, dynamic, PAT, port forwarding), VPN, QoS/CoS/DSCP, ACL і фаєрволи. Діагностувати мережу знизу вгору: ip , ping , traceroute , ss , dig , curl , nc ."}, {"title": "Лекція 6 · Комп'ютерні мережі: OSI і TCP/IP, IPv4 і IPv6, DHCP, DNS, NAT, VPN, QoS", "section": "Мережа, протокол, пристрої", "url": "lectures/week-2/lecture-6.html#basics", "text": "Мережа, протокол, пристрої Сучасне ПЗ здебільшого розподілене : браузер, вебсервер, база даних, кеш і черги працюють на різних машинах і спілкуються мережею за моделлю клієнт-сервер . Клієнт ініціює запит і чекає відповіді; сервер слухає порт і відповідає, сам обмін не починає. Визначення Протокол — набір правил обміну даними: формат повідомлень і значення полів, порядок надсилання й отримання, реакція на помилки, взаємодія з сусідніми рівнями. Приклади: HTTP, TCP, IP, Ethernet. Термін Значення LAN (Local Area Network) локальна мережа: офіс, дім, стійка в дата-центрі WAN (Wide Area Network) мережа, що з'єднує віддалені LAN (інтернет — найбільша WAN) Хост (host, вузол) будь-який пристрій з IP-адресою: сервер, ноутбук, принтер, контейнер Сегмент / підмережа частина мережі, де хости бачать один одного напряму, без маршрутизатора Шлюз за замовчуванням (default gateway) маршрутизатор, якому хост віддає все, що адресовано в інші мережі Пропускна здатність / затримка скільки бітів за секунду (bandwidth, Мбіт/с) / скільки часу йде пакет (latency, мс; RTT — туди й назад) Мережеві пристрої і рівні, на яких вони працюють Пристрій Рівень OSI Що робить Хаб (hub), повторювач (repeater) L1 фізичний повторює сигнал на всі порти, нічого не аналізує. Застарів Комутатор (switch), міст (bridge) L2 канальний вивчає MAC-адреси пристроїв на кожному порту (MAC-таблиця) і пересилає кадр лише в потрібний порт Точка доступу (wireless access point) L2 підключає бездротові пристрої до дротової LAN Маршрутизатор (router) L3 мережевий з'єднує різні IP-мережі, обирає шлях за таблицею маршрутизації, зазвичай робить NAT Комутатор L3 (multilayer switch) L2 + L3 комутатор з функцією маршрутизації між VLAN Фаєрвол (firewall) L3–L4, NGFW — до L7 пропускає або блокує трафік за правилами (адреси, порти, стан з'єднання, вміст) Балансувальник навантаження (load balancer) L4 або L7 розподіляє запити між кількома серверами Проксі-сервер L7 робить запити від імені клієнта (кешування, фільтрація, приховування клієнта)"}, {"title": "Лекція 6 · Комп'ютерні мережі: OSI і TCP/IP, IPv4 і IPv6, DHCP, DNS, NAT, VPN, QoS", "section": "Модель OSI: сім рівнів", "url": "lectures/week-2/lecture-6.html#osi", "text": "Модель OSI: сім рівнів OSI (Open Systems Interconnection, ISO 7498) — еталонна модель, що ділить мережеву взаємодію на 7 рівнів. Кожен рівень вирішує свою задачу і спирається на нижчий. Реальні мережі на неї лише «накладаються»; працює інтернет на стеку TCP/IP. Але OSI — спільна мова: «проблема на L2» одразу каже, що шукати треба в комутаторі чи VLAN, а не в коді застосунку. № Рівень Задача Протоколи і стандарти PDU Пристрої 7 Application (прикладний) мережеві сервіси для застосунків HTTP(S), FTP, SMTP, POP3, IMAP, DNS, DHCP, SSH, Telnet, SNMP, NTP, LDAP дані — 6 Presentation (представлення) формат даних: кодування, стиснення, шифрування ASCII, UTF-8, JPEG, MPEG; шифрування TLS/SSL часто відносять сюди дані — 5 Session (сеансовий) встановлення, підтримка і завершення сеансів NetBIOS, RPC, SMB (частково), PPTP дані — 4 Transport (транспортний) доставка між процесами (порти), надійність, порядок, контроль потоку TCP, UDP сегмент (TCP) / датаграма (UDP) балансувальник L4, фаєрвол 3 Network (мережевий) логічна адресація (IP) і маршрутизація між мережами IPv4, IPv6, ICMP, IPsec, OSPF, BGP пакет маршрутизатор, комутатор L3 2 Data Link (канальний) доставка кадру в межах сегмента за MAC-адресою , виявлення помилок (CRC) Ethernet (802.3), Wi-Fi (802.11), VLAN (802.1Q), ARP, PPP кадр (frame) комутатор, міст, точка доступу, NIC 1 Physical (фізичний) передача бітів сигналом: напруга, світло, радіо; роз'єми, кабелі вита пара (RJ-45), оптика, 802.11 радіо, DSL біти кабель, хаб, повторювач, трансивер Мнемоніка «згори вниз» (7→1): A ll P eople S eem T o N eed D ata P rocessing. «Знизу вгору» (1→7): P lease D o N ot T hrow S ausage P izza A way. Канальний рівень поділяють на два підрівні: LLC (Logical Link Control, зв'язок з L3) і MAC (Media Access Control, доступ до середовища і MAC-адреси)."}, {"title": "Лекція 6 · Комп'ютерні мережі: OSI і TCP/IP, IPv4 і IPv6, DHCP, DNS, NAT, VPN, QoS", "section": "Модель TCP/IP і інкапсуляція", "url": "lectures/week-2/lecture-6.html#tcpip", "text": "Модель TCP/IP і інкапсуляція OSI vs TCP/IP. Верхні три рівні OSI в TCP/IP об'єднані в один Application, нижні два — у Network Access (Link). (*ARP працює на межі L2/L3.) Модель TCP/IP (DoD-модель) має 4 рівні: Application (L5–7 OSI), Transport (L4), Internet (L3), Network Access / Link (L1–2). Деякі підручники рахують 5 рівнів, виділяючи Physical окремо. Назви рівнів у тесті можуть бути будь-якими з цих варіантів — орієнтуйтеся на протоколи: IP — Internet, TCP/UDP — Transport, Ethernet — Network Access. Інкапсуляція і декапсуляція Під час відправлення кожен рівень додає до даних свій заголовок (а канальний — ще й трейлер з контрольною сумою): дані застосунку → TCP-сегмент (порти) → IP-пакет (IP-адреси) → Ethernet-кадр (MAC-адреси, CRC) → біти в кабелі. Отримувач знімає заголовки в зворотному порядку — декапсуляція . Кожен рівень читає лише «свій» заголовок. Інкапсуляція. Кожен рівень загортає дані вищого рівня у свою «обгортку». Що відбувається, коли ви відкриваєте https://example.com DNS (L7, UDP 53): браузер дізнається IP сервера за іменем. TCP (L4): тристороннє рукостискання з портом 443 сервера; ваш порт — випадковий з динамічного діапазону. TLS (L6/L7): узгодження шифрування, перевірка сертифіката. IP (L3): ваш хост порівнює адресу призначення зі своєю мережею (через маску), бачить, що вона чужа, і відправляє пакет на шлюз . ARP (L2/L3): щоб покласти кадр у кабель, потрібна MAC-адреса шлюзу; хост дізнається її ARP-запитом. Ethernet (L2/L1): кадр з MAC шлюзу як отримувачем іде через комутатор до роутера. Маршрутизатори (L3) передають пакет мережа за мережею; на кожному переході MAC-адреси в кадрі змінюються, а IP-адреси (без NAT) лишаються. На вашому роутері NAT замінює приватну адресу відправника на публічну. HTTP (L7): всередині зашифрованого каналу йде GET / , сервер відповідає HTML."}, {"title": "Лекція 6 · Комп'ютерні мережі: OSI і TCP/IP, IPv4 і IPv6, DHCP, DNS, NAT, VPN, QoS", "section": "Три рівні адресації: MAC, IP, порт", "url": "lectures/week-2/lecture-6.html#addressing", "text": "Три рівні адресації: MAC, IP, порт Аналогія з поштою: IP-адреса — адреса будинку, порт — номер квартири (яка програма отримає дані), MAC-адреса — номер конкретного поштового ящика, до якого листоноша несе лист на останньому відрізку шляху. MAC · L2 · 48 біт Фізична адреса інтерфейсу Записується 12 шістнадцятковими цифрами: 3C:52:82:1A:2B:9F (або через дефіс, у Cisco — 3c52.821a.2b9f ). Перші 24 біти — OUI (ідентифікатор виробника), решта — номер пристрою. Діє лише в межах сегмента: маршрутизатор її не пропускає далі. IP · L3 · 32 / 128 біт Логічна адреса вузла Призначається адміністратором, DHCP або автоматично. Складається з частини мережі й частини хоста, тому дає змогу маршрутизувати між мережами. Port · L4 · 16 біт (0–65535) Адреса процесу Дозволяє багатьом програмам ділити одну IP-адресу. Пара IP:порт називається сокетом : 203.0.113.10:443 . MAC-адреса FF:FF:FF:FF:FF:FF — широкомовна (broadcast) на L2: кадр отримають усі пристрої сегмента. Подивитися свою MAC: ip link (рядок link/ether ). ARP: як IP перетворюється на MAC Щоб передати пакет у межах сегмента, потрібна MAC-адреса отримувача (або шлюзу). Її дізнаються протоколом ARP (Address Resolution Protocol, лише IPv4): Хост A ( 192.168.1.10 ) хоче надіслати пакет на 192.168.1.1 . Перевіряє свій ARP-кеш ( ip neigh , у Windows arp -a ). Запису немає → A надсилає широкомовний ARP Request на FF:FF:FF:FF:FF:FF : «Хто має 192.168.1.1? Скажіть 192.168.1.10». Усі в сегменті отримують запит, але відповідає лише власник адреси: unicast ARP Reply «192.168.1.1 — це AA:BB:CC:11:22:33 ». A кладе відповідність у кеш на кілька хвилин і відправляє кадр. Якщо адреса призначення в іншій мережі, хост через ARP шукає MAC не сервера, а шлюзу . В IPv6 ARP немає — цю роль виконує NDP (див. розділ про IPv6)."}, {"title": "Лекція 6 · Комп'ютерні мережі: OSI і TCP/IP, IPv4 і IPv6, DHCP, DNS, NAT, VPN, QoS", "section": "Види передачі: unicast, broadcast, multicast, anycast", "url": "lectures/week-2/lecture-6.html#cast", "text": "Види передачі: unicast, broadcast, multicast, anycast Тип Кому Приклад IPv4 / IPv6 Unicast одному конкретному хосту з унікальною адресою завантаження вебсторінки, SSH є / є Broadcast усім хостам сегмента ARP Request, DHCP Discover є ( 255.255.255.255 — limited, 192.168.1.255 — directed) / немає Multicast групі хостів, які «підписалися» IPTV, протоколи маршрутизації (OSPF — 224.0.0.5 ) 224.0.0.0/4 (Class D) / ff00::/8 Anycast найближчому з кількох вузлів з однаковою адресою кореневі DNS-сервери, публічні DNS 1.1.1.1 , 8.8.8.8 , CDN реалізується маршрутизацією (BGP) / вбудовано в стандарт Broadcast не проходить через маршрутизатор — він обмежує широкомовний домен . Тому, наприклад, DHCP-сервер в іншій підмережі потребує relay-агента."}, {"title": "Лекція 6 · Комп'ютерні мережі: OSI і TCP/IP, IPv4 і IPv6, DHCP, DNS, NAT, VPN, QoS", "section": "Порти і транспортні протоколи", "url": "lectures/week-2/lecture-6.html#ports", "text": "Порти і транспортні протоколи Запит іде з динамічного (ефемерного) порту клієнта на well-known порт сервера: клієнт 192.168.1.10:51234 → сервер 93.184.216.34:443 . Відповідь повертається на 51234. Діапазон Назва Призначення 0–1023 well-known (системні) стандартні служби; у Linux прив'язатися до них може лише root (або з capability) 1024–49151 registered зареєстровані в IANA програми (3306 MySQL, 8080 альтернативний HTTP) 49152–65535 dynamic / private / ephemeral тимчасові порти клієнтів (Linux за замовчуванням бере 32768–60999) Порти, які треба знати напам'ять Порт Протокол Транспорт Призначення 20, 21 FTP TCP передача файлів: 20 — дані, 21 — команди (без шифрування) 22 SSH, SFTP, SCP TCP захищений віддалений доступ і копіювання 23 Telnet TCP віддалений доступ без шифрування (застарілий) 25 SMTP TCP пересилання пошти між серверами (587 — відправлення клієнтом, 465 — SMTPS) 53 DNS UDP (запити), TCP (зонні трансфери, великі відповіді) імена → адреси 67, 68 DHCP UDP 67 — сервер, 68 — клієнт 69 TFTP UDP простий FTP без автентифікації (завантаження по мережі, прошивки) 80 HTTP TCP веб без шифрування 110 / 995 POP3 / POP3S TCP отримання пошти (завантажити і видалити з сервера) 123 NTP UDP синхронізація часу 143 / 993 IMAP / IMAPS TCP робота з поштою на сервері 161, 162 SNMP UDP моніторинг мережевих пристроїв (162 — trap-повідомлення) 389 / 636 LDAP / LDAPS TCP каталоги користувачів (Active Directory) 443 HTTPS TCP (і UDP для HTTP/3) веб через TLS 445 SMB TCP файлові ресурси Windows 514 Syslog UDP централізовані логи 1433 / 1521 MS SQL / Oracle TCP бази даних 3306 MySQL / MariaDB TCP база даних 3389 RDP TCP віддалений робочий стіл Windows 5432 PostgreSQL TCP база даних 6379 / 27017 Redis / MongoDB TCP NoSQL-сховища 8080, 8443 альтернативні HTTP/HTTPS TCP сервери застосунків, Jenkins, проксі TCP: надійна доставка через з'єднання Життя TCP-з'єднання. Тристороннє рукостискання, обмін з підтвердженнями, чотиристороннє закриття. Тристороннє рукостискання (three-way handshake): SYN → SYN-ACK → ACK. Сторони узгоджують початкові порядкові номери (sequence numbers). Нумерація і підтвердження : кожен байт має номер; отримувач підтверджує прийняте (ACK). Не отримав підтвердження "}, {"title": "Лекція 6 · Комп'ютерні мережі: OSI і TCP/IP, IPv4 і IPv6, DHCP, DNS, NAT, VPN, QoS", "section": "Двійкова система: без неї маски не зрозуміти", "url": "lectures/week-2/lecture-6.html#binary", "text": "Двійкова система: без неї маски не зрозуміти IPv4-адреса — це 32 біти . Для людей її записують у десятковому вигляді з крапками (dotted decimal): чотири октети по 8 біт, кожен від 0 до 255. Не шістнадцятковими (так пишуть IPv6 і MAC), не вісімковими і не двійковими — хоча всередині комп'ютера адреса двійкова. Біт (позиція) 8 7 6 5 4 3 2 1 Вага 128 64 32 16 8 4 2 1 Десяткове → двійкове: віднімаємо ваги зліва направо 192 = 128 + 64 → 1 1 0 0 0 0 0 0 168 = 128 + 32 + 8 → 1 0 1 0 1 0 0 0 25 = 16 + 8 + 1 → 0 0 0 1 1 0 0 1 100 = 64 + 32 + 4 → 0 1 1 0 0 1 0 0 192.168.25.100 = 11000000.10101000.00011001.01100100 Значення октетів маски, які варто запам'ятати Маска завжди має вигляд «спочатку одиниці, потім нулі», тому в октеті маски можливі лише 9 значень: Двійково 00000000 10000000 11000000 11100000 11110000 11111000 11111100 11111110 11111111 Десятково 0 128 192 224 240 248 252 254 255 Одиниць 0 1 2 3 4 5 6 7 8"}, {"title": "Лекція 6 · Комп'ютерні мережі: OSI і TCP/IP, IPv4 і IPv6, DHCP, DNS, NAT, VPN, QoS", "section": "IPv4: мережа, хост, маска, префікс", "url": "lectures/week-2/lecture-6.html#ipv4", "text": "IPv4: мережа, хост, маска, префікс Старші біти адреси — мережева частина (network ID, P біт), молодші — частина хоста (host ID, N біт), P + N = 32 . Де проходить межа, показує маска підмережі (subnet mask): 32-бітне число, де мережеві біти = 1, хостові = 0. Скорочений запис маски — префікс (CIDR-нотація): /24 означає 24 одиниці, тобто 255.255.255.0 . Головна ідея Саме маска дозволяє визначити, до якого мережевого сегмента належить IP-адреса. Хост виконує побітове «І» (AND) своєї адреси з маскою і адреси призначення з тією самою маскою. Результати збігаються → отримувач у тій самій мережі, кадр іде напряму. Не збігаються → пакет іде на шлюз за замовчуванням. Адреса мережі Усі біти хоста = 0. Ідентифікує підмережу в таблицях маршрутизації, хосту не призначається: 192.168.25.0 . Broadcast Усі біти хоста = 1. Пакет отримають усі в підмережі: 192.168.25.255 . Хосту не призначається. Адреси хостів Усе між ними: .1–.254 . Кількість = 2 N − 2 . Шлюзу зазвичай дають першу ( .1 ) або останню ( .254 ). Побітове І (AND). 1 AND 1 = 1, усе інше = 0. IP & маска = адреса мережі. Алгоритм розрахунку за IP і маскою Знайдіть «цікавий» октет — перший, де маска не 255 і не 0. Якщо маска кратна 8 (/8, /16, /24), рахувати майже нічого не треба. Розмір блоку = 256 − значення маски в цікавому октеті. Мережі починаються з чисел, кратних розміру блоку. Адреса мережі : найбільше кратне розміру блоку, що не перевищує значення октету адреси. Broadcast : адреса наступної мережі − 1. Хости : від (мережа + 1) до (broadcast − 1), кількість 2 N − 2, де N = 32 − префікс. Приклад 1: 192.168.25.100/26 /26 → маска 255.255.255.192, цікавий октет — 4-й (192) розмір блоку = 256 − 192 = 64 → мережі: .0 .64 .128 .192 100 лежить між 64 і 128 мережа 192.168.25.64 broadcast 192.168.25.127 хости 192.168.25.65 – 192.168.25.126 (2^6 − 2 = 62) Приклад 2: 172.16.45.10/20 /20 = 8+8+4 → маска 255.255.240.0, цікавий октет — 3-й (240) розмір блоку = 256 − 240 = 16 → мережі в 3-му октеті: 0, 16, 32, 48 … 45 лежить між 32 і 48 мережа 172.16.32.0 broadcast 172.16.47.255 хости 172.16.32.1 – 172.16.47.254 (2^12 − 2 = 4094) Приклад 3: чи в одній мережі 10.1.1.5/25 і 10.1.1.200/25 ? /25 → 255.255.255.128, блок 128 → мережі "}, {"title": "Лекція 6 · Комп'ютерні мережі: OSI і TCP/IP, IPv4 і IPv6, DHCP, DNS, NAT, VPN, QoS", "section": "Класи IPv4 (classful addressing)", "url": "lectures/week-2/lecture-6.html#classes", "text": "Класи IPv4 (classful addressing) До 1993 року розмір мережі визначався першими бітами адреси — класом. Потім перейшли на CIDR (Classless Inter-Domain Routing), де префікс може бути будь-яким. Класи більше не використовуються для маршрутизації, але їх досі питають на тестах і за ними названо діапазони. Клас Старші біти Перший октет Маска за замовчуванням Мереж Хостів у мережі Призначення A 0 1–126 (0 і 127 зарезервовані) 255.0.0.0 /8 126 16 777 214 дуже великі мережі, unicast B 10 128–191 255.255.0.0 /16 16 384 65 534 середні мережі, unicast C 110 192–223 255.255.255.0 /24 2 097 152 254 малі мережі, unicast D 1110 224–239 — — — multicast E 1111 240–255 — — — зарезервовано для майбутнього (експериментальне) Як швидко визначити клас: перегляньте перший октет. 10.x → A, 172.16.x → B (172 між 128 і 191), 192.168.x → C, 224.0.0.5 → D."}, {"title": "Лекція 6 · Комп'ютерні мережі: OSI і TCP/IP, IPv4 і IPv6, DHCP, DNS, NAT, VPN, QoS", "section": "Приватні, публічні та спеціальні адреси", "url": "lectures/week-2/lecture-6.html#special", "text": "Приватні, публічні та спеціальні адреси Приватні діапазони (RFC 1918) Ці адреси можна вільно використовувати в будь-якій локальній мережі, але в інтернеті вони не маршрутизуються (non-routable): провайдери їх відкидають. Щоб вийти в інтернет з приватної адреси, потрібен NAT. Діапазон Префікс У межах класу Розмір Де зустрічається 10.0.0.0 – 10.255.255.255 10.0.0.0/8 A 16,7 млн корпоративні мережі, VPC у хмарах 172.16.0.0 – 172.31.255.255 172.16.0.0/12 B 1 млн мережі Docker за замовчуванням ( 172.17.0.0/16 ), default VPC AWS ( 172.31.0.0/16 ) 192.168.0.0 – 192.168.255.255 192.168.0.0/16 C 65 тис. домашні роутери ( 192.168.0.0/24 , 192.168.1.0/24 ) Пастки: 172.32.0.1 вже публічна (діапазон закінчується на 172.31), 192.169.1.1 — теж публічна. Зверніть увагу, що 192.168.0.0/16 — це 256 мереж /24, а не одна мережа /24. Спеціальні діапазони Адреси Назва Значення 0.0.0.0/8 , зокрема 0.0.0.0 «ця мережа» / невизначена адреса як адреса відправника — «ще не маю адреси» (DHCP Discover); у налаштуваннях сервера — «слухати на всіх інтерфейсах»; 0.0.0.0/0 — маршрут за замовчуванням (усі адреси) 127.0.0.0/8 loopback звернення до самого себе, пакети не виходять з хоста. Найчастіше 127.0.0.1 = localhost 169.254.0.0/16 link-local / APIPA адреса, яку хост призначає собі сам, якщо не отримав відповідь від DHCP. Працює лише в межах сегмента 100.64.0.0/10 CGNAT (shared address space) адреси, які провайдер дає клієнтам за своїм NAT (carrier-grade NAT) 192.0.2.0/24 , 198.51.100.0/24 , 203.0.113.0/24 TEST-NET-1/2/3 лише для документації і прикладів 224.0.0.0/4 (224–239) multicast (клас D) групова розсилка: 224.0.0.1 — усі хости сегмента, 224.0.0.2 — усі маршрутизатори 240.0.0.0/4 (240–255) зарезервовано (клас E) «для майбутнього використання», хостам не призначається 255.255.255.255 limited broadcast усім у власному сегменті; маршрутизатори не пропускають APIPA детальніше APIPA (Automatic Private IP Addressing) — механізм (у Windows під цією назвою, в Linux — IPv4 link-local, RFC 3927), який спрацьовує, коли клієнт налаштований на DHCP, але жоден сервер не відповів. Хост сам обирає випадкову адресу з 169.254.1.0 – 169.254.254.255 з маскою 255.255.0.0 , перевіряє через ARP, що її ніхто не "}, {"title": "Лекція 6 · Комп'ютерні мережі: OSI і TCP/IP, IPv4 і IPv6, DHCP, DNS, NAT, VPN, QoS", "section": "IPv6 детально", "url": "lectures/week-2/lecture-6.html#ipv6", "text": "IPv6 детально IPv6 (RFC 8200) розроблено, щоб розв'язати дефіцит IPv4: 128 біт адреси дають 2¹²⁸ ≈ 3,4·10³⁸ адрес. Попутно спрощено заголовок, прибрано broadcast і обов'язковий NAT, вбудовано автоналаштування адрес. IPv4 IPv6 Довжина адреси 32 біти 128 біт Запис десятковий, 4 октети через крапку: 192.149.252.76 шістнадцятковий , 8 груп (хекстетів) по 16 біт через двокрапку: 2001:0db8:85a3:0000:0000:8a2e:0370:7334 Розмір мережі маска або префікс лише префікс; типова підмережа — /64 Broadcast є немає , замінено multicast Визначення MAC сусіда ARP NDP (ICMPv6) Автоналаштування DHCP, APIPA SLAAC, DHCPv6, link-local завжди Адрес на інтерфейсі зазвичай одна кілька одночасно (link-local + глобальна + тимчасові) NAT майже обов'язковий через дефіцит не потрібен: адрес вистачає кожному пристрою Loopback 127.0.0.1 ::1 URL з адресою http://192.0.2.1:8080/ у квадратних дужках: http://[2001:db8::1]:8080/ Правила скорочення (RFC 4291, RFC 5952) Ведучі нулі в кожній групі можна прибрати: 0db8 → db8 , 00A7 → A7 , 0000 → 0 . Кінцеві нулі прибирати не можна : 4C00 лишається 4C00 . Одну безперервну послідовність груп, що складаються лише з нулів, можна замінити на :: . Використати :: двічі не можна: тоді невідомо, скільки нулів у кожному пропуску. Рекомендації RFC 5952 для канонічної форми: стискати найдовшу послідовність нулів; якщо є кілька однакової довжини — першу; одну нульову групу не стискати в :: ; писати малими літерами. Розібрані приклади 2001:0db8:0000:0000:0000:0000:0000:0001 → 2001:db8::1 2001:0DB0:0000:123A:0000:0000:0000:0030 → 2001:db0:0:123a::30 (найдовша серія — 3 групи) FE80:00A7:0000:0000:02AA:0000:4C00:FE9A → FE80:A7::2AA:0:4C00:FE9A (серія з 2 груп → ::, одиночна 0 лишається) 0000:0000:0000:0000:0000:0000:0000:0001 → ::1 (loopback) 0000:0000:0000:0000:0000:0000:0000:0000 → :: (невизначена адреса) ff02:0000:0000:0000:0000:0000:0000:0002 → ff02::2 (усі маршрутизатори) Розгортання назад Порахуйте наявні групи і доповніть пропуск :: нульовими групами до восьми. 2001:db8::8a2e:370:7334 : є 5 груп → :: замінює 3 → 2001:0db8:0000:0000:0000:8a2e:0370:7334 . Як перевіряти варіанти «стиснутої» адреси Розгорніть кожен варіант до 8 повних груп і порівняйте з оригіналом. Т"}, {"title": "Лекція 6 · Комп'ютерні мережі: OSI і TCP/IP, IPv4 і IPv6, DHCP, DNS, NAT, VPN, QoS", "section": "Співіснування IPv4 і IPv6: механізми переходу", "url": "lectures/week-2/lecture-6.html#transition", "text": "Співіснування IPv4 і IPv6: механізми переходу Інтернет переходить на IPv6 поступово, тому довгий час обидві версії працюють разом. Механізми переходу поділяють на три групи. Механізм Група Суть Особливості Dual stack подвійний стек хост і мережа одночасно мають і IPv4, і IPv6; з кожним сервером спілкуються тією версією, яку він підтримує найпоширеніший і рекомендований підхід 6in4 (ручний тунель) тунелювання IPv6-пакет вкладається в IPv4-пакет (IP protocol 41) між двома налаштованими кінцями тунельні брокери, напр. Hurricane Electric 6to4 (RFC 3056) тунелювання автоматично інкапсулює IPv6 в IPv4 для передачі IPv4-мережами; IPv6-префікс 2002::/16 будується з публічної IPv4-адреси «обмежений» механізм: потрібна публічна IPv4, не працює за NAT; застарілий (RFC 7526) Teredo (RFC 4380) тунелювання інкапсулює IPv6 в UDP -датаграми IPv4 (порт 3544), тому проходить крізь NAT механізм з нативною підтримкою NAT ; префікс 2001::/32 ; був вбудований у Windows Miredo — відкрита реалізація Teredo (клієнт і сервер) для Linux, BSD, macOS це програма, а не окремий протокол ISATAP тунелювання тунелі IPv6 через IPv4 всередині корпоративної мережі застарілий NAT64 + DNS64 трансляція шлюз перекладає пакети IPv6 ↔ IPv4, щоб клієнти лише з IPv6 бачили IPv4-сайти мобільні мережі, AWS NAT-PT трансляція ранній варіант трансляції протоколів скасований (historic) Як відрізнити у тесті «Інкапсуляція IPv6 в IPv4, обмежений механізм» → 6to4 . «Нативна підтримка NAT» → Teredo . «Miredo» → програмне забезпечення для тунелювання Teredo. «Обидва протоколи одночасно» → dual stack . «4to6» — не стандартна назва (існує 4in6/DS-Lite, але він передає IPv4 всередині IPv6, тобто у зворотному напрямку), 802.3af — стандарт живлення по Ethernet (PoE), eDiscovery — юридичний пошук електронних даних."}, {"title": "Лекція 6 · Комп'ютерні мережі: OSI і TCP/IP, IPv4 і IPv6, DHCP, DNS, NAT, VPN, QoS", "section": "DHCP: автоматична видача адрес", "url": "lectures/week-2/lecture-6.html#dhcp", "text": "DHCP: автоматична видача адрес DHCP (Dynamic Host Configuration Protocol, RFC 2131) — протокол, що замінює ручне налаштування IP-адрес. Клієнт без жодних налаштувань отримує від сервера: IP-адресу, маску, шлюз за замовчуванням, DNS-сервери , ім'я домену, строк оренди та інші опції. Транспорт — UDP : сервер слухає порт 67 , клієнт — 68 . DORA: чотири кроки отримання адреси DORA. Discover і Request — широкомовні: у клієнта ще немає адреси, і він має повідомити всі сервери, чию пропозицію прийняв. Discover : клієнт широкомовно (з 0.0.0.0 на 255.255.255.255 ) шукає сервери. Offer : кожен сервер, що почув, пропонує вільну адресу з параметрами. Request : клієнт обирає одну пропозицію (зазвичай першу) і широкомовно повідомляє, яку саме — інші сервери повертають свої адреси в пул. Acknowledge (ACK) : сервер підтверджує, клієнт налаштовує інтерфейс. Якщо адреса вже недоступна — сервер відповість NAK , і процес почнеться спочатку. Перед використанням клієнт може перевірити адресу через ARP, щоб уникнути конфлікту. Коли адреса більше не потрібна, клієнт надсилає DHCPRELEASE . Ключові поняття DHCP-сервера Термін Значення Приклад Scope (область, pool) діапазон адрес, які сервер може видавати в певній підмережі, разом з її параметрами 192.168.1.100 – 192.168.1.200 , маска /24 Exclusion (виключення) адреси всередині scope, які сервер не видаватиме (для пристроїв зі статичними адресами) .100–.110 для принтерів Lease (оренда) тимчасове призначення адреси на визначений строк 8 годин для гостьового Wi-Fi, 8 днів в офісі Reservation (резервування) постійне призначення: сервер завжди видає пристрою з указаною MAC-адресою одну й ту саму IP MAC принтера 3C:52:… → завжди .150 Options (опції) додаткові параметри 003 — шлюз (router), 006 — DNS-сервери, 015 — ім'я домену, 051 — строк оренди, 066/067 — завантаження по мережі (PXE) DHCP relay (IP helper) агент на маршрутизаторі, що пересилає широкомовні DHCP-запити до сервера в іншій підмережі (broadcast крізь роутер не проходить) Cisco: ip helper-address 10.0.0.5 RFC 2131 описує три способи розподілу: dynamic — адреса на обмежений час (оренда); automatic — постійна адреса, видана сервером автоматично; manual — адреса, яку адміністратор зак"}, {"title": "Лекція 6 · Комп'ютерні мережі: OSI і TCP/IP, IPv4 і IPv6, DHCP, DNS, NAT, VPN, QoS", "section": "DNS: як ім'я перетворюється на адресу", "url": "lectures/week-2/lecture-6.html#dns", "text": "DNS: як ім'я перетворюється на адресу DNS (Domain Name System) — розподілена ієрархічна база даних «ім'я → дані». Людям зручні імена ( www.example.com ), мережі потрібні адреси ( 93.184.215.14 ). Працює на порту 53 : звичайні запити — UDP, великі відповіді та передача зон між серверами — TCP. Ієрархія імен . (корінь, 13 логічних кореневих серверів a–m.root-servers.net) ┌───────────┼───────────┐ com org ua ← TLD (домени верхнього рівня) │ │ example kpi ← домени другого рівня │ │ www campus ← піддомени / імена хостів Повне ім'я (FQDN): www.example.com. ← крапка в кінці — корінь Як відбувається розв'язання імені Програма перевіряє локальний кеш і файл /etc/hosts (порядок задає /etc/nsswitch.conf ). Немає — запит до рекурсивного резолвера з /etc/resolv.conf (провайдер, 8.8.8.8 , 1.1.1.1 , у хмарі — резолвер VPC). Клієнт ставить рекурсивний запит: «дай мені остаточну відповідь». Резолвер, якщо не має відповіді в кеші, робить ітеративні запити: корінь → «питай сервери .com » → сервер .com → «питай ns1.example.com » → авторитетний сервер домену → « www.example.com = 93.184.215.14». Резолвер кешує відповідь на час TTL (time to live, у секундах) і повертає клієнту. TTL пояснює, чому зміни в DNS «поширюються» не одразу: доки не мине TTL старого запису, резолвери віддають кешовану адресу. Перед міграцією сервера TTL заздалегідь зменшують, наприклад до 300 секунд. Типи записів Запис Що зберігає Приклад A ім'я → IPv4 www A 93.184.215.14 AAAA ім'я → IPv6 www AAAA 2606:2800:21f:cb07::1 CNAME псевдонім → інше ім'я (canonical name) blog CNAME myblog.github.io. MX поштовий сервер домену з пріоритетом (менше число — вищий пріоритет) @ MX 10 mail.example.com. NS авторитетні сервери імен домену @ NS ns1.example.com. PTR зворотний запис: IP → ім'я (зони in-addr.arpa , ip6.arpa ) 14.215.184.93.in-addr.arpa PTR www.example.com. SOA головна інформація зони: основний сервер, email адміністратора, серійний номер, таймери один на зону TXT довільний текст: SPF, DKIM, підтвердження власності домену @ TXT \"v=spf1 include:_spf.google.com ~all\" SRV розташування служби: хост і порт _sip._tcp SRV 10 5 5060 sip.example.com. dig example.com # A-запис з деталями (TTL, сервер, час) dig +short example"}, {"title": "Лекція 6 · Комп'ютерні мережі: OSI і TCP/IP, IPv4 і IPv6, DHCP, DNS, NAT, VPN, QoS", "section": "NAT: трансляція адрес", "url": "lectures/week-2/lecture-6.html#nat", "text": "NAT: трансляція адрес NAT (Network Address Translation) змінює IP-адреси (і порти) в заголовках пакетів, поки ті проходять через маршрутизатор . Маршрутизатор веде таблицю трансляцій, щоб повернути відповідь правильному внутрішньому хосту. Наслідки: багато приватних адрес виходять в інтернет через одну публічну (економія IPv4), а внутрішні адреси ззовні не видно (NAT працює як IP-проксі між приватною LAN і публічною мережею). PAT на прикладі зі слайдів. Роутер запам'ятовує, якому внутрішньому хосту належить публічний порт 8801, і повертає йому відповідь. Тип Відповідність Суть Static NAT одна приватна ↔ одна публічна, постійно потрібно, щоб внутрішній сервер завжди мав ту саму публічну адресу (вхідні з'єднання) Dynamic NAT багато приватних ↔ пул публічних, тимчасово хост отримує будь-яку вільну адресу з пулу на час сеансу; пул вичерпався — нові хости чекають PAT (Port Address Translation), NAT overload, NAPT багато приватних ↔ одна публічна, розрізнення за портами прив'язує комбінацію «приватна IP + порт» до «публічна IP + порт». Так працює кожен домашній роутер Port forwarding (переадресація портів, static PAT) публічна IP:порт → приватна IP:порт сервер з приватною адресою обслуговує запити з інтернету: 203.0.113.5:80 → 192.168.1.20:8080 Masquerading як PAT у Linux (iptables/nftables): публічна адреса береться з інтерфейсу автоматично — зручно, коли вона динамічна CGNAT NAT у провайдера клієнти отримують адреси з 100.64.0.0/10 , а провайдер транслює їх у свої публічні Дві розшифровки SNAT і DNAT У Linux і в слайдах курсу: SNAT = Source NAT (змінюється адреса відправника , доступ з LAN в інтернет), DNAT = Destination NAT (змінюється адреса отримувача , доступ ззовні до внутрішнього сервера; port forwarding — різновид DNAT). У тестах CompTIA/ExamCompass ті самі абревіатури означають Static NAT і Dynamic NAT . Тому читайте розшифровку в дужках. Твердження «Dynamic NAT дає постійну відповідність приватної і публічної адреси» — хибне (постійна — у static). «Static NAT зіставляє приватну адресу з будь-якою з пулу » — теж хибне (пул — у dynamic). # Linux як NAT-роутер (nftables/iptables) sudo sysctl -w net.ipv4.ip_forward=1 # дозволити пересилання пакетів sudo iptable"}, {"title": "Лекція 6 · Комп'ютерні мережі: OSI і TCP/IP, IPv4 і IPv6, DHCP, DNS, NAT, VPN, QoS", "section": "VPN", "url": "lectures/week-2/lecture-6.html#vpn", "text": "VPN VPN (Virtual Private Network) — захищена мережа поверх іншої, зазвичай публічної й недовіреної. Трафік тунелюється (вкладається в пакети іншого протоколу) і шифрується ; сторони проходять автентифікацію. Тип Призначення Site-to-site (Intranet VPN) постійно об'єднує мережі кількох офісів або офіс і хмару (AWS Site-to-Site VPN) в одну Remote access окремий співробітник з ноутбука підключається до корпоративної мережі Client/server шифрування між двома вузлами всередині корпоративної мережі Протоколи: IPsec (L3, site-to-site), OpenVPN і SSL/TLS VPN (через TLS, проходить фаєрволи на 443), WireGuard (сучасний, простий і швидкий, UDP), застарілі PPTP і L2TP. Split tunneling — у тунель іде лише корпоративний трафік, а інтернет — напряму; full tunnel — увесь трафік через VPN. Недоліки VPN: накладні витрати на заголовки та шифрування, додаткова затримка."}, {"title": "Лекція 6 · Комп'ютерні мережі: OSI і TCP/IP, IPv4 і IPv6, DHCP, DNS, NAT, VPN, QoS", "section": "QoS, ACL, фаєрволи, VLAN", "url": "lectures/week-2/lecture-6.html#qos", "text": "QoS, ACL, фаєрволи, VLAN QoS: керування якістю обслуговування QoS (Quality of Service) — набір механізмів, що виділяють мережеві ресурси різним типам трафіку: голос і відео отримують пріоритет перед завантаженням файлів, щоб розмова не переривалась. Механізм Рівень Суть CoS (Class of Service, IEEE 802.1p) L2 3-бітне поле пріоритету (PCP, 0–7) в заголовку Ethernet-кадру , у тезі 802.1Q (VLAN). Необов'язкове поле, яке вмикає QoS у кадрах DiffServ / DSCP L3 6-бітне поле в заголовку IP-пакета позначає клас трафіку; кожен маршрутизатор обробляє клас за своєю політикою. Архітектура DiffServ — це QoS і керування трафіком Traffic shaping (packet shaping) — згладжує трафік до заданої швидкості, буферизуючи надлишок Policing — жорстко відкидає трафік понад ліміт ACL і фаєрволи ACL (Access Control List) — упорядкований список правил, що визначає, яким користувачам, процесам або пакетам дозволено доступ до ресурсу. У мережах ACL на маршрутизаторі чи фаєрволі перевіряє кожен пакет за адресами, портами і протоколом. Правила читаються згори вниз до першого збігу, а наприкінці стоїть неявне «заборонити все» (implicit deny). 1 permit tcp any host 10.0.1.10 eq 443 # HTTPS до вебсервера — дозволено 2 permit tcp 10.0.9.0/24 host 10.0.1.10 eq 22 # SSH лише з адмін-мережі 3 deny ip any any # усе інше (неявно є і без цього рядка) Stateless фаєрвол (простий ACL) перевіряє кожен пакет окремо — для відповідей потрібні дзеркальні правила. Stateful фаєрвол відстежує з'єднання: дозволили вихідний запит — відповідь пропускається автоматично. Так працюють Security Groups в AWS, тоді як Network ACL в AWS — stateless. Фаєрволи в Linux: nftables / iptables , надбудови ufw (Ubuntu: sudo ufw allow 22/tcp ) і firewalld (RHEL: firewall-cmd --add-service=http --permanent ). WAF (web application firewall) працює на L7 і блокує атаки на вебзастосунки (SQL-ін'єкції, XSS). VLAN VLAN (Virtual LAN, IEEE 802.1Q) логічно ділить один фізичний комутатор на кілька ізольованих мереж: бухгалтерія, розробники і гості фізично в одному комутаторі, але один одного не бачать без маршрутизатора. У кадр додається 4-байтовий тег з номером VLAN (1–4094) і полем пріоритету CoS. Порт access належить одній VLAN, trunk переда"}, {"title": "Лекція 6 · Комп'ютерні мережі: OSI і TCP/IP, IPv4 і IPv6, DHCP, DNS, NAT, VPN, QoS", "section": "Маршрутизація", "url": "lectures/week-2/lecture-6.html#routing", "text": "Маршрутизація Маршрутизатор пересилає пакет за таблицею маршрутизації , обираючи найдовший збіг префікса (longest prefix match): маршрут 10.1.2.0/24 точніший за 10.0.0.0/8 . Якщо жоден маршрут не підходить, використовується маршрут за замовчуванням 0.0.0.0/0 (default route) — він веде до шлюзу. $ ip route default via 192.168.1.1 dev eth0 proto dhcp # шлюз за замовчуванням 192.168.1.0/24 dev eth0 proto kernel scope link # своя мережа — напряму 172.17.0.0/16 dev docker0 # мережа Docker $ ip route get 8.8.8.8 # яким маршрутом піде пакет $ sudo ip route add 10.10.0.0/16 via 192.168.1.254 # статичний маршрут Статична маршрутизація — маршрути прописує адміністратор. Просто, але не реагує на збої. Динамічна — маршрутизатори обмінюються маршрутами протоколами: OSPF (всередині організації, link-state), BGP (між автономними системами в інтернеті), RIP (застарілий, distance-vector). Поле TTL в IP-заголовку (Hop Limit в IPv6) зменшується на 1 на кожному маршрутизаторі; при 0 пакет відкидається, а відправнику йде ICMP Time Exceeded. На цьому побудовано traceroute ."}, {"title": "Лекція 6 · Комп'ютерні мережі: OSI і TCP/IP, IPv4 і IPv6, DHCP, DNS, NAT, VPN, QoS", "section": "Діагностика мережі", "url": "lectures/week-2/lecture-6.html#tools", "text": "Діагностика мережі Алгоритм «знизу вгору» Коли «сайт не відкривається», перевіряйте рівні OSI по черзі — так ви не шукатимете помилку в коді, коли не підключено кабель. Крок Перевірка Що означає провал 1. Інтерфейс (L1–L2) ip link — стан UP , ip a — є адреса кабель, драйвер, вимкнений інтерфейс. Адреса 169.254.x.x — DHCP не відповів 2. Локальний стек ping 127.0.0.1 проблема з TCP/IP на самому хості (буває рідко). Успіх нічого не каже про кабель, IP, маску чи шлюз 3. Своя мережа (L3) ip r — є default; ping 192.168.1.1 (шлюз) неправильна IP/маска/VLAN, шлюз недоступний 4. Інтернет за IP ping 8.8.8.8 , traceroute 8.8.8.8 маршрутизація, NAT, провайдер. Але ICMP може бути заблоковано 5. DNS dig example.com , getent hosts example.com за IP працює, за іменем ні → DNS-сервер, /etc/resolv.conf , /etc/hosts 6. Порт (L4) nc -zv example.com 443 , ss -tulpn на сервері служба не слухає порт, фаєрвол, Security Group 7. Застосунок (L7) curl -v https://example.com статус-код 4xx/5xx, сертифікат, редиректи, логи застосунку ping і traceroute ping надсилає ICMP Echo Request і чекає Echo Reply , показуючи затримку (RTT) і втрати. traceroute (у Windows — tracert ) відправляє пакети зі зростаючим TTL = 1, 2, 3…; кожен маршрутизатор, на якому TTL обнулився, відповідає ICMP Time Exceeded — так видно всі проміжні вузли і затримку до кожного. Зірочки * * * означають, що вузол не відповідає на такі пакети (часто це не проблема). ping -c 4 8.8.8.8 # 4 запити (у Linux ping без -c працює нескінченно, Ctrl+C) ping -6 ::1 # IPv6 traceroute example.com # маршрут (може знадобитись apt install traceroute) tracepath example.com # те саме без root, показує ще й MTU mtr example.com # ping + traceroute наживо, зручно шукати місце втрат Типовий маршрут з дому: локальний роутер (ваш шлюз) → вузол провайдера (PoP) → регіональний провайдер Tier 2 → IXP (точка обміну трафіком) → магістральний провайдер Tier 1 → мережа отримувача. Інші команди Linux Задача Команда Застарілий аналог / Windows Інтерфейси та адреси ip a , ip -4 a , ip -6 a ifconfig / ipconfig /all Маршрути, шлюз ip r route -n , netstat -r / route print ARP / NDP-сусіди ip neigh arp -n / arp -a Які порти слухаються, якими процесами sudo ss -tul"}, {"title": "Лекція 6 · Комп'ютерні мережі: OSI і TCP/IP, IPv4 і IPv6, DHCP, DNS, NAT, VPN, QoS", "section": "Типові помилки", "url": "lectures/week-2/lecture-6.html#mistakes", "text": "Типові помилки UDP — «зламаний TCP», його не використовують. UDP навмисно простіший і швидший: для DNS, DHCP, голосу й відео затримка гірша за втрату окремого пакета. У мережі /24 можна адресувати 256 хостів. 256 адрес, але хостів 2⁸ − 2 = 254: адреса мережі та broadcast не призначаються пристроям. Успішний ping 127.0.0.1 = мережа працює. Loopback перевіряє лише локальний стек TCP/IP, а не кабель, IP, маску чи шлюз. Хост «не пінгується», отже він вимкнений. ICMP часто блокують фаєрволи. Перевірте сервіс напряму: curl , nc -zv host 443 . 2001:DB8::1::5 — коректне скорочення. :: можна використати лише один раз, інакше неможливо визначити, скільки нулів у кожному пропуску. При скороченні IPv6 можна прибрати й кінцеві нулі: 4C00 → 4C . Прибирати можна лише ведучі нулі. 4C = 004C — інше значення. IPv4 записують вісімковими або шістнадцятковими числами. IPv4 — десятковий запис з крапками. Шістнадцятковими пишуть IPv6 і MAC. 172.32.0.0 — приватна адреса, бо «172 — це приватний діапазон». Приватний лише 172.16.0.0 – 172.31.255.255 (/12). Усе інше з 172 — публічне. Адреса 169.254.x.x на сервері — нормальна приватна адреса. Це APIPA: хост не отримав відповідь DHCP. Шукайте проблему з DHCP-сервером, кабелем, VLAN або relay. DHCP lease — це постійна адреса пристрою. Lease — оренда на строк. Постійну адресу дає reservation (прив'язка до MAC) або статичне налаштування. В IPv6 є broadcast, як і в IPv4. В IPv6 broadcast немає: його замінює multicast ( ff02::1 — усі вузли сегмента), а ARP замінює NDP. Маска визначає клас адреси, а шлюз — мережу. До якої мережі належить адреса, визначає маска . Шлюз — лише маршрутизатор для трафіку в інші мережі."}, {"title": "Лекція 7 · Хмарні обчислення: модель NIST, IaaS/PaaS/SaaS і провайдери AWS, GCP, Azure", "section": "Вступ", "url": "lectures/week-2/lecture-7.html", "text": ""}, {"title": "Лекція 7 · Хмарні обчислення: модель NIST, IaaS/PaaS/SaaS і провайдери AWS, GCP, Azure", "section": "Чого ви навчитесь", "url": "lectures/week-2/lecture-7.html#goals", "text": "Чого ви навчитесь Пояснити, яку бізнес-проблему розв'язують хмари (CapEx → OpEx, еластичність). Назвати 5 базових характеристик , моделі сервісів і 4 моделі розгортання за NIST. Зважити переваги і недоліки хмар (vendor lock-in, «усе ламається»). Розрізняти регіони і зони доступності , зональні та регіональні ресурси. Зіставити ключові сервіси AWS, Azure і GCP. Пояснити IAM (користувачі, групи, ролі, політики) і принцип найменших привілеїв. Спроєктувати VPC з публічною і приватною підмережами, IGW, NAT gateway, Security Groups і NACL. Розуміти EC2 (AMI, типи, key pair, user data, EBS), S3, RDS, ELB, Auto Scaling, CloudWatch, Lambda і AWS CLI. Рахувати доступність («дев'ятки»), знати RPO/RTO, стратегії DR, стовпи Well-Architected і стратегії міграції 6R."}, {"title": "Лекція 7 · Хмарні обчислення: модель NIST, IaaS/PaaS/SaaS і провайдери AWS, GCP, Azure", "section": "Звідки взялися хмари", "url": "lectures/week-2/lecture-7.html#history", "text": "Звідки взялися хмари Період Як розміщували сервіси Проблема 1990-ті Своє залізо і ПЗ, канал від провайдера, власне приміщення, свій штат IT/Ops Платиш за все, навіть коли не використовуєш 2000-ні Оренда стійок у спільному дата-центрі (colocation) Сервери, ПЗ і чергові адміни «з пейджером 24/7» — досі свої Хмари Оренда ресурсів через інтернет із погодинною/посекундною оплатою Нові ризики: залежність від провайдера Ідея Google — будувати надійність на дешевому стандартному залізі (commodity hardware) і програмно обходити відмови. Amazon на початку 2000-х мав надлишок потужностей під пікові розпродажі й вирішив здавати їх в оренду — так з'явився AWS. Вправа на масштабування Припустимо, 1 сервер обслуговує 20 тис. користувачів. Скільки серверів купувати, якщо аудиторія росте так: Чому прогнозувати важко. Купили під прогноз — у січні–березні сервери простоюють, у травні «успіх-катастрофа»: попит утричі більший, а нове залізо їде тижнями. Чому власне залізо масштабувати складно: великі капітальні витрати наперед ; на масштабі залізо часто ламається ; потрібні спеціалісти; замовлення нового обладнання займає тижні ; глобальне розгортання вимагає глобальної команди. Хмара дозволяє додати 7 серверів за хвилини і прибрати їх, коли пік мине."}, {"title": "Лекція 7 · Хмарні обчислення: модель NIST, IaaS/PaaS/SaaS і провайдери AWS, GCP, Azure", "section": "Модель хмари за NIST", "url": "lectures/week-2/lecture-7.html#nist", "text": "Модель хмари за NIST Визначення NIST Хмарні обчислення — модель повсюдного, зручного мережевого доступу на вимогу до спільного пулу конфігурованих обчислювальних ресурсів (мережі, ВМ, сховища, застосунки, сервіси), які можна швидко виділити і звільнити з мінімальними зусиллями з управління чи взаємодії з провайдером. Структура моделі NIST: 5 характеристик + 3 (і більше) моделі сервісів + 4 моделі розгортання. Характеристика Що означає на практиці On-demand self-service Створюєте ВМ самі в консолі/API, без дзвінка провайдеру Broad network access Доступ через мережу зі стандартних пристроїв Resource pooling Ресурси провайдера спільні для багатьох клієнтів (multi-tenancy) Rapid elasticity Швидко масштабуєте вгору і вниз під навантаження Measured service Використання вимірюється — платите за фактом (pay-as-you-go) Моделі розгортання: public — ресурси провайдера для всіх (AWS, GCP, Azure); private — хмара для однієї організації; hybrid — поєднання власної інфраструктури і публічної хмари; community — спільна хмара для групи організацій зі спільними вимогами. Розподіл відповідальності (повторення лекції 1): в IaaS провайдер керує мережею, сховищем, серверами і віртуалізацією; у PaaS — ще й ОС, middleware і runtime; у SaaS — усім, клієнт лише користується."}, {"title": "Лекція 7 · Хмарні обчислення: модель NIST, IaaS/PaaS/SaaS і провайдери AWS, GCP, Azure", "section": "Переваги і недоліки", "url": "lectures/week-2/lecture-7.html#pros-cons", "text": "Переваги і недоліки Переваги «Assetless»: не треба купувати залізо і приміщення. Плата за використання , масштабування вгору/вниз із посекундною тарифікацією. Менший штат IT/Ops : автоматизація замість лінійного росту персоналу. Вибір рівня: від DevOps (керує клієнт) до NoOps (керує провайдер). Готові сервіси: ML API (зір, мова, мовлення), GIS, сховища даних. Недоліки Vendor lock-in: важко переїхати GCP ↔ AWS ↔ Azure. Закритий код сервісів — важче дебажити . Commodity hardware: треба проєктувати систему з розрахунку на часті відмови. «Everything fails all the time» — Вернер Фогельс, CTO Amazon. Ризик неочікуваних рахунків (з чату: при реєстрації часто треба прив'язати картку). Моделі управління , які пропонує провайдер: клієнт робить усе (хмара як віртуальний дата-центр), клієнт робить частину (DevOps, гібрид), клієнт не робить нічого (NoOps, повністю керовані сервіси). Розробники, за слайдом, віддають перевагу останньому."}, {"title": "Лекція 7 · Хмарні обчислення: модель NIST, IaaS/PaaS/SaaS і провайдери AWS, GCP, Azure", "section": "Регіони і зони", "url": "lectures/week-2/lecture-7.html#geo", "text": "Регіони і зони Ієрархія інфраструктури. Регіон → кілька ізольованих зон → кілька дата-центрів у зоні. AWS: Availability Zone (AZ) — ізольоване розташування з кількох з'єднаних дата-центрів; регіон — географічна група з 2+ AZ (напр. us-east-1 ). GCP: регіон — незалежна географічна область із зон; зона — окремий «домен відмови» в регіоні. Зональні ресурси недоступні, якщо впала зона; регіональні — розгорнуті з резервуванням у кількох зонах регіону; мультирегіональні/глобальні — розподілені між регіонами (з компромісом щодо затримки чи узгодженості даних). Висновок для проєктування: критичний сервіс розміщують щонайменше у двох зонах . Кількість регіонів і зон швидко змінюється — актуальні цифри дивіться на сайтах провайдерів."}, {"title": "Лекція 7 · Хмарні обчислення: модель NIST, IaaS/PaaS/SaaS і провайдери AWS, GCP, Azure", "section": "AWS, GCP, Azure: що є що", "url": "lectures/week-2/lecture-7.html#providers", "text": "AWS, GCP, Azure: що є що У кожного провайдера понад 100 продуктів. GCP зі слайдів: першим запровадив посекундну оплату, робить ставку на open source (Kubernetes, TensorFlow, Go) проти vendor lock-in, власна глобальна оптоволоконна мережа. Абстракції в усіх провайдерів однакові — різняться назви. Категорія AWS Azure GCP Віртуальні машини (IaaS) EC2 Virtual Machines Compute Engine PaaS для застосунків Elastic Beanstalk App Service / Cloud Services App Engine Serverless-функції (FaaS) Lambda Functions Cloud Functions Kubernetes EKS AKS GKE Об'єктне сховище S3 Blob Storage Cloud Storage Блокові диски EBS Disk Storage Persistent Disk Реляційна БД RDS, Aurora SQL Database Cloud SQL, Spanner NoSQL DynamoDB Cosmos DB Bigtable, Datastore Мережа VPC Virtual Network (VNet) VPC DNS / балансування Route 53 / ELB Traffic Manager / Load Balancer Cloud DNS / Cloud Load Balancing Архівне сховище Glacier Archive Storage Nearline / Coldline Сильні сторони за PDF-порівнянням: AWS — лідер ринку, найширший і найзріліший набір сервісів, глобальне покриття; Azure — інтеграція з продуктами Microsoft, гібридна хмара, підтримка великих організацій; GCP — орієнтація на cloud-native, open source і портативність, гнучкі контракти та знижки за тривале використання. Усі мають free tier для старту."}, {"title": "Лекція 7 · Хмарні обчислення: модель NIST, IaaS/PaaS/SaaS і провайдери AWS, GCP, Azure", "section": "Базові сервіси хмари на прикладі AWS", "url": "lectures/week-2/lecture-7.html#aws-core", "text": "Базові сервіси хмари на прикладі AWS Назви різняться між провайдерами, але набір «цеглинок» однаковий. Нижче — те, з чим DevOps-інженер працює щодня; аналоги Azure і GCP — у таблиці вище. IAM: хто що може робити Root account Власник акаунта Має необмежені права. Вмикають MFA, ключі доступу не створюють, для щоденної роботи не використовують. User / Group Користувач і група Людина або програма з постійними обліковими даними; права зручно видавати групам. Role Роль Набір прав, які тимчасово отримує сервіс (EC2, Lambda, CI-система) без зберігання ключів. Правильний спосіб дати ВМ доступ до S3. Policy Політика JSON-документ: які дії (Action) над якими ресурсами (Resource) дозволено (Effect). { \"Version\": \"2012-10-17\", \"Statement\": [{ \"Effect\": \"Allow\", \"Action\": [\"s3:GetObject\", \"s3:PutObject\"], \"Resource\": \"arn:aws:s3:::my-app-backups/*\" }] } Принцип найменших привілеїв : давати лише потрібні дії на потрібні ресурси. Явна заборона ( Deny ) завжди переважає дозвіл. VPC: власна мережа в хмарі Типова VPC. Ззовні доступний лише балансувальник; сервери і БД у приватній підмережі виходять в інтернет (за оновленнями) через NAT gateway. Компонент Призначення VPC ізольована віртуальна мережа в регіоні з вашим діапазоном (напр. 10.0.0.0/16 ) Subnet частина діапазону VPC в одній зоні доступності. Публічна — з маршрутом в Internet Gateway, приватна — без нього Internet Gateway (IGW) вихід VPC в інтернет і вхід з нього NAT Gateway дає приватним підмережам вихід в інтернет без можливості вхідних з'єднань (SNAT/PAT з лекції 6) Route table маршрути підмережі ( 0.0.0.0/0 → igw-… ) Security Group stateful фаєрвол на рівні інтерфейсу ВМ, лише правила «дозволити» Network ACL stateless фаєрвол на рівні підмережі, правила allow і deny з номерами Elastic IP статична публічна IPv4-адреса (платна, якщо не використовується) EC2: віртуальні машини AMI (Amazon Machine Image) — образ, з якого створюється ВМ: ОС і встановлене ПЗ. Тип інстансу задає ресурси: t3.micro (2 vCPU, 1 ГБ, «burstable», у free tier), сімейства m — загального призначення, c — обчислювальні, r — з великою пам'яттю. Key pair — SSH-ключі для входу (публічна частина на ВМ, приватну завантажуєте ви один раз). User data — скрип"}, {"title": "Лекція 7 · Хмарні обчислення: модель NIST, IaaS/PaaS/SaaS і провайдери AWS, GCP, Azure", "section": "Масштабування, спільна відповідальність і моделі оплати", "url": "lectures/week-2/lecture-7.html#ops", "text": "Масштабування, спільна відповідальність і моделі оплати Вертикальне (scale up) Більший сервер: більше CPU і RAM. Просто, але є стеля і часто потрібен перезапуск. Горизонтальне (scale out) Більше однакових серверів за балансувальником. Майже без стелі; застосунок має бути stateless. Масштабованість (scalability) — здатність системи рости. Еластичність (elasticity) — автоматично збільшувати й зменшувати ресурси під навантаження (AWS Auto Scaling, GCP Managed Instance Groups, Azure VM Scale Sets). Висока доступність досягається розміщенням копій у кількох зонах доступності. SLA 99,9% — це до ≈8,8 год простою на рік, 99,99% — до ≈53 хв. Модель спільної відповідальності (shared responsibility) Провайдер відповідає за безпеку «самої хмари» : дата-центри, залізо, мережу, гіпервізор. Клієнт — за безпеку «у хмарі» : свої дані, користувачів і права (IAM), шифрування, а в IaaS ще й за ОС, оновлення та правила firewall (security groups). Що вища модель (IaaS → PaaS → SaaS), то більше бере на себе провайдер, але дані й доступи завжди на клієнті . Як платять за обчислення Модель Суть Коли On-demand погодинна/посекундна оплата без зобов'язань нерівне чи непередбачуване навантаження Reserved / Savings Plans зобов'язання на 1–3 роки, знижка до ~72% стабільне базове навантаження Spot (GCP — Spot VMs) надлишкові потужності зі знижкою до 90%, але провайдер може забрати ВМ (в AWS — з попередженням за 2 хв) задачі, які можна перервати: пакетна обробка, CI-збірки Типи сховищ: об'єктне (AWS S3, GCS, Azure Blob — файли за URL), блокове (EBS, Persistent Disk — «диск» для ВМ), файлове (EFS, Azure Files — спільна мережева папка)."}, {"title": "Лекція 7 · Хмарні обчислення: модель NIST, IaaS/PaaS/SaaS і провайдери AWS, GCP, Azure", "section": "Надійність, аварійне відновлення і міграція в хмару", "url": "lectures/week-2/lecture-7.html#design", "text": "Надійність, аварійне відновлення і міграція в хмару «Дев'ятки» доступності Доступність Допустимий простій на рік на місяць 99% («дві дев'ятки») 3,65 доби ≈7,3 год 99,9% ≈8,8 год ≈44 хв 99,95% ≈4,4 год ≈22 хв 99,99% ≈53 хв ≈4,4 хв 99,999% ≈5,3 хв ≈26 с Доступність ланцюжка залежних компонентів перемножується: вебсервер 99,9% × БД 99,9% ≈ 99,8% для системи. Дублювання навпаки підвищує доступність: два незалежні сервери по 99% дають 1 − 0,01² = 99,99%. RPO і RTO RPO — Recovery Point Objective Скільки даних можна втратити, виміряне в часі. Бекап раз на добу → RPO до 24 год. Синхронна реплікація → RPO ≈ 0. RTO — Recovery Time Objective За який час система має знову запрацювати після аварії. Відновлення з архіву вручну — години; автоматичне перемикання на репліку — хвилини. Стратегії аварійного відновлення (disaster recovery) Стратегія Суть RTO / RPO Вартість Backup & restore лише бекапи в іншому регіоні; при аварії все розгортається заново (IaC дуже допомагає) години / години найнижча Pilot light у резервному регіоні працює мінімум (репліка БД), решта вмикається при аварії десятки хвилин низька Warm standby зменшена, але повністю робоча копія системи, масштабується при аварії хвилини середня Multi-site active-active повні копії в кількох регіонах обслуговують трафік одночасно ≈0 / ≈0 найвища Multi-AZ (кілька зон доступності в одному регіоні) захищає від збою дата-центру; multi-region — від збою цілого регіону або катастрофи. AWS Well-Architected Framework: шість стовпів Operational excellence — автоматизація операцій, IaC, малі зворотні зміни, навчання на інцидентах. Security — IAM з найменшими привілеями, шифрування, журналювання, захист на всіх рівнях. Reliability — автоматичне відновлення, горизонтальне масштабування, тестування відмов. Performance efficiency — правильні типи ресурсів, serverless, глобальне розміщення. Cost optimization — платити лише за потрібне, правильний розмір, Spot і Reserved. Sustainability — мінімізація енергоспоживання і зайвих ресурсів. Як переносять системи в хмару: «6R» Стратегія Що робимо Rehost («lift and shift») переносимо ВМ як є, без змін коду — швидко, але без переваг хмари Replatform («lift, tinker and shift») дрібні зміни: влас"}, {"title": "Лекція 7 · Хмарні обчислення: модель NIST, IaaS/PaaS/SaaS і провайдери AWS, GCP, Azure", "section": "Типові помилки", "url": "lectures/week-2/lecture-7.html#mistakes", "text": "Типові помилки Щоб ВМ мала доступ до S3, треба покласти на неї ключі доступу. Правильно — призначити ВМ IAM-роль : тимчасові облікові дані видаються автоматично і не зберігаються на диску. Security Group і Network ACL — одне й те саме. Security Group — stateful, на рівні інтерфейсу ВМ, лише allow. NACL — stateless, на рівні підмережі, allow і deny. Приватна підмережа не може виходити в інтернет. Може — через NAT gateway (вихідні з'єднання). Не можна лише ініціювати з'єднання ззовні. Зупинена (stopped) ВМ нічого не коштує. Оплата за ВМ припиняється, але диски EBS, Elastic IP і знімки оплачуються далі. У хмарі за безпеку повністю відповідає провайдер. Провайдер захищає інфраструктуру, а дані, доступи і (в IaaS) ОС — відповідальність клієнта. Хмара — це просто «чужий сервер». Хмару визначають 5 характеристик NIST: самообслуговування, мережевий доступ, пул ресурсів, еластичність і вимірюваність. Орендований VPS без них — звичайний хостинг. У хмарі нічого не ламається — за це відповідає провайдер. Залізо в хмарі звичайне і відмовляє регулярно. Надійність — відповідальність архітектури: кілька зон, резервні копії, моніторинг. Регіон і зона — одне й те саме. Регіон — географічна область, що містить кілька ізольованих зон. Резервування між зонами захищає від аварії одного дата-центру. Хмара завжди дешевша. Хмара вигідна при змінному навантаженні. За постійного високого навантаження і без контролю витрат рахунок може перевищити власне залізо."}, {"title": "Лекція 8 · Infrastructure as Code і Terraform: HCL, state, init → plan → apply", "section": "Вступ", "url": "lectures/week-2/lecture-8.html", "text": ""}, {"title": "Лекція 8 · Infrastructure as Code і Terraform: HCL, state, init → plan → apply", "section": "Чого ви навчитесь", "url": "lectures/week-2/lecture-8.html#goals", "text": "Чого ви навчитесь Дати визначення IaC і пояснити, чим він кращий за ручне налаштування. Розрізняти configuration management , server templating і provisioning та назвати інструменти кожного типу. Пояснити ключові поняття Terraform: provider, resource, variable, output, state . Прочитати і написати простий HCL-блок. Знати, що робить кожна команда циклу init → plan → apply → destroy . Порівняти Ansible (agentless, push) з Puppet/Chef (агенти, pull) і пояснити remote state та модулі Terraform. Організувати проєкт Terraform (versions, providers, main, variables, outputs, lock-файл) і розгорнути вебсервер в AWS. Використовувати посилання, неявні та явні залежності, count і for_each , data sources, функції, модулі і lifecycle . Читати план ( + , ~ , -/+ , - ), налаштувати remote state з блокуванням, імпортувати ресурси, вбудувати Terraform у CI. Писати Ansible inventory і playbook з шаблоном і handler, пояснити ідемпотентність, ролі, Vault."}, {"title": "Лекція 8 · Infrastructure as Code і Terraform: HCL, state, init → plan → apply", "section": "Що таке Infrastructure as Code", "url": "lectures/week-2/lecture-8.html#iac", "text": "Що таке Infrastructure as Code Визначення Infrastructure as Code (IaC) — процес управління IT-інфраструктурою, що застосовує найкращі практики DevOps-розробки до хмарних ресурсів. Ресурси організації кодифікуються в текстові файли , які зберігаються в системі контролю версій (Git) — це відкриває feature-гілки, pull request-и і, як наслідок, CI/CD для інфраструктури. Нагадування з «хмарної піраміди»: що нижче (IaaS), то більше контролю і роботи з інфраструктурою — саме тут працює DevOps і саме тут IaC дає найбільший ефект. Вручну («ClickOps») Кроки в консолі ніде не записані Друге середовище відрізняється від першого Відновлення після аварії — з пам'яті Немає рев'ю змін Як код Файли = документація інфраструктури dev/stage/prod з одного коду — однакові Відтворення за хвилини Зміни проходять pull request і історію Git Передісторія: спершу інфраструктуру автоматизували скриптами (Bash, Python, Ruby, PowerShell). Потім з'явилися спеціалізовані інструменти: Vagrant, Docker, Terraform, Ansible, Packer. Повна «карта» — CNCF Landscape: Ansible, Chef, Puppet, SaltStack, Pulumi, Terraform та десятки інших."}, {"title": "Лекція 8 · Infrastructure as Code і Terraform: HCL, state, init → plan → apply", "section": "Три типи IaC-інструментів", "url": "lectures/week-2/lecture-8.html#types", "text": "Три типи IaC-інструментів Типи IaC. На практиці їх комбінують: Terraform створює ВМ, Ansible налаштовує її, або ВМ запускається з готового образу Packer/Docker. Idempotent Ідемпотентність Повторний запуск дає той самий результат: якщо nginx уже встановлено, вдруге нічого не зміниться. Immutable infrastructure Незмінна інфраструктура Сервер не «латають» на місці, а замінюють новим із нового образу. Менше дрейфу конфігурації. Declarative Декларативний підхід Описуєте бажаний стан («2 ВМ типу e2-small»), а інструмент сам вирішує, що створити, змінити чи видалити. Так працює Terraform."}, {"title": "Лекція 8 · Infrastructure as Code і Terraform: HCL, state, init → plan → apply", "section": "Чому Terraform", "url": "lectures/week-2/lecture-8.html#terraform", "text": "Чому Terraform Безкоштовний і з відкритим кодом (HashiCorp), написаний на Go. Простий в установці — один бінарний файл; перевірка: terraform -version . Мультиплатформний: сотні провайдерів — AWS, GCP, Azure, VirtualBox, Docker, Kubernetes… «Керуй будь-чим, що має API». Цілі: уніфікований погляд на ресурси, підтримка IaaS/PaaS/SaaS, безпечні й передбачувані зміни, робочий процес, що не залежить від технології."}, {"title": "Лекція 8 · Infrastructure as Code і Terraform: HCL, state, init → plan → apply", "section": "Структура проєкту і повний приклад для AWS", "url": "lectures/week-2/lecture-8.html#project", "text": "Структура проєкту і повний приклад для AWS Файли типового проєкту infra/ ├── versions.tf # блок terraform: версія Terraform, required_providers, backend ├── providers.tf # налаштування провайдерів (регіон, профіль) ├── main.tf # ресурси ├── variables.tf # оголошення вхідних змінних ├── outputs.tf # вихідні значення ├── terraform.tfvars # значення змінних (не комітити, якщо є секрети) ├── .terraform.lock.hcl # зафіксовані версії провайдерів — КОМІТИТИ ├── .terraform/ # завантажені провайдери і модулі — НЕ комітити └── terraform.tfstate # локальний state — НЕ комітити (краще remote backend) Terraform читає усі файли *.tf у каталозі як одну конфігурацію; поділ на файли — лише для зручності. .gitignore для проєкту: .terraform/ , *.tfstate , *.tfstate.* , *.tfvars з секретами. Обмеження версій terraform { required_version = \">= 1.6\" required_providers { aws = { source = \"hashicorp/aws\" version = \"~> 5.0\" # будь-яка 5.x, але не 6.0 (оператор «песимістичного» обмеження) } } } Повний приклад: вебсервер в AWS # variables.tf variable \"region\" { type = string default = \"eu-central-1\" } variable \"instance_type\" { type = string default = \"t3.micro\" } variable \"my_ip\" { type = string description = \"Ваша IP для SSH, напр. 203.0.113.7/32\" } # providers.tf provider \"aws\" { region = var.region } # main.tf data \"aws_ami\" \"ubuntu\" { # data source: ЗНАЙТИ існуючий об'єкт, а не створити most_recent = true owners = [\"099720109477\"] # Canonical filter { name = \"name\" values = [\"ubuntu/images/hvm-ssd-gp3/ubuntu-noble-24.04-amd64-server-*\"] } } resource \"aws_security_group\" \"web\" { name = \"web-sg\" ingress { from_port = 80 to_port = 80 protocol = \"tcp\" cidr_blocks = [\"0.0.0.0/0\"] # HTTP для всіх } ingress { from_port = 22 to_port = 22 protocol = \"tcp\" cidr_blocks = [var.my_ip] # SSH лише з вашої адреси } egress { from_port = 0 to_port = 0 protocol = \"-1\" # будь-який протокол назовні cidr_blocks = [\"0.0.0.0/0\"] } } resource \"aws_instance\" \"web\" { ami = data.aws_ami.ubuntu.id # посилання на data source instance_type = var.instance_type vpc_security_group_ids = [aws_security_group.web.id] # неявна залежність від SG user_data = <<-EOF #!/bin/bash apt-get update && apt-get install -y nginx ech"}, {"title": "Лекція 8 · Infrastructure as Code і Terraform: HCL, state, init → plan → apply", "section": "Ключові поняття Terraform", "url": "lectures/week-2/lecture-8.html#concepts", "text": "Ключові поняття Terraform Provider Провайдер Плагін, що взаємодіє з API сервісу (hashicorp/aws, hashicorp/google, terra-farm/virtualbox). Завантажується з Terraform Registry. Resource Ресурс Блок, що описує один чи кілька об'єктів інфраструктури: ВМ, мережу, DNS-запис, навіть локальний файл. Variable Змінна Пара ключ-значення для налаштування конфігурації без зміни коду. Output Вихідне значення Значення, яке модуль повертає (виводить у CLI або передає іншим конфігураціям), напр. IP створеної ВМ. State Стан Закешована інформація про керовану інфраструктуру: зв'язок «ресурс у коді ↔ реальний об'єкт». Змінні Вид Як задається Input Блок variable ; значення передаються до виконання (CLI -var , файл .tfvars , default) Local Блок locals — внутрішні обчислені значення, можуть посилатися на інші змінні Output Блок output — вивести результат у CLI Environment Змінні оточення з префіксом TF_VAR_ : export TF_VAR_db_username=admin Типи значень: string , number (цілі й дробові), bool , list / tuple ( [\"us-west-1a\", \"us-west-1c\"] , індекс з 0), map / object ( {name = \"Mabel\", age = 52} ), null ."}, {"title": "Лекція 8 · Infrastructure as Code і Terraform: HCL, state, init → plan → apply", "section": "HCL: мова конфігурації", "url": "lectures/week-2/lecture-8.html#hcl", "text": "HCL: мова конфігурації HCL (HashiCorp Configuration Language) візуально схожа на JSON, але має власні структури. Основна мета — оголошувати ресурси ; решта можливостей лише робить це гнучкішим. Три складові: блоки (контейнери з типом і мітками), аргументи (ім'я = значення) і вирази (значення або посилання на інші значення). # загальний синтаксис <BLOCK TYPE> \"<BLOCK LABEL>\" \"<BLOCK LABEL>\" { <IDENTIFIER> = <EXPRESSION> # argument } Приклад: ВМ у Google Cloud (зі слайдів) terraform { required_providers { google = { source = \"hashicorp/google\" , version = \"3.5.0\" } } } provider \"google\" { credentials = file( \"my_gcp.json\" ) # ключ сервісного акаунта — НЕ комітити в Git! project = \"project_vasis\" region = \"europe-north1\" zone = \"europe-north1-a\" } resource \"google_compute_instance\" \"vm_instance\" { name = \"moodle\" machine_type = \"e2-small\" boot_disk { initialize_params { image = \"ubuntu-2004-focal-v20210720\" } } } Змінні та виходи (практика з VirtualBox) variable \"type_network\" { default = \"bridged\" } resource \"virtualbox_vm\" \"node\" { count = 2 # дві однакові ВМ name = format( \"node-%02d\" , count.index + 1) # node-01, node-02 image = \"…/ubuntu/boxes/xenial64/…/virtualbox.box\" cpus = 2 memory = \"2048 mib\" network_adapter { type = var.type_network } } output \"IPAddr\" { value = element(virtualbox_vm.node.*.network_adapter.0.ipv4_address, 1) } На лекції провайдер terra-farm/virtualbox (alpha-версія) збирали з вихідного коду ( go build ) і запускали terraform apply -parallelism=1 , щоб ВМ створювались по черзі. Це дозволяє вчитися IaC локально, без хмарних рахунків."}, {"title": "Лекція 8 · Infrastructure as Code і Terraform: HCL, state, init → plan → apply", "section": "Посилання, залежності, count і for_each, data sources, функції, lifecycle", "url": "lectures/week-2/lecture-8.html#expressions", "text": "Посилання, залежності, count і for_each, data sources, функції, lifecycle Як посилатися на значення Вираз Що означає var.region вхідна змінна local.common_tags локальне значення з блоку locals aws_instance.web.public_ip атрибут ресурсу: <тип>.<ім'я>.<атрибут> data.aws_ami.ubuntu.id атрибут data source module.network.vpc_id вихідне значення модуля \"web-${var.env}\" інтерполяція в рядку var.env == \"prod\" ? 3 : 1 умовний вираз Залежності Terraform будує граф залежностей і створює незалежні ресурси паралельно (за замовчуванням до 10 одночасно, -parallelism=N ). Залежність буває неявною — один ресурс посилається на атрибут іншого — і явною через depends_on , коли зв'язок не видно з коду (наприклад, застосунок має стартувати лише після створення політики IAM). Граф можна побачити: terraform graph | dot -Tpng > graph.png . count і for_each: кілька однакових ресурсів resource \"aws_instance\" \"web\" { count = 3 # web[0], web[1], web[2] ami = data.aws_ami.ubuntu.id instance_type = \"t3.micro\" tags = { Name = \"web-${count.index + 1}\" } } output \"ips\" { value = aws_instance.web[*].public_ip } # splat: список усіх IP resource \"aws_s3_bucket\" \"env\" { for_each = toset([\"dev\", \"staging\", \"prod\"]) # env[\"dev\"], env[\"staging\"], env[\"prod\"] bucket = \"myapp-${each.key}-artifacts\" } Різниця важлива: з count ресурси адресуються за індексом , тож видалення елемента з середини списку зсуває індекси, і Terraform захоче перестворити «зсунуті» ресурси. for_each адресує за ключем , і видалення одного елемента зачіпає лише його. Data sources Блок data читає інформацію про об'єкти, якими Terraform не керує або які створено деінде: найновіший образ AMI, існуючу VPC, зони доступності регіону, поточний акаунт. Ресурс ( resource ) — створює і керує; data source — лише читає. Корисні функції file(\"${path.module}/scripts/init.sh\") # вміст файла templatefile(\"nginx.conf.tftpl\", { port = 8080 }) # шаблон з підстановкою cidrsubnet(\"10.0.0.0/16\", 8, 1) # \"10.0.1.0/24\" — нарізати підмережі lookup(var.sizes, var.env, \"t3.micro\") # значення з map за ключем або default length(var.zones) # кількість елементів join(\",\", [\"a\", \"b\"]) # \"a,b\" merge(local.tags, { Name = \"web\" }) # об'єднати map-и Перевірити вираз б"}, {"title": "Лекція 8 · Infrastructure as Code і Terraform: HCL, state, init → plan → apply", "section": "Життєвий цикл: init → plan → apply → destroy", "url": "lectures/week-2/lecture-8.html#lifecycle", "text": "Життєвий цикл: init → plan → apply → destroy Команда Що робить terraform init Ініціалізує робочий каталог: завантажує провайдерів. Першою після написання нової конфігурації або клонування з Git terraform plan Будує план: читає поточний стан реальних об'єктів, порівнює конфігурацію з попереднім state, пропонує дії, щоб реальність відповідала коду terraform apply Виконує план (з підтвердженням yes ) і оновлює state terraform destroy Видаляє всі ресурси, якими керує конфігурація State Terraform зберігає стан, щоб зіставляти ресурси з коду з реальними об'єктами , відстежувати метадані і пришвидшувати роботу з великою інфраструктурою. За замовчуванням — локальний файл terraform.tfstate ; у команді його зберігають віддалено (наприклад, у S3 чи GCS), щоб усі працювали з одним станом. Безпека State і файли облікових даних (як my_gcp.json ) можуть містити секрети. Додавайте їх у .gitignore ; паролі передавайте через TF_VAR_… або менеджер секретів."}, {"title": "Лекція 8 · Infrastructure as Code і Terraform: HCL, state, init → plan → apply", "section": "State, план і робота в команді", "url": "lectures/week-2/lecture-8.html#state-deep", "text": "State, план і робота в команді Як читати terraform plan Terraform will perform the following actions: # aws_security_group.web will be created + resource \"aws_security_group\" \"web\" { ... } # + створити # aws_instance.web will be updated in-place ~ resource \"aws_instance\" \"web\" { ~ instance_type = \"t3.micro\" -> \"t3.small\" # ~ змінити на місці } # aws_instance.old must be replaced -/+ resource \"aws_instance\" \"old\" { # -/+ знищити і створити заново ~ ami = \"ami-0aaa\" -> \"ami-0bbb\" # forces replacement } # aws_s3_bucket.tmp will be destroyed - resource \"aws_s3_bucket\" \"tmp\" { ... } # - знищити Plan: 2 to add, 1 to change, 2 to destroy. Рядки -/+ і must be replaced читайте особливо уважно: деякі атрибути (образ ВМ, ім'я БД) не можна змінити на льоту, і ресурс буде видалено разом з даними. Для CI план зберігають у файл і застосовують саме його: terraform plan -out=tfplan → terraform apply tfplan . Що таке state і навіщо він Файл terraform.tfstate (JSON) зв'язує ресурси з коду з реальними об'єктами ( aws_instance.web ↔ i-0abc123 ) і зберігає їхні атрибути. Без state Terraform не знає, що вже створено, і спробує створити все заново. Дрейф (drift) — розбіжність між state/кодом і реальністю, коли хтось змінив ресурс вручну в консолі. terraform plan його покаже, terraform apply поверне ресурс до опису в коді. State містить усі атрибути у відкритому вигляді, зокрема паролі БД. Тому — шифроване віддалене сховище з обмеженим доступом, а не Git. Remote backend з блокуванням terraform { backend \"s3\" { bucket = \"mycompany-tfstate\" key = \"study/web/terraform.tfstate\" region = \"eu-central-1\" encrypt = true dynamodb_table = \"terraform-locks\" # блокування: другий apply чекатиме, поки перший завершиться } } Після зміни backend — terraform init -migrate-state . У нових версіях Terraform блокування можна робити і самим S3 ( use_lockfile = true ). Команди для роботи зі state Команда Призначення terraform state list які ресурси відстежуються terraform state show aws_instance.web атрибути ресурсу зі state terraform import aws_instance.web i-0abc123 (або блок import ) взяти під керування об'єкт, створений вручну terraform apply -replace=aws_instance.web примусово перестворити ресурс (раніш"}, {"title": "Лекція 8 · Infrastructure as Code і Terraform: HCL, state, init → plan → apply", "section": "Імперативний vs декларативний, Ansible і ще трохи Terraform", "url": "lectures/week-2/lecture-8.html#ansible", "text": "Імперативний vs декларативний, Ansible і ще трохи Terraform Імперативний підхід Описуєте кроки : «встанови nginx, скопіюй конфіг, перезапусти». Приклад — Bash-скрипт. Декларативний підхід Описуєте бажаний стан : «має бути 2 ВМ і відкритий порт 80». Інструмент сам рахує різницю. Приклад — Terraform, маніфести Kubernetes. Ansible, Puppet, Chef Ansible Puppet / Chef Агент на серверах не потрібен (agentless) — підключається по SSH потрібен агент на кожному вузлі Модель push : керуючий вузол надсилає зміни pull : агент періодично тягне конфігурацію з master-сервера Мова YAML- playbooks Puppet DSL / Ruby # playbook.yml — запуск: ansible-playbook -i inventory.ini playbook.yml - hosts: web # група серверів з inventory become: true # sudo tasks: - name: Install nginx apt: { name: nginx, state: present } # модуль; повтор нічого не змінить - name: Start nginx service: { name: nginx, state: started, enabled: true } Inventory — список хостів і груп; модулі ( apt , copy , service ) ідемпотентні. Terraform: що ще варто знати Модулі — повторно використовувані набори ресурсів (власні або з Terraform Registry), викликаються блоком module . Значення змінних зручно задавати у файлі terraform.tfvars . Remote state : у команді state зберігають не локально, а в спільному бекенді (AWS S3, GCS, Terraform Cloud) з блокуванням (locking), щоб двоє не застосували зміни одночасно. State може містити секрети — у Git його не комітять. terraform fmt — форматує код, terraform validate — перевіряє синтаксис і логіку конфігурації без звернення до хмари."}, {"title": "Лекція 8 · Infrastructure as Code і Terraform: HCL, state, init → plan → apply", "section": "Ansible детально", "url": "lectures/week-2/lecture-8.html#ansible-deep", "text": "Ansible детально Inventory і ad-hoc команди # inventory.ini [web] web1 ansible_host=10.0.1.10 web2 ansible_host=10.0.1.11 [db] db1 ansible_host=10.0.2.20 [all:vars] ansible_user=ubuntu ansible_ssh_private_key_file=~/.ssh/study.pem ansible all -i inventory.ini -m ping # перевірити зв'язок (це не ICMP ping, а SSH + Python) ansible web -i inventory.ini -a \"uptime\" # виконати команду на групі web ansible web -i inventory.ini -b -m apt -a \"name=htop state=present\" # -b = become (sudo) ansible-playbook -i inventory.ini site.yml --check --diff # «сухий» прогін: що змінилося б ansible-playbook -i inventory.ini site.yml --limit web1 # лише на одному хості Playbook зі змінними, шаблоном і handler - name: Configure web servers hosts: web become: true vars: app_port: 8080 tasks: - name: Install nginx ansible.builtin.apt: name: nginx state: present update_cache: true - name: Deploy nginx config from template ansible.builtin.template: src: templates/site.conf.j2 # Jinja2: усередині {{ app_port }} dest: /etc/nginx/sites-available/default notify: Reload nginx # викликати handler, ЛИШЕ якщо файл змінився - name: Ensure nginx is running and enabled ansible.builtin.service: name: nginx state: started enabled: true handlers: - name: Reload nginx ansible.builtin.service: name: nginx state: reloaded Як працює ідемпотентність Перший запуск: changed=3 — пакет встановлено, файл записано, nginx перечитав конфіг. Другий запуск без змін у коді: changed=0 , усі задачі ok , handler не викликається. Модулі apt , template , service спершу перевіряють поточний стан. А от модулі shell і command ідемпотентності не мають — їм додають умови creates: / when: . Організація коду Roles — повторно використовувані набори задач, шаблонів, змінних і handler-ів у стандартній структурі ( roles/nginx/tasks/main.yml , templates/ , handlers/ , defaults/ ). Готові ролі — в Ansible Galaxy. Змінні можна задавати в inventory, у group_vars/web.yml , host_vars/web1.yml , у playbook, з командного рядка ( -e ). Facts — змінні, які Ansible сам збирає про хост (ОС, IP, пам'ять): {{ ansible_facts['distribution'] }} . Ansible Vault шифрує файли з секретами: ansible-vault create secrets.yml , запуск з --ask-vault-pass . Ter"}, {"title": "Лекція 8 · Infrastructure as Code і Terraform: HCL, state, init → plan → apply", "section": "Типові помилки", "url": "lectures/week-2/lecture-8.html#mistakes", "text": "Типові помилки Кілька аргументів блоку можна записати в один рядок через кому. В один рядок пишеться блок лише з одним аргументом; кома допустима всередині значень-об'єктів ( tags = { a = 1, b = 2 } ). .terraform.lock.hcl треба додати в .gitignore разом з .terraform/ . Lock-файл фіксує версії провайдерів — його комітять. Ігнорують каталог .terraform/ і state-файли. count і for_each взаємозамінні. count адресує за індексом: видалення елемента з середини зсуває решту і викликає перестворення. for_each адресує за ключем. Рядок -/+ у плані — безпечне оновлення. Це знищення і повторне створення ресурсу. Для БД це означає втрату даних, якщо немає бекапу чи prevent_destroy . Модуль shell в Ansible ідемпотентний, як і apt . shell і command виконуються щоразу. Для ідемпотентності — спеціалізовані модулі або умови creates / when . Одразу terraform apply без plan . Plan показує, що буде створено (+), змінено (~) і знищено (−) . Читайте його завжди — деякі зміни перестворюють ресурс. Змінити ВМ вручну в консолі, «бо швидше». З'являється дрейф: код і реальність розходяться, наступний apply поверне або зламає зміни. Усі зміни — через код. Видалити terraform.tfstate , «бо заважає». Без state Terraform «забуде» створені ресурси і спробує створити їх заново. State бережуть і зберігають віддалено. Terraform і Ansible — взаємозамінні. Terraform — provisioning (створити інфраструктуру), Ansible — configuration management (налаштувати ПЗ на ній). Їх часто використовують разом."}, {"title": "Лекція 9 · Віртуалізація і контейнери: гіпервізор, namespaces, Docker і Dockerfile", "section": "Вступ", "url": "lectures/week-2/lecture-9.html", "text": ""}, {"title": "Лекція 9 · Віртуалізація і контейнери: гіпервізор, namespaces, Docker і Dockerfile", "section": "Чого ви навчитесь", "url": "lectures/week-2/lecture-9.html#goals", "text": "Чого ви навчитесь Порівняти віртуальні машини і контейнери за архітектурою та витратою ресурсів. Назвати механізми ядра Linux, на яких тримаються контейнери: namespaces , cgroups , capabilities . Розрізняти образ , контейнер , registry і пояснити архітектуру Docker Engine. Написати Dockerfile і пояснити різницю між RUN , CMD , ENTRYPOINT , EXPOSE . Користуватися основними командами: pull , build , run -p , ps , exec , stop , rm , rmi . Розрізняти гіпервізори типу 1 і 2, пояснити шари образу і томи, підняти стек через Docker Compose і назвати базові об'єкти Kubernetes. Розрізняти shell і exec форми, CMD і ENTRYPOINT, ARG і ENV, COPY і ADD; писати багатоетапний Dockerfile за найкращими практиками. Запускати контейнери з потрібними опціями, мережами, томами, обмеженнями; публікувати образи в реєстр; діагностувати за кодами виходу. Пояснити архітектуру Kubernetes і об'єкти Pod, Deployment, Service, Ingress, ConfigMap, Secret; писати маніфест і користуватися kubectl."}, {"title": "Лекція 9 · Віртуалізація і контейнери: гіпервізор, namespaces, Docker і Dockerfile", "section": "Віртуалізація", "url": "lectures/week-2/lecture-9.html#virtualization", "text": "Віртуалізація Принцип «один застосунок — один фізичний сервер» означає: багато серверів, ліцензії ОС для кожного і низьке завантаження кожної машини. Розділяй і володарюй — розв'язок дає віртуалізація. Визначення Гіпервізор (VMM, virtual machine monitor) — ПЗ, прошивка або залізо, що створює і запускає віртуальні машини. Комп'ютер із гіпервізором — host (хост), кожна ВМ — guest (гість). Приклади: KVM, Xen, VMware, Oracle VirtualBox. Але для клієнта цінність — застосунок , а не ОС. У кожній ВМ своя повна ОС, яка споживає багато CPU, RAM і диска: OS ≠ business value ."}, {"title": "Лекція 9 · Віртуалізація і контейнери: гіпервізор, namespaces, Docker і Dockerfile", "section": "ВМ vs контейнер", "url": "lectures/week-2/lecture-9.html#vm-vs-container", "text": "ВМ vs контейнер Головна різниця: ВМ віртуалізує залізо (у кожної своє ядро), контейнер — ОС (ядро спільне). Контейнери легші, але слабше ізольовані. Віртуальна машина Контейнер Що віртуалізує Залізо (через гіпервізор) ОС (OS-level virtualization) Ядро Власне в кожній ВМ Спільне ядро хоста Ресурси Багато CPU/RAM/диска на ОС Менше CPU, RAM і диска Ізоляція Сильніша Достатня для більшості задач, але слабша Інша ОС Можна (Windows-гість на Linux-хості) Тільки під ядро хоста (Linux-контейнери на Linux) Конфлікт бібліотек: два застосунки на одному сервері потребують різних версій однієї бібліотеки — у спільній ОС конфлікт. У контейнерах кожен застосунок несе свій user space зі своїми версіями."}, {"title": "Лекція 9 · Віртуалізація і контейнери: гіпервізор, namespaces, Docker і Dockerfile", "section": "Як працюють контейнери: механізми ядра", "url": "lectures/week-2/lecture-9.html#kernel", "text": "Як працюють контейнери: механізми ядра Контейнери — це можливість Unix-подібних ОС , а не винахід Docker. Docker лише зручна обгортка над функціями ядра. Namespaces Ізоляція «що бачить процес» PID — свої процеси (усередині свій PID 1), MNT — своя файлова система, NET — своя мережа, USER — свої користувачі й привілеї. Control groups (cgroups) Обмеження ресурсів Групують процеси і ставлять ліміти: скільки CPU, RAM, I/O може взяти контейнер. Capabilities Дрібні привілеї Замість «усе або нічого» root — окремі дозволи (напр. лише прив'язка до порту < 1024). Формула зі слайдів cgroups + namespaces + image = Docker-контейнер . Namespaces дають ізоляцію, cgroups — ліміти, образ — файлову систему із застосунком."}, {"title": "Лекція 9 · Віртуалізація і контейнери: гіпервізор, namespaces, Docker і Dockerfile", "section": "Docker: архітектура і терміни", "url": "lectures/week-2/lecture-9.html#docker", "text": "Docker: архітектура і терміни Docker — набір PaaS-продуктів, що використовують віртуалізацію рівня ОС для постачання ПЗ в пакетах — контейнерах . Docker Engine — клієнт-серверний застосунок: CLI-клієнт спілкується з демоном dockerd через REST API . Image Образ Шаблон застосунку: набір файлів і параметрів. Конструкція часу збирання (build time). Не файлова система і не віртуальний диск — по суті tar-архів шарів з ієрархією. Container Контейнер Запущений екземпляр образу — ізольований процес на Docker-хості зі спільним ядром. Конструкція часу виконання (runtime). Registry Реєстр Мережеве сховище образів, приватне чи публічне. Найбільший публічний — Docker Hub. Dockerfile Рецепт образу Текстовий файл з інструкціями, які Docker виконує, щоб зібрати образ. Шари образу Образ складається з шарів : кожна інструкція Dockerfile — окремий шар, усі шари образу лише для читання . Коли запускається контейнер, зверху додається тонкий записуваний шар — зміни контейнера живуть лише в ньому і зникають разом із контейнером. Спільні шари (напр. базовий python ) зберігаються один раз для всіх образів."}, {"title": "Лекція 9 · Віртуалізація і контейнери: гіпервізор, namespaces, Docker і Dockerfile", "section": "Dockerfile", "url": "lectures/week-2/lecture-9.html#dockerfile", "text": "Dockerfile Dockerfile схожий на shell-скрипт із ключовими словами: розширює базовий образ ( FROM ) і дає новий образ . Формат: # коментар і ІНСТРУКЦІЯ аргументи . docker build збирає образ з Dockerfile і контексту — набору файлів за шляхом (PATH) або URL Git-репозиторію. Інструкція Призначення FROM Базовий образ (перша інструкція) RUN Крок збирання : виконати команду і зафіксувати результат у новому шарі (встановити пакети). Може бути багато COPY / ADD Скопіювати файли з контексту в образ ( ADD вміє ще URL і розпакування архівів) WORKDIR Робочий каталог для наступних інструкцій ENV , LABEL Змінні оточення, метадані EXPOSE Документує , який порт слухає контейнер (саме по собі порт не публікує) CMD Команда за замовчуванням при старті контейнера. Діє лише остання; перевизначається: docker run image інша_команда ENTRYPOINT Головна команда контейнера; CMD тоді стає її аргументами за замовчуванням VOLUME , HEALTHCHECK , USER … Томи для даних, перевірка здоров'я, користувач тощо"}, {"title": "Лекція 9 · Віртуалізація і контейнери: гіпервізор, namespaces, Docker і Dockerfile", "section": "Dockerfile детально: CMD vs ENTRYPOINT, багатоетапна збірка, найкращі практики", "url": "lectures/week-2/lecture-9.html#dockerfile-deep", "text": "Dockerfile детально: CMD vs ENTRYPOINT, багатоетапна збірка, найкращі практики Форми shell і exec Форма Запис Як запускається exec (рекомендована) CMD [\"python\", \"app.py\"] програма стає процесом з PID 1 і отримує сигнали ( docker stop → SIGTERM) напряму shell CMD python app.py загортається в /bin/sh -c \"python app.py\" ; PID 1 — оболонка, яка може не передати SIGTERM застосунку, і контейнер зупиниться лише через 10 с примусово CMD vs ENTRYPOINT: що виконається Dockerfile docker run img docker run img --help CMD [\"nginx\", \"-g\", \"daemon off;\"] nginx -g daemon off; --help (CMD повністю замінено, найімовірніше помилка) ENTRYPOINT [\"curl\"] curl curl --help ENTRYPOINT [\"curl\"] + CMD [\"https://example.com\"] curl https://example.com curl --help (CMD — аргументи за замовчуванням, їх замінено) Правило: ENTRYPOINT — «що це за програма», CMD — «аргументи за замовчуванням». ENTRYPOINT перевизначається лише явно: docker run --entrypoint sh img . Інші пари, які плутають ARG vs ENV : ARG VERSION=1.2 існує лише під час збирання ( docker build --build-arg VERSION=1.3 ); ENV APP_ENV=prod зберігається в образі і доступна в запущеному контейнері (перевизначається docker run -e ). COPY vs ADD : використовуйте COPY ; ADD додатково розпаковує локальні tar-архіви і завантажує URL, що робить збірку менш передбачуваною. RUN vs CMD : RUN виконується під час збирання і фіксує результат у шарі; CMD — під час запуску контейнера. EXPOSE vs -p : EXPOSE 8080 лише документує порт; відкриває його назовні лише docker run -p 8282:8080 . Багатоетапна збірка (multi-stage build) Інструменти збирання (компілятор, dev-залежності) не потрібні в production-образі. Багатоетапна збірка використовує кілька FROM : у першому етапі збирають, у фінальний копіюють лише результат. # ---- етап 1: збірка ---- FROM node:20 AS build WORKDIR /app COPY package*.json ./ RUN npm ci # залежності — окремим шаром, кешується COPY . . RUN npm run build # результат у /app/dist # ---- етап 2: лише статичні файли за nginx ---- FROM nginx:1.27-alpine COPY --from=build /app/dist /usr/share/nginx/html EXPOSE 80 HEALTHCHECK CMD wget -qO- http://localhost/ || exit 1 Образ node:20 важить понад 1 ГБ, а фінальний на nginx:alpine — десятки "}, {"title": "Лекція 9 · Віртуалізація і контейнери: гіпервізор, namespaces, Docker і Dockerfile", "section": "Практичний кейс: Python-вебсервер у контейнері", "url": "lectures/week-2/lecture-9.html#case", "text": "Практичний кейс: Python-вебсервер у контейнері Файли з архіву лекції server.zip : server.py #!/usr/bin/env python3 import http.server import socketserver handler = http.server.SimpleHTTPRequestHandler with socketserver.TCPServer((\"\", 1234), handler) as httpd: httpd.serve_forever() Dockerfile FROM python:latest ADD server.py /server/ ADD index.html /server/ WORKDIR /server/ CMD [\"python\", \"./server.py\"] EXPOSE 1234 docker build -t serverimage . # -t — тег (ім'я) образу, . — контекст docker run --name myserver -d -p 1234:1234 serverimage # -d у фоні, -p ХОСТ:КОНТЕЙНЕР curl http://localhost:1234 # Hello world! Мапінг портів: перше число — порт хоста, друге — порт усередині контейнера."}, {"title": "Лекція 9 · Віртуалізація і контейнери: гіпервізор, namespaces, Docker і Dockerfile", "section": "Шпаргалка команд", "url": "lectures/week-2/lecture-9.html#commands", "text": "Шпаргалка команд Команда Що робить docker pull openjdk:8-jdk Завантажити образ з Docker Hub (тег після : , без тегу — latest ) docker images Список локальних образів docker ps / docker ps -a Запущені / усі контейнери docker run --name java8 -it openjdk:8-jdk Створити й запустити контейнер з інтерактивним терміналом ( -i вхід, -t TTY) docker stop <id> / docker start <id> Зупинити / запустити існуючий контейнер docker exec -it java8 bash Виконати команду (shell) у запущеному контейнері docker cp app.jar java8:/app.jar Скопіювати файл у контейнер docker commit <id> imagejava8 Зберегти стан контейнера як новий образ (краще — Dockerfile) docker logs <id> Логи контейнера docker rm <id> / docker rmi <id> Видалити контейнер / образ Встановлення на Linux на лекції: curl -fsSL https://get.docker.com/ | sh , далі systemctl enable --now docker . З чату: Docker працює й на Windows; образ той самий, важлива лише архітектура процесора. Альтернативи Docker (наприклад, Podman) використовують ті самі механізми ядра."}, {"title": "Лекція 9 · Віртуалізація і контейнери: гіпервізор, namespaces, Docker і Dockerfile", "section": "Запуск контейнерів: опції, мережі, діагностика", "url": "lectures/week-2/lecture-9.html#runtime", "text": "Запуск контейнерів: опції, мережі, діагностика Опції docker run Опція Значення Приклад -d у фоні (detached) docker run -d nginx -it інтерактивно з терміналом docker run -it ubuntu bash --name ім'я контейнера --name web -p хост:контейнер опублікувати порт -p 8080:80 ; -p 127.0.0.1:8080:80 — лише локально -e , --env-file змінні оточення -e DB_HOST=db -v , --mount том або каталог хоста -v data:/var/lib/mysql --rm видалити контейнер після зупинки для разових задач --restart політика перезапуску: no , on-failure , always , unless-stopped --restart unless-stopped --network до якої мережі підключити --network appnet -m , --cpus обмеження пам'яті і CPU (cgroups) -m 512m --cpus 1.5 Схему публікації порту -p 8282:8080 див. у розділі «Практичний кейс» вище: запит на порт хоста перенаправляється на порт усередині контейнера. Мережі Docker Драйвер Поведінка bridge (за замовчуванням) контейнери в приватній мережі 172.17.0.0/16 на хості; назовні — через NAT і -p користувацька bridge ( docker network create appnet ) те саме, плюс вбудований DNS : контейнери знаходять один одного за іменами. Саме так працює Compose host контейнер використовує мережевий стек хоста напряму, без ізоляції і без -p none без мережі docker network create appnet docker run -d --name db --network appnet -e POSTGRES_PASSWORD=secret postgres:16 docker run -d --name api --network appnet -e DB_HOST=db -p 8080:8080 myapi:1.0 # api звертається до бази за адресою db:5432 — ім'я розв'язує DNS Docker Життєвий цикл і діагностика Стани контейнера: created → running → paused / exited → видалений. Контейнер живе, поки працює його головний процес (PID 1): процес завершився — контейнер перейшов у exited . Команда Навіщо docker ps -a стан і код виходу: Exited (1) docker logs -f --tail 100 web stdout/stderr контейнера наживо docker inspect web повна конфігурація: IP, томи, змінні, політика перезапуску docker exec -it web sh зайти всередину запущеного контейнера docker stats CPU, пам'ять, мережа кожного контейнера наживо docker system df / docker system prune скільки місця займають образи і контейнери / прибрати невикористане Код виходу Типова причина 0 процес завершився нормально (наприклад, CMD — разова команда, а не се"}, {"title": "Лекція 9 · Віртуалізація і контейнери: гіпервізор, namespaces, Docker і Dockerfile", "section": "Типи гіпервізорів, шари, томи, Compose і Kubernetes", "url": "lectures/week-2/lecture-9.html#more", "text": "Типи гіпервізорів, шари, томи, Compose і Kubernetes Гіпервізор типу 1 (bare-metal) Ставиться прямо на залізо замість ОС. Для дата-центрів і хмар. VMware ESXi, Microsoft Hyper-V, Xen, KVM . Гіпервізор типу 2 (hosted) Звичайна програма всередині ОС. Для навчання і розробки. Oracle VirtualBox, VMware Workstation . Шари образу і кеш збірки Кожна інструкція Dockerfile, що змінює файлову систему ( RUN , COPY , ADD ), створює шар (layer) . Шари лише для читання, кешуються і спільні між образами. Якщо шар змінився, усі шари після нього збираються наново — тому рідко змінні кроки (встановлення залежностей) ставлять вище, а COPY . . з кодом — нижче. Файл .dockerignore не пускає в образ зайве ( .git , node_modules ). Томи: дані поза контейнером Контейнер ефемерний : після docker rm усе, що він записав у себе, зникає. Дані БД зберігають у volume : docker run -v pgdata:/var/lib/postgresql/data postgres (іменований том) або -v /home/me/site:/usr/share/nginx/html (bind mount — каталог хоста). Docker Compose — кілька контейнерів одним файлом # docker-compose.yml services: web: build: . # зібрати з Dockerfile поруч ports: [\"8080:80\"] # хост:контейнер depends_on: [db] db: image: mysql:8 environment: { MYSQL_ROOT_PASSWORD: secret } volumes: [\"dbdata:/var/lib/mysql\"] volumes: dbdata: docker compose up -d — підняти все у фоні, docker compose logs — логи, docker compose down — зупинити й видалити контейнери. Сервіси бачать одне одного за іменами ( web звертається до db:3306 ). Kubernetes коротко Kubernetes (K8s) — оркестратор контейнерів: запускає їх на кластері з багатьох машин, перезапускає впалі, масштабує і оновлює без простою. Кластер = control plane (керування) + worker nodes (де працюють контейнери). Pod Под Найменша одиниця: один або кілька контейнерів зі спільною мережею. Deployment Розгортання Скільки реплік поду тримати; плавне оновлення (rolling update). Service Сервіс Стабільна адреса і балансування між подами. Керують через kubectl : kubectl apply -f app.yaml , kubectl get pods . Маніфести — декларативний YAML."}, {"title": "Лекція 9 · Віртуалізація і контейнери: гіпервізор, namespaces, Docker і Dockerfile", "section": "Kubernetes детальніше", "url": "lectures/week-2/lecture-9.html#k8s", "text": "Kubernetes детальніше Архітектура кластера Компонент Де Роль kube-apiserver control plane єдина точка входу: усі команди kubectl і компоненти спілкуються через його API etcd control plane розподілене сховище «ключ-значення» з усім станом кластера kube-scheduler control plane обирає вузол для кожного нового поду (за ресурсами, правилами) kube-controller-manager control plane контролери, що постійно приводять реальний стан до бажаного (немає 3 реплік — створити) kubelet кожен вузол агент, що запускає контейнери подів через container runtime (containerd) kube-proxy кожен вузол правила мережі для Service Основні об'єкти Об'єкт Призначення Pod один або кілька контейнерів зі спільною IP і томами; ефемерний ReplicaSet тримає задану кількість однакових подів Deployment керує ReplicaSet-ами: rolling update і rollback ( kubectl rollout undo ) Service стабільне ім'я і IP для набору подів: ClusterIP (лише всередині кластера), NodePort (порт на кожному вузлі), LoadBalancer (хмарний балансувальник) Ingress HTTP-маршрутизація ззовні: домени і шляхи → сервіси, TLS ConfigMap / Secret конфігурація / секрети, що передаються в под як змінні або файли Namespace логічний поділ кластера (dev, staging, команди) PersistentVolume / PVC постійне сховище для даних, що переживає перезапуск подів StatefulSet, DaemonSet, Job, CronJob для БД зі стабільними іменами / по поду на кожному вузлі / разові й періодичні задачі Маніфест: Deployment + Service apiVersion: apps/v1 kind: Deployment metadata: name: web spec: replicas: 3 # бажаний стан: три поди selector: matchLabels: { app: web } template: metadata: labels: { app: web } spec: containers: - name: web image: ghcr.io/anna/myapp:1.4.2 ports: [{ containerPort: 8080 }] resources: requests: { cpu: 100m, memory: 128Mi } limits: { memory: 256Mi } readinessProbe: # под отримує трафік лише коли готовий httpGet: { path: /health, port: 8080 } livenessProbe: # завис — kubelet перезапустить контейнер httpGet: { path: /health, port: 8080 } --- apiVersion: v1 kind: Service metadata: name: web spec: selector: { app: web } # трафік на поди з міткою app=web ports: [{ port: 80, targetPort: 8080 }] type: ClusterIP kubectl: найчастіші команди kubectl apply -f app"}, {"title": "Лекція 9 · Віртуалізація і контейнери: гіпервізор, namespaces, Docker і Dockerfile", "section": "Типові помилки", "url": "lectures/week-2/lecture-9.html#mistakes", "text": "Типові помилки EXPOSE 80 у Dockerfile відкриває порт назовні. EXPOSE лише документує порт. Назовні його публікує docker run -p 8080:80 . Видалити файл у наступному RUN — і образ стане меншим. Попередній шар уже містить файл. Чистити кеш треба в тому самому RUN або використовувати multi-stage build. Пароль БД можна покласти в ENV у Dockerfile. Його видно в docker history та inspect . Секрети передають під час запуску. Контейнер з кодом виходу 137 «впав через помилку в коді». 137 = 128 + 9: процес вбито SIGKILL, найчастіше через перевищення ліміту пам'яті (OOM). Service в Kubernetes — це контейнер. Service — стабільна адреса і балансування для набору подів, обраних за мітками. Дані, записані всередині контейнера, переживуть його видалення. Контейнер ефемерний. Усе важливе — у volume або bind mount. Образ і контейнер — одне й те саме. Образ — незмінний шаблон (build time), контейнер — його запущений екземпляр (runtime). З одного образу можна запустити багато контейнерів. EXPOSE 1234 робить сервіс доступним ззовні. EXPOSE лише документує порт. Публікує його docker run -p ХОСТ:КОНТЕЙНЕР . Запускати сервер через RUN python server.py . RUN виконується під час збирання образу. Команда старту контейнера — CMD або ENTRYPOINT (тому на слайді RUN закоментовано). Зберігати дані БД усередині контейнера. Записуваний шар зникає з контейнером. Дані виносять у томи ( -v / VOLUME ). Контейнер = «легка ВМ» з власним ядром. Контейнери ділять ядро хоста; ізоляцію дають namespaces, а ліміти — cgroups."}, {"title": "Лекція 10 · Системи контролю версій: Git, гілки, Git Flow і pull request", "section": "Вступ", "url": "lectures/week-2/lecture-10.html", "text": ""}, {"title": "Лекція 10 · Системи контролю версій: Git, гілки, Git Flow і pull request", "section": "Чого ви навчитесь", "url": "lectures/week-2/lecture-10.html#goals", "text": "Чого ви навчитесь Пояснити, яку проблему розв'язує VCS, і порівняти моделі lock-modify-unlock та copy-modify-merge . Розрізняти централізовані (SVN) і розподілені (Git) системи. Описати три зони Git — робочий каталог, індекс, репозиторій — і рух змін між ними. Користуватися базовими командами, розв'язувати конфлікти, відкочувати зміни ( reset vs revert ). Пояснити Git Flow , GitHub Flow і процес pull request . Пояснити, як Git зберігає дані (blob, tree, commit), що таке гілка, HEAD і detached HEAD. Знати стани файлів, різницю fetch і pull, upstream, і як скасувати будь-яку зміну (restore, reset, revert, reflog). Порівняти Git Flow, GitHub Flow і trunk-based; писати повідомлення комітів за Conventional Commits; налаштувати захист main, hooks і теги."}, {"title": "Лекція 10 · Системи контролю версій: Git, гілки, Git Flow і pull request", "section": "Навіщо контроль версій", "url": "lectures/week-2/lecture-10.html#why", "text": "Навіщо контроль версій Звичайний файловий сервер дає спільне сховище, але не пам'ятає історії. Репозиторій — особливий файловий сервер, що пам'ятає кожну зміну : кожного файла і навіть структури каталогів. Клієнт зазвичай бачить останню версію, але може переглянути будь-який попередній стан. Інструменти в історичному порядку: CVS (1986, клієнт-сервер, розвиток зупинено 2008), Apache Subversion (SVN) (2000, наступник CVS; клієнти TortoiseSVN, RabbitVCS), Microsoft VSS (для малих проєктів, підтримку завершено 2016), TFS (Team Foundation Server у складі Visual Studio Team System), і нарешті Git (2005). За словами інструктора, SVN зараз переважно трапляється в історії старих проєктів — основний інструмент Git. Проблема одночасного редагування Гаррі і Саллі одночасно редагують один файл. Гаррі зберігає першим, Саллі — за хвилину, і непомітно перезаписує зміни Гаррі. Вони не втрачені назавжди (система пам'ятає історію), але в останній версії їх немає. Lock-Modify-Unlock Щоб редагувати, файл треба заблокувати ; інші лише читають. Конфліктів немає, але люди чекають . Гаррі забув зняти блокування і пішов у відпустку — Саллі потрібен адміністратор. Copy-Modify-Merge Кожен працює зі своєю робочою копією , паралельно. Наприкінці копії зливаються (merge) ; VCS допомагає, але відповідає людина. Якщо зміни перетинаються — конфлікт , який розв'язує людина. На практиці конфлікти рідкісні й дешевші за очікування блокувань. Жодна система не виявить семантичні конфлікти (код зливається, але логіка ламається) — тому потрібні комунікація, рев'ю і тести. Централізовані vs розподілені VCS"}, {"title": "Лекція 10 · Системи контролю версій: Git, гілки, Git Flow і pull request", "section": "Git: старт", "url": "lectures/week-2/lecture-10.html#git", "text": "Git: старт Git — розподілена система контролю версій з акцентом на швидкість, цілісність даних і нелінійну розробку (багато гілок). Створена Лінусом Торвальдсом у 2005 для розробки ядра Linux. sudo apt install git # Debian/Ubuntu (Windows: git-scm.com/download/win) git config --global user.name \"Ivan Petrenko\" # автор комітів git config --global user.email \"ivan@example.com\" git config --list # перевірити налаштування git help commit # довідка: також git commit --help .gitignore — шаблони файлів, які Git не відстежує: порожні рядки і рядки з # ігноруються, / в кінці — каталог, ! — виняток. *.[oa] # об'єктні файли й архіви /target/ # каталог target у корені doc/*.txt # doc/notes.txt, але не doc/info/arch.txt doc/**/*.txt # усі .txt у doc на будь-якій глибині .env # секрети — ніколи не в Git"}, {"title": "Лекція 10 · Системи контролю версій: Git, гілки, Git Flow і pull request", "section": "Три зони Git і рух змін", "url": "lectures/week-2/lecture-10.html#areas", "text": "Три зони Git і рух змін Транспортні команди Git. Зелені стрілки ведуть зміни «вперед» до сервера, помаранчеві — повертають їх. Базовий цикл git init # новий репозиторій у поточному каталозі git clone https://github.com/user/repo.git # або копія існуючого git remote add origin <url> # прив'язати віддалений репо git remote -v # список remotes git status # що змінено / в індексі git add readme.txt # додати файл в індекс (git add . — усі) git diff --staged # що піде в коміт git commit -m \"Add readme\" # зафіксувати git commit --amend -m \"Better message\" # виправити ОСТАННІЙ коміт (до push!) git push origin main # відправити гілку main git pull origin main # забрати й злити зміни з сервера git log -3 / git log -p -2 / git log --since=2.weeks git reflog # журнал переміщень HEAD — рятує «втрачені» коміти git rm --cached file # прибрати з індексу, залишити на диску git mv old new # перейменувати Конфлікти Якщо дві гілки змінили той самий рядок, Git позначає конфлікт маркерами. Треба вручну залишити потрібний варіант, видалити маркери , зробити git add і коміт. <<<<<<< HEAD:index.html <div id=\"footer\">contact : email.support@github.com</div> ======= <div id=\"footer\">please contact us at support@github.com</div> >>>>>>> iss53:index.html Відкат змін: reset vs revert Команда Робочий каталог Індекс Локальний репо (HEAD) git reset --soft f314b2 без змін без змін переноситься git reset f314b2 (mixed) без змін оновлюється переноситься git reset --hard f314b2 перезаписується оновлюється переноситься reset переписує історію — безпечно лише для локальних, ще не надісланих комітів. Для вже опублікованих змін використовують git revert <sha> : він створює новий коміт , що скасовує старий, і нікому не ламає історію. git push -f (примусово) на спільну гілку — крайній захід."}, {"title": "Лекція 10 · Системи контролю версій: Git, гілки, Git Flow і pull request", "section": "Як Git влаштований усередині, стани файлів і скасування змін", "url": "lectures/week-2/lecture-10.html#internals", "text": "Як Git влаштований усередині, стани файлів і скасування змін Об'єкти, хеші і посилання Git зберігає не «різниці», а знімки (snapshots) проєкту. Усе лежить у каталозі .git/objects як об'єкти, ідентифіковані хешем SHA-1 (40 hex-символів; нові репозиторії можуть використовувати SHA-256): blob Вміст файла Лише байти, без імені. Однакові файли зберігаються один раз. tree Каталог Список імен і посилань на blob-и та інші tree. commit Коміт Посилання на кореневий tree, батьківський коміт(и), автор, дата, повідомлення. tag Анотований тег Іменована позначка на коміт з автором і повідомленням. Гілка — лише файл з хешем останнього коміту ( .git/refs/heads/main ). Тому гілки в Git створюються миттєво. HEAD — вказівник на поточну гілку (або напряму на коміт). cat .git/HEAD → ref: refs/heads/main . Detached HEAD — HEAD вказує на коміт, а не на гілку (після git checkout a1b2c3d або тегу). Нові коміти тут не належатимуть жодній гілці; щоб зберегти — git switch -c new-branch . Хеш коміту залежить від усього вмісту і батьків, тому зміна будь-якого старого коміту змінює хеші всіх наступних — так Git гарантує цілісність історії. Стани файлів Стан Значення Як перейти далі Untracked новий файл, Git його не відстежує git add file Modified змінений після останнього коміту, ще не в індексі git add file Staged у індексі, піде в наступний коміт git commit Committed (unmodified) збережений у локальному репозиторії git push — на сервер fetch vs pull, remote-tracking гілки git fetch завантажує нові коміти з сервера в remote-tracking гілки ( origin/main ), але не змінює ваші локальні гілки і робочий каталог. Безпечно в будь-який момент. git pull = git fetch + git merge origin/main (або --rebase ) у поточну гілку. git push -u origin feature/login — перший push нової гілки; -u запам'ятовує зв'язок (upstream), далі досить git push . git branch -vv покаже, на скільки комітів ви попереду/позаду сервера. Як скасувати що завгодно Ситуація Команда Відкинути незбережені зміни у файлі git restore app.py (раніше git checkout -- app.py ) Прибрати файл з індексу, залишивши зміни git restore --staged app.py (раніше git reset HEAD app.py ) Змінити повідомлення або додати файл до останнього коміту (ще не запу"}, {"title": "Лекція 10 · Системи контролю версій: Git, гілки, Git Flow і pull request", "section": "Гілки і стратегії", "url": "lectures/week-2/lecture-10.html#branches", "text": "Гілки і стратегії git branch testing # створити гілку git checkout testing # перейти (git checkout -b testing — створити й перейти) # … коміти … git checkout main git merge testing # злити testing у поточну (main) git branch -d testing # видалити локально git push origin :testing # видалити на сервері (або --delete testing) Git Flow. Дві «вічні» гілки (main, develop) і тимчасові допоміжні: feature, release, hotfix. Git Flow (Вінсент Дріссен, 2010) main (master) — production-код; develop — передрелізний код. Обидві існують завжди. feature-* : від develop → назад у develop. release-* : від develop → у main і develop (дрібні фікси, метадані релізу). hotfix-* : від main → у main і develop (терміново виправити production). GitHub Flow (GitHub, 2011) Усе в main — завжди готове до деплою. Нова робота — у гілці від main з описовою назвою ( new-oauth2-scopes ). Регулярно комітимо і пушимо гілку на сервер. Потрібен фідбек або готово — відкриваємо pull request . Після рев'ю і схвалення — merge у main і одразу деплой ."}, {"title": "Лекція 10 · Системи контролю версій: Git, гілки, Git Flow і pull request", "section": "Pull request: командна робота", "url": "lectures/week-2/lecture-10.html#pr", "text": "Pull request: командна робота Pull request (PR) повідомляє команду про зміни, які ви запушили в гілку. У PR обговорюють і переглядають код, додають нові коміти — і лише потім зливають у базову гілку. Це ключовий результат курсу: «репозиторій на GitHub з pull request-ами та рев'ю». Власник репозиторію запрошує учасників (collaborators) і налаштовує правила захисту гілки : зміни в main лише через PR, обов'язкове схвалення. Учасник клонує репозиторій і створює нову гілку. Змінює код → commit → push гілки. Відкриває pull request і чекає рев'ю. Після схвалення зміни зливаються; гілку зазвичай видаляє той, хто зробив merge. Секрети в репозиторії З чату лекції: якщо пароль чи токен випадково потрапив у Git, мало видалити його з історії — секрет треба негайно змінити (відкликати) , бо копії репозиторію вже могли розійтися. Великі бінарні файли в Git не зберігають (для цього є Git LFS)."}, {"title": "Лекція 10 · Системи контролю версій: Git, гілки, Git Flow і pull request", "section": "Командні практики: моделі гілок, коміти, захист main", "url": "lectures/week-2/lecture-10.html#workflows", "text": "Командні практики: моделі гілок, коміти, захист main Три популярні моделі гілок Модель Як працює Коли підходить Git Flow довгі гілки main і develop , плюс feature/* , release/* , hotfix/* продукти з плановими версіями (мобільні застосунки, коробкове ПЗ) GitHub Flow одна головна гілка main , яку завжди можна розгорнути; кожна зміна — коротка гілка + pull request + деплой після злиття вебсервіси з частим деплоєм Trunk-based development усі зливають маленькі зміни в main щонайменше щодня; незавершене ховають за feature flags команди з розвиненим CI/CD; рекомендується дослідженнями DORA Гарне повідомлення коміту fix(auth): reject expired JWT tokens ← заголовок до ~50 символів, наказовий спосіб Tokens were validated only by signature, so expired tokens were still accepted. Check the exp claim and return 401. Closes #142 ← посилання на задачу Специфікація Conventional Commits задає префікси: feat: (нова функція), fix: (виправлення), docs: , refactor: , test: , chore: , ci: ; BREAKING CHANGE — несумісна зміна. З таких комітів інструменти автоматично генерують changelog і наступну версію за SemVer. Один коміт — одна логічна зміна: так його легше переглянути і, якщо треба, відкотити через revert . Захист головної гілки Protected branch : заборонити прямий push і push --force у main . Обов'язковий pull request з мінімум одним схваленням (approve) і зеленими перевірками CI (required status checks). CODEOWNERS — файл, що автоматично призначає рецензентів для певних каталогів ( /infra/ @devops-team ). Підписані коміти (GPG/SSH) — підтвердження авторства. Хуки і перевірки до коміту Git hooks — скрипти в .git/hooks/ , що запускаються на події: pre-commit (перед комітом: лінтер, форматування, пошук секретів), commit-msg (перевірити формат повідомлення), pre-push (тести). Фреймворк pre-commit дає змогу зберігати набір перевірок у репозиторії ( .pre-commit-config.yaml ), щоб у всіх вони були однакові. Якщо в Git потрапив секрет Видалення файла новим комітом не допоможе: секрет залишається в історії, і його вже могли скопіювати. Порядок дій: негайно відкликати і замінити ключ чи пароль (rotate), потім за потреби почистити історію ( git filter-repo , BFG) і змусити всіх перевзяти р"}, {"title": "Лекція 10 · Системи контролю версій: Git, гілки, Git Flow і pull request", "section": "merge vs rebase, stash і розв'язання конфлікту", "url": "lectures/week-2/lecture-10.html#more", "text": "merge vs rebase, stash і розв'язання конфлікту git merge feature Створює merge-коміт з двома батьками. Історія чесна, але розгалужена. Безпечно для спільних гілок. git rebase main Переписує ваші коміти поверх main (нові хеші). Історія лінійна, без merge-комітів. Не робіть rebase гілок, які вже запушені й використовуються іншими. Конфлікт крок за кроком git merge feature → CONFLICT (content): Merge conflict in app.py . У файлі з'являються маркери: <<<<<<< HEAD (ваша версія) … ======= … >>>>>>> feature (версія гілки). Залишаєте потрібний код і видаляєте маркери . git add app.py — позначити конфлікт розв'язаним, потім git commit (або git merge --continue ). Передумали — git merge --abort . Ще корисні команди git stash # сховати незакомічені зміни (щоб перейти на іншу гілку) git stash pop # повернути їх git switch -c feature/login # створити гілку й перейти (= git checkout -b) git log --oneline --graph # компактна історія з гілками git diff # незаіндексовані зміни; git diff --staged — проіндексовані git cherry-pick a1b2c3d # перенести один коміт на поточну гілку git tag v1.0 # позначити реліз"}, {"title": "Лекція 10 · Системи контролю версій: Git, гілки, Git Flow і pull request", "section": "Типові помилки", "url": "lectures/week-2/lecture-10.html#mistakes", "text": "Типові помилки git fetch оновлює мою гілку і файли. fetch лише завантажує коміти в origin/*. Злиття у вашу гілку робить merge або pull. Секрет, який потрапив у коміт, досить видалити наступним комітом. Він лишається в історії. Спершу відкличте і замініть секрет, потім чистіть історію. Гілка в Git — копія всіх файлів проєкту. Гілка — лише вказівник на коміт, тому створюється миттєво. Робити git rebase гілки, з якою вже працюють інші. rebase змінює хеші комітів. Для спільних гілок використовуйте merge. git reset --hard або push -f на спільній гілці, щоб «прибрати» коміт. Для опублікованих комітів — git revert : новий коміт, що скасовує зміни, без переписування чужої історії. git pull і git fetch — одне й те саме. fetch лише завантажує зміни в локальний репо; pull = fetch + merge у поточну гілку. Зробив git add — зміни вже на GitHub. add → індекс, commit → локальний репо, і лише push → сервер. Комітити .env , ключі, terraform.tfstate . Додайте їх у .gitignore заздалегідь; секрети зберігайте в Secrets CI-системи."}, {"title": "Лекція 11 · CI/CD і Jenkins: конвеєр збирання, Jenkinsfile і Pipeline as Code", "section": "Вступ", "url": "lectures/week-3/lecture-11.html", "text": ""}, {"title": "Лекція 11 · CI/CD і Jenkins: конвеєр збирання, Jenkinsfile і Pipeline as Code", "section": "Чого ви навчитесь", "url": "lectures/week-3/lecture-11.html#goals", "text": "Чого ви навчитесь Пояснити, що таке Continuous Integration і з чого складається CI/CD-конвеєр. Описати архітектуру CI-сервера: VCS, тригер, агенти збирання, артефакти, деплой. Встановити Jenkins і знати його ключові налаштування. Прочитати і написати declarative Jenkinsfile : agent , stages , steps , post , parameters , when . Порівняти declarative і scripted pipeline та знати допоміжні інструменти Jenkins. Пояснити архітектуру Jenkins: контролер, агенти, executors, мітки, workspace; типи задач і статуси збірки. Безпечно працювати з секретами (Credentials, withCredentials, sshagent) і знати правила безпеки Jenkins. Написати повний конвеєр: тести з junit, збірка і публікація Docker-образу, деплой зі схваленням; знати вбудовані змінні. Порівняти Jenkins з GitHub Actions, GitLab CI, TeamCity та іншими системами."}, {"title": "Лекція 11 · CI/CD і Jenkins: конвеєр збирання, Jenkinsfile і Pipeline as Code", "section": "Continuous Integration", "url": "lectures/week-3/lecture-11.html#ci", "text": "Continuous Integration Визначення Continuous Integration (CI) — практика, коли розробники часто (щонайменше щодня) інтегрують зміни в спільну гілку, а кожна інтеграція перевіряється автоматичним збиранням і тестами . Мета — знаходити помилки інтеграції якнайраніше (класичний опис — стаття Мартіна Фаулера «Continuous Integration»). CI-цикл. Тригер — webhook на push або періодичне опитування репозиторію (poll SCM). Далі по конвеєру — Continuous Delivery (кожна вдала збірка готова до релізу, вихід у production — після ручного схвалення) і Continuous Deployment (повністю автоматично). Різницю ми розібрали в лекції 1."}, {"title": "Лекція 11 · CI/CD і Jenkins: конвеєр збирання, Jenkinsfile і Pipeline as Code", "section": "Jenkins", "url": "lectures/week-3/lecture-11.html#jenkins", "text": "Jenkins Що це Open-source CI/CD-сервер з вебінтерфейсом. Написаний на Java, працює в servlet-контейнері. Наступник (форк) Hudson. Факти зі слайдів Перший реліз — 2005 (як Hudson), ліцензія MIT, активна незалежна спільнота, 1500+ плагінів . Jenkins 2.0 (2016) Pipeline — «громадянин першого класу»: Pipeline as Code (Jenkinsfile) і новий інтерфейс Blue Ocean. Встановлення (CentOS, як на лекції) java -version # Jenkins потребує Java wget -O /etc/yum.repos.d/jenkins.repo http://jenkins-ci.org/redhat/jenkins.repo rpm --import http://pkg.jenkins-ci.org/redhat/jenkins-ci.org.key yum install jenkins service jenkins start # далі http://server:8080 Налаштування сервісу — /etc/sysconfig/jenkins : JENKINS_HOME=\"/var/lib/jenkins\" (усі задачі, плагіни, історія), JENKINS_USER=\"jenkins\" , JENKINS_PORT=\"8080\" . Після першого входу: оновити/встановити плагіни, налаштувати Maven (для Java-проєктів), Git-плагін, і SSH-ключ для доступу до репозиторію ( ssh-keygen → публічний ключ у GitHub, як у лекції 2). Адреси репозиторіїв Jenkins з часом змінювались — актуальну інструкцію беріть на jenkins.io."}, {"title": "Лекція 11 · CI/CD і Jenkins: конвеєр збирання, Jenkinsfile і Pipeline as Code", "section": "Архітектура Jenkins: контролер, агенти, задачі, облікові дані", "url": "lectures/week-3/lecture-11.html#arch", "text": "Архітектура Jenkins: контролер, агенти, задачі, облікові дані Розподілені збірки. Контролер керує, агенти виконують. На production-контролері самі збірки не запускають. Поняття Значення Controller (колишній master) центральний сервер: UI, планування, конфігурація, плагіни, облікові дані, історія збірок Agent (node, slave) машина або контейнер, де виконуються збірки. Підключається по SSH (контролер ходить на агента) або inbound (агент сам підключається до контролера) Executor слот для однієї збірки на агенті; 2 executors = 2 паралельні збірки Label мітка агента ( linux , docker , gpu ); у Jenkinsfile — agent { label 'docker' } Workspace каталог на агенті, куди клонується код і де йде збірка ( $WORKSPACE ) Build один запуск задачі з номером ( #42 ), логом консолі, артефактами і статусом Типи задач і статуси збірки Freestyle — налаштування мишкою у вебформі (старий підхід, не версіонується). Pipeline — конвеєр з Jenkinsfile. Multibranch Pipeline — окрема задача для кожної гілки і PR репозиторію з Jenkinsfile. Folder / Organization Folder — групування і автоматичне сканування організації GitHub. Статус Колір Значення SUCCESS зелений (синій у старому UI) усі кроки пройшли UNSTABLE жовтий збірка є, але частина тестів впала (наприклад, junit знайшов провалені тести) FAILURE червоний крок завершився помилкою (ненульовий код sh , помилка компіляції) ABORTED сірий зупинено вручну або за тайм-аутом NOT_BUILT сірий етап пропущено (наприклад, умова when не виконалась) Облікові дані (Credentials) Секрети зберігаються в Jenkins зашифровано і підставляються в збірку за ID, а в лозі маскуються як **** . Типи: Username with password, Secret text (токен), SSH Username with private key, Secret file, Certificate. withCredentials([usernamePassword(credentialsId: 'dockerhub', usernameVariable: 'DOCKER_USER', passwordVariable: 'DOCKER_PASS')]) { sh 'echo \"$DOCKER_PASS\" | docker login -u \"$DOCKER_USER\" --password-stdin' } sshagent(['deploy-key']) { sh 'ssh -o StrictHostKeyChecking=no deploy@10.0.1.10 \"sudo systemctl restart app\"' } Зверніть увагу на одинарні лапки в sh '...' : змінну розкриє shell, а не Groovy, тож секрет не потрапить у текст команди, що логується. У подвійних лапках Gr"}, {"title": "Лекція 11 · CI/CD і Jenkins: конвеєр збирання, Jenkinsfile і Pipeline as Code", "section": "Jenkinsfile: Pipeline as Code", "url": "lectures/week-3/lecture-11.html#jenkinsfile", "text": "Jenkinsfile: Pipeline as Code Jenkinsfile — опис конвеєра на Groovy DSL , що лежить у репозиторії поруч із кодом. Переваги зберігання в SCM: рев'ю й ітерації коду конвеєра, журнал змін (audit trail) , єдине джерело правди . Declarative (з 2017) Декларативна модель, простіший і «суворіший» синтаксис Валідація і візуальний редактор Обмежує можливості — ідеально для типових CD-конвеєрів Scripted Імперативна модель — повноцінна мова програмування Максимальна гнучкість, майже без обмежень Для досвідчених користувачів і складних вимог Спільне: обидва на Groovy, той самий Pipeline-движок, переважно однакові кроки, обидва вміють Shared Libraries і змішуються через крок script . Анатомія declarative pipeline. Stage — логічний етап (видно в UI), step — конкретна дія всередині. Приклад declarative Jenkinsfile Зібрано з фрагментів слайдів (settings, stages, parameters, approval, post): pipeline { agent any triggers { pollSCM( 'H/5 * * * *' ) } // перевіряти репозиторій кожні 5 хв options { timeout(time: 60, unit: 'MINUTES' ) buildDiscarder(logRotator(numToKeepStr: '30' )) // зберігати 30 останніх збірок } parameters { string(name: 'DEPLOY_ENV' , defaultValue: 'TESTING' , description: 'The target environment' ) } environment { AWS_ACCESS_KEY_ID = credentials( 'my-aws-key' ) // секрет із Jenkins Credentials } stages { stage( 'Build & unit tests' ) { steps { checkout scm sh './gradlew build' stash name: 'my-workspace' , includes: 'build/**' } } stage( 'Acceptance tests' ) { parallel { // гілки виконуються одночасно stage( 'Firefox' ) { steps { echo 'testing Firefox' } } stage( 'Chrome' ) { steps { echo 'testing Chrome' } } } } stage( 'Deploy to Stage' ) { when { branch 'master' } // лише для master steps { timeout(time: 30, unit: 'DAYS' ) { input message: 'Deploy to Stage?' , submitter: 'admin,pete.pm' } unstash 'my-workspace' sh \"echo deploying build ${env.BUILD_NUMBER} to ${params.DEPLOY_ENV}\" } } } post { failure { emailext subject: \"FAILED: ${env.JOB_NAME} [${env.BUILD_NUMBER}]\" , body: \"Check console output at ${env.BUILD_URL}\" , recipientProviders: [culprits()] } } } Елемент Що робить agent Де виконувати: any , мітка вузла, Docker-контейнер; agent none на верхньому рівні"}, {"title": "Лекція 11 · CI/CD і Jenkins: конвеєр збирання, Jenkinsfile і Pipeline as Code", "section": "Повний конвеєр: тести → Docker-образ → реєстр → деплой", "url": "lectures/week-3/lecture-11.html#full-pipeline", "text": "Повний конвеєр: тести → Docker-образ → реєстр → деплой pipeline { agent { label 'docker' } environment { IMAGE = \"ghcr.io/anna/shop-api\" TAG = \"${env.BUILD_NUMBER}-${env.GIT_COMMIT.take(7)}\" // напр. 42-a1b2c3d } options { timeout(time: 30, unit: 'MINUTES') disableConcurrentBuilds() buildDiscarder(logRotator(numToKeepStr: '20')) } triggers { githubPush() } // webhook від GitHub stages { stage('Test') { agent { docker { image 'python:3.12-slim'; reuseNode true } } steps { sh 'pip install -r requirements.txt' sh 'pytest --junitxml=reports/junit.xml' } post { always { junit 'reports/junit.xml' } } // графік тестів у UI, UNSTABLE при падіннях } stage('Build image') { steps { sh 'docker build -t $IMAGE:$TAG .' } } stage('Push image') { when { branch 'main' } steps { withCredentials([usernamePassword(credentialsId: 'ghcr', usernameVariable: 'U', passwordVariable: 'P')]) { sh 'echo \"$P\" | docker login ghcr.io -u \"$U\" --password-stdin' sh 'docker push $IMAGE:$TAG' } } } stage('Deploy to staging') { when { branch 'main' } steps { sshagent(['staging-key']) { sh 'ssh deploy@staging.local \"docker pull $IMAGE:$TAG && docker rm -f api || true && docker run -d --name api -p 80:8000 $IMAGE:$TAG\"' } } } stage('Deploy to production') { when { branch 'main' } steps { input message: \"Deploy ${TAG} to production?\", submitter: 'release-managers' sh 'kubectl set image deploy/api api=$IMAGE:$TAG' // Continuous Delivery: реліз після схвалення людиною } } } post { success { echo \"OK: ${env.BUILD_URL}\" } failure { echo \"FAILED: ${env.JOB_NAME} #${env.BUILD_NUMBER}\" } // тут — Slack/email always { sh 'docker image prune -f || true' } } } Вбудовані змінні Jenkins Змінна Значення BUILD_NUMBER номер збірки: 42 BUILD_ID , BUILD_URL ідентифікатор і посилання на збірку JOB_NAME ім'я задачі (для multibranch — з гілкою) WORKSPACE шлях до робочого каталогу на агенті BRANCH_NAME гілка (у multibranch pipeline) GIT_COMMIT хеш коміту, що збирається NODE_NAME агент, на якому йде збірка Список з описами — на сторінці http://jenkins:8080/env-vars.html . Тег образу з номером збірки і хешем коміту однозначно пов'язує образ у реєстрі з кодом і збіркою, на відміну від latest ."}, {"title": "Лекція 11 · CI/CD і Jenkins: конвеєр збирання, Jenkinsfile і Pipeline as Code", "section": "Jenkins і інші CI/CD-системи", "url": "lectures/week-3/lecture-11.html#ci-tools", "text": "Jenkins і інші CI/CD-системи Система Розміщення Опис конвеєра Особливості Jenkins власний сервер (self-hosted) Jenkinsfile (Groovy) максимальна гнучкість, 1800+ плагінів, але сервер треба адмініструвати і оновлювати GitHub Actions хмара GitHub (+ self-hosted runners) YAML у .github/workflows/ інтеграція з GitHub, маркетплейс готових дій (лекція 12) GitLab CI/CD GitLab.com або власний GitLab .gitlab-ci.yml вбудований у GitLab разом з реєстром і середовищами TeamCity власний сервер / хмара JetBrains UI або Kotlin DSL зручний для .NET і Java Azure Pipelines Azure DevOps YAML інтеграція з екосистемою Microsoft CircleCI , Travis CI хмара YAML популярні для open source Argo CD , Flux у Kubernetes маніфести в Git лише CD за підходом GitOps"}, {"title": "Лекція 11 · CI/CD і Jenkins: конвеєр збирання, Jenkinsfile і Pipeline as Code", "section": "Масштабування і зручності", "url": "lectures/week-3/lecture-11.html#ecosystem", "text": "Масштабування і зручності Multibranch / Organization Folder — сканує організацію GitHub/Bitbucket, знаходить Jenkinsfile і автоматично створює задачі для кожного репозиторію, гілки й PR. Запуск — через webhook або періодично. Docker-агенти — збірка в контейнері: не треба встановлювати інструменти на сервер, можна кілька версій одного інструмента; також підтримується Kubernetes. Shared Libraries (DRY) — спільний код для всіх задач, завантажується з Git-репозиторію. Інструменти: Blue Ocean (візуалізація і редактор конвеєрів, інтеграція з PR), Snippet Generator ( http://jenkins:8080/pipeline-syntax ), Directive Generator, Replay (перезапустити змінений конвеєр без коміту), автоконвертація Freestyle-задач, лінтер Jenkinsfile з командного рядка, автодоповнення в IntelliJ (GDSL), unit-тести конвеєрів. З чату лекції: комітити в головну гілку вирішує команда (зазвичай через PR), а не DevOps одноосібно; Jenkins і альтернативи (GitHub Actions — наступна лекція) краще вивчати окремо — встановлення і налаштування, потім інтеграції."}, {"title": "Лекція 11 · CI/CD і Jenkins: конвеєр збирання, Jenkinsfile і Pipeline as Code", "section": "Тригери збірки, плагіни і правила CI", "url": "lectures/week-3/lecture-11.html#practice", "text": "Тригери збірки, плагіни і правила CI Тригер Як працює Build Now ручний запуск кнопкою Poll SCM Jenkins сам періодично питає репозиторій «чи є нові коміти» (розклад у форматі cron, напр. H/5 * * * * ) Webhook (GitHub hook trigger) репозиторій сам повідомляє Jenkins про push — швидше і без зайвих опитувань Build periodically за розкладом незалежно від змін (нічні збірки) Build after other projects після успішної збірки іншої задачі (upstream/downstream) H у розкладі Jenkins — «хеш»: Jenkins сам обирає хвилину, щоб сотні задач не стартували в одну мить. Плагіни — основний спосіб розширити Jenkins (Git, Pipeline, Docker, Credentials, Blue Ocean тощо), встановлюються через Manage Jenkins → Plugins . Результати тестів публікують кроком junit , готові файли зберігають кроком archiveArtifacts . Правила CI Комітьте в спільну гілку часто , малими порціями. Кожен коміт автоматично збирається і тестується . Зламану збірку лагодять першочергово — «червоний» main блокує всіх. Збірка має бути швидкою (хвилини, а не години). Тестове середовище має бути схожим на production."}, {"title": "Лекція 11 · CI/CD і Jenkins: конвеєр збирання, Jenkinsfile і Pipeline as Code", "section": "Типові помилки", "url": "lectures/week-3/lecture-11.html#mistakes", "text": "Типові помилки Збірки зручно запускати прямо на контролері Jenkins. Код збірки на контролері має доступ до JENKINS_HOME і всіх секретів. Збірки — на агентах, executors контролера = 0. Секрет у sh \"docker login -p ${PASS}\" безпечний, бо Jenkins маскує його. Подвійні лапки — інтерполяція Groovy: секрет потрапляє в текст команди. Пишіть sh '... \"$PASS\" ...' і передавайте через stdin. UNSTABLE — те саме, що FAILURE. UNSTABLE: збірка відбулась, але частина тестів впала. FAILURE: крок завершився помилкою. Налаштовувати конвеєр кліками в UI (Freestyle) і ніде його не зберігати. Jenkinsfile у репозиторії: рев'ю, історія змін, відтворюваність. Для міграції є автоконвертація Freestyle → Pipeline. Писати пароль прямо в Jenkinsfile. Секрети зберігають у Jenkins Credentials і підставляють через credentials('id') в environment . Плутати stage і step . Stage — етап конвеєра (Build, Test, Deploy), steps — список дій усередині етапу ( sh , echo , git ). Тримати input всередині агента, що займає executor на дні. Для очікування схвалення використовують agent none на верхньому рівні, щоб не блокувати ресурси."}, {"title": "Лекція 12 · GitHub Actions: workflow, jobs, runners, secrets і автоматичний деплой", "section": "Вступ", "url": "lectures/week-3/lecture-12.html", "text": ""}, {"title": "Лекція 12 · GitHub Actions: workflow, jobs, runners, secrets і автоматичний деплой", "section": "Чого ви навчитесь", "url": "lectures/week-3/lecture-12.html#goals", "text": "Чого ви навчитесь Назвати 6 компонентів GitHub Actions і пояснити, як вони пов'язані. Створити workflow-файл у правильному каталозі і прочитати його синтаксис: on , jobs , runs-on , steps , uses , with , run . Використати matrix для тестування на кількох версіях і secrets для токенів. Розібрати workflow «тести → збірка → деплой на Heroku» рядок за рядком. Порівняти GitHub Actions і Jenkins. Використовувати контексти й вирази ${{ }} , outputs кроків і jobs, GITHUB_OUTPUT , GITHUB_ENV , функції статусу failure() / always() . Налаштувати середовища зі схваленням, мінімальні permissions , OIDC до хмари, concurrency, services-контейнери. Написати повний workflow: матриця тестів, збірка і публікація образу в GHCR, деплой у staging і production."}, {"title": "Лекція 12 · GitHub Actions: workflow, jobs, runners, secrets і автоматичний деплой", "section": "Що таке GitHub Actions", "url": "lectures/week-3/lecture-12.html#what", "text": "Що таке GitHub Actions GitHub Actions автоматизує робочі процеси розробки — збирання, тести, деплой, рев'ю, керування гілками й задачами — просто в GitHub . Actions — це повторно використовувані скрипти: можна писати свої (JavaScript, Docker тощо) або брати готові з GitHub Marketplace : надіслати повідомлення в Slack ( slack-send ), завантажити звіт покриття ( codecov ), задеплоїти в Google Cloud ( setup-gcloud ). Готові дії «зшиваються» у workflow ."}, {"title": "Лекція 12 · GitHub Actions: workflow, jobs, runners, secrets і автоматичний деплой", "section": "Компоненти", "url": "lectures/week-3/lecture-12.html#components", "text": "Компоненти Ієрархія: подія → workflow → jobs (кожен на своєму runner) → steps (дія або команда). Workflow Робочий процес Налаштований автоматизований процес, що запускає один або кілька jobs. YAML-файл у репозиторії. Event Подія Активність у репозиторії, що запускає workflow: push, pull request, розклад, ручний запуск. Job Завдання Набір кроків, що виконуються на одному runner послідовно. Step Крок Або uses (готова дія), або run (shell-команда) — не обидва в одному кроці. Action Дія Застосунок для платформи, що виконує складну повторювану задачу (checkout коду, встановлення Node). Runner Виконавець Сервер, що виконує jobs: GitHub-hosted ( ubuntu-latest , windows-latest , macos-latest ) або self-hosted — на вашому ПК чи в хмарі."}, {"title": "Лекція 12 · GitHub Actions: workflow, jobs, runners, secrets і автоматичний деплой", "section": "Як увімкнути", "url": "lectures/week-3/lecture-12.html#enable", "text": "Як увімкнути Відкрити репозиторій проєкту на GitHub. Створити каталог .github/workflows/ (саме workflows , у множині) — або вкладка Actions → Set up a workflow чи готовий шаблон. Додати файл у форматі YAML , напр. my-pipeline-ver-1.yml . Щойно файл потрапив у репозиторій, GitHub Actions автоматично починає реагувати на описані події. Результати — на вкладці Actions."}, {"title": "Лекція 12 · GitHub Actions: workflow, jobs, runners, secrets і автоматичний деплой", "section": "Синтаксис: ключі workflow", "url": "lectures/week-3/lecture-12.html#syntax", "text": "Синтаксис: ключі workflow Ключ Значення name Назва для відображення в інтерфейсі (необов'язкова) on Події-тригери, напр. push у гілку master jobs Перелік jobs; ключ ( build ) — ідентифікатор runs-on Тип runner strategy.matrix Запустити job кілька разів з різними параметрами steps Список кроків job uses Готова дія: власник/репо@версія , локальна папка або Docker-образ with Параметри для дії (наприклад, версія Node) run Shell-команда; | дозволяє кілька рядків env Змінні оточення кроку/job actions/checkout завантажує код репозиторію і гілки, на якій запущено workflow — без нього в runner немає вашого коду . actions/setup-node встановлює Node.js потрібної версії. Вихідний код будь-якої дії можна переглянути на GitHub за назвою (версія — після @ )."}, {"title": "Лекція 12 · GitHub Actions: workflow, jobs, runners, secrets і автоматичний деплой", "section": "Вирази, контексти, outputs і змінні оточення", "url": "lectures/week-3/lecture-12.html#contexts", "text": "Вирази, контексти, outputs і змінні оточення Вирази в workflow пишуть у ${{ … }} . Усередині доступні контексти — об'єкти з інформацією про запуск. Контекст Що містить Приклад github подія, репозиторій, гілка, коміт, автор github.ref , github.sha , github.event_name , github.actor env змінні оточення з env: env.IMAGE vars / secrets несекретні змінні / секрети з налаштувань репозиторію vars.REGION , secrets.DOCKER_TOKEN matrix поточна комбінація матриці matrix.node steps результати і outputs попередніх кроків з id steps.meta.outputs.tag needs результати і outputs jobs-залежностей needs.build.outputs.version runner інформація про runner runner.os inputs параметри ручного запуску або reusable workflow inputs.environment Передача значень між кроками і jobs jobs: build: runs-on: ubuntu-latest outputs: version: ${{ steps.meta.outputs.version }} # зробити output кроку output-ом job steps: - id: meta run: echo \"version=1.4.${{ github.run_number }}\" >> \"$GITHUB_OUTPUT\" - run: echo \"DEPLOY_ENV=staging\" >> \"$GITHUB_ENV\" # змінна для всіх наступних кроків job - run: echo \"Версія ${{ steps.meta.outputs.version }}, середовище $DEPLOY_ENV\" - run: echo \"### Зібрано ${{ steps.meta.outputs.version }}\" >> \"$GITHUB_STEP_SUMMARY\" # звіт на сторінці запуску deploy: needs: build runs-on: ubuntu-latest steps: - run: echo \"Деплою ${{ needs.build.outputs.version }}\" Стандартні змінні оточення runner: GITHUB_SHA , GITHUB_REF , GITHUB_REPOSITORY , GITHUB_RUN_NUMBER , GITHUB_WORKSPACE , RUNNER_OS . Різниця записів: ${{ env.X }} підставляє GitHub до запуску кроку, а $X розкриває shell під час виконання. Умови і функції статусу - name: Notify on failure if: failure() # лише якщо попередній крок впав run: ./notify.sh \"Build failed: ${{ github.sha }}\" - name: Cleanup if: always() # завжди, навіть після помилки чи скасування run: docker compose down - name: Only on tags if: startsWith(github.ref, 'refs/tags/v') run: echo \"Release ${{ github.ref_name }}\" За замовчуванням кожен крок має неявну умову success() : після першої помилки решта кроків пропускається. Функції: success() , failure() , always() , cancelled() ; рядкові contains() , startsWith() , endsWith() , format() , toJSON() . Інші корисн"}, {"title": "Лекція 12 · GitHub Actions: workflow, jobs, runners, secrets і автоматичний деплой", "section": "Середовища, схвалення і безпека", "url": "lectures/week-3/lecture-12.html#environments", "text": "Середовища, схвалення і безпека Environments: Continuous Delivery в GitHub Actions У Settings → Environments створюють середовища ( staging , production ) з правилами захисту: required reviewers (хтось має натиснути «Approve»), таймер очікування, дозволені гілки, окремі секрети середовища. Job з environment: production зупиняється і чекає схвалення — це аналог кроку input у Jenkins. deploy-prod: needs: deploy-staging runs-on: ubuntu-latest environment: name: production url: https://shop.example.com steps: - run: ./deploy.sh production Безпека workflow Мінімальні права GITHUB_TOKEN через permissions: на рівні workflow або job. OIDC замість довгоживучих ключів : workflow отримує короткоживучий токен від хмари (AWS, Azure, GCP) через permissions: id-token: write і дію на кшталт aws-actions/configure-aws-credentials . Ключі доступу не зберігаються в secrets взагалі. Фіксуйте сторонні дії на повний SHA коміту ( uses: org/action@a1b2c3… ) або хоча б мажорну версію від перевіреного автора: тег може бути перезаписаний. Секрети не передаються у workflow, запущені з pull request з форків. Тригер pull_request_target їх отримує — тому в ньому ніколи не виконують код із PR. Dependabot оновлює і залежності застосунку, і версії дій у workflow ( .github/dependabot.yml ). Повторне використання Reusable workflow : файл з on: workflow_call , який викликають з інших workflow як job: uses: org/ci/.github/workflows/build.yml@main . Composite action : набір кроків, оформлений як власна дія з action.yml . Starter workflows і Marketplace — готові шаблони і дії."}, {"title": "Лекція 12 · GitHub Actions: workflow, jobs, runners, secrets і автоматичний деплой", "section": "Розбір: тести, збірка і деплой на Heroku", "url": "lectures/week-3/lecture-12.html#example", "text": "Розбір: тести, збірка і деплой на Heroku Workflow зі сторінки курсу (Node.js-застосунок): name: CI on: push: branches: - master # 1. запуск на push у master jobs: build: runs-on: ubuntu-latest # 2. GitHub-hosted runner strategy: matrix: node-version: [14.x, 16.x] # 3. job запуститься двічі steps: - uses: actions/checkout@v1 # 4. забрати код - name: Use Node.js ${{ matrix.node-version }} uses: actions/setup-node@v1 # 5. встановити Node with: node-version: ${{ matrix.node-version }} - name: yarn install run: yarn install # 6. залежності - name: yarn test run: yarn test env: CI: true # 7. тести в CI-режимі - name: yarn build run: yarn run build --if-present # 8. збірка, якщо є скрипт build - name: Add remote origin run: git remote add heroku https://heroku:${{ secrets.HEROKU_API_KEY }}@git.heroku.com/${{ secrets.HEROKU_APP_NAME }}.git - name: Deploy to Heroku run: git push heroku HEAD:master -f # 9. деплой = push у git-репозиторій Heroku Matrix на практиці. Два паралельні запуски. Зверніть увагу: тут деплой виконується в кожній копії matrix — у реальному проєкті деплой виносять в окремий job з needs: build , щоб він ішов один раз. Актуальність прикладу Приклад 2022 року. Відтоді Heroku прибрав безкоштовний тариф (листопад 2022), Node 14/16 більше не підтримуються, а дії мають новіші версії ( actions/checkout@v4 , actions/setup-node@v4 ). Логіку workflow це не змінює."}, {"title": "Лекція 12 · GitHub Actions: workflow, jobs, runners, secrets і автоматичний деплой", "section": "Secrets, обмеження, self-hosted runners", "url": "lectures/week-3/lecture-12.html#secrets", "text": "Secrets, обмеження, self-hosted runners Опублікований токен — великий ризик. Тому в GitHub є secrets : Settings → Secrets and variables → Actions , створюєте, напр., MY_TOKEN , і в workflow пишете ${{ secrets.MY_TOKEN }} . Значення шифрується і маскується в логах. Також щоразу автоматично доступний ${{ secrets.GITHUB_TOKEN }} для роботи з цим репозиторієм. Self-hosted runner — власна машина (ПК, сервер, хмарна ВМ) реєструється в репозиторії (Settings → Actions → Runners) і виконує jobs: доступ до внутрішньої мережі, своє залізо, без хвилин GitHub. Обмеження: у PDF наведено ліміти на кшталт «до 58 хвилин на workflow» — вони не відповідають поточній документації (зараз, наприклад, job на GitHub-hosted runner може тривати до 6 годин). Ліміти і ціни змінюються — перевіряйте розділ «Usage limits» документації GitHub. Публічні репозиторії мають безкоштовні хвилини. Marketplace : Danger — автоматичне код-рев'ю, Dependabot — оновлення вразливих залежностей, Codecov — звіти покриття. Бейдж статусу в README: ![](https://github.com/<user>/<repo>/actions/workflows/<file>.yml/badge.svg) (у PDF — старіший формат через /workflows/<name>/badge.svg )."}, {"title": "Лекція 12 · GitHub Actions: workflow, jobs, runners, secrets і автоматичний деплой", "section": "Довідково: деплой статичного сайту на GitHub Pages", "url": "lectures/week-3/lecture-12.html#pages", "text": "Довідково: деплой статичного сайту на GitHub Pages Цей самий навчальний сайт публікується на GitHub Pages. Сучасний мінімальний workflow для статичного сайту (без збирання) виглядає так: name: Deploy site on: push: branches: [main] permissions: contents: read pages: write id-token: write jobs: deploy: runs-on: ubuntu-latest environment: github-pages steps: - uses: actions/checkout@v4 - uses: actions/upload-pages-artifact@v3 with: path: . # що публікувати - uses: actions/deploy-pages@v4 # викласти на Pages"}, {"title": "Лекція 12 · GitHub Actions: workflow, jobs, runners, secrets і автоматичний деплой", "section": "GitHub Actions vs Jenkins", "url": "lectures/week-3/lecture-12.html#vs-jenkins", "text": "GitHub Actions vs Jenkins Jenkins GitHub Actions Де працює Власний сервер (self-hosted) Хмара GitHub (+ опційно self-hosted runners) Опис конвеєра Jenkinsfile , Groovy .github/workflows/*.yml , YAML Розширення 1500+ плагінів Actions з Marketplace Секрети Jenkins Credentials Repository/Organization Secrets Ручне схвалення input Environments з required reviewers Підтримка Ви адмініструєте сервер і плагіни Інфраструктуру підтримує GitHub Коли обирати Складні корпоративні конвеєри, будь-які VCS, повний контроль Код на GitHub, швидкий старт без сервера"}, {"title": "Лекція 12 · GitHub Actions: workflow, jobs, runners, secrets і автоматичний деплой", "section": "Тригери, залежності jobs, умови, кеш і артефакти", "url": "lectures/week-3/lecture-12.html#more", "text": "Тригери, залежності jobs, умови, кеш і артефакти on: push: { branches: [main] } pull_request: schedule: [{ cron: \"0 3 * * 1\" }] # щопонеділка о 03:00 UTC workflow_dispatch: # кнопка «Run workflow» у вкладці Actions jobs: build: runs-on: ubuntu-latest steps: - uses: actions/checkout@v4 - uses: actions/setup-node@v4 with: { node-version: 20, cache: npm } # кеш залежностей між запусками - run: npm ci && npm test && npm run build - uses: actions/upload-artifact@v4 # передати збірку наступному job with: { name: dist, path: dist } deploy: needs: build # чекати успішного build if: github.ref == 'refs/heads/main' # лише для main runs-on: ubuntu-latest steps: - uses: actions/download-artifact@v4 with: { name: dist } Jobs за замовчуванням ідуть паралельно ; needs робить їх послідовними. Кожен job стартує на чистому runner , тож файли між jobs передають через артефакти ( upload-artifact / download-artifact ), а залежності пришвидшують кешем ( actions/cache або cache: у setup-діях). if: вмикає крок чи job за умовою (гілка, подія, результат попереднього кроку). Розклад schedule використовує формат cron (як у Linux) і час UTC."}, {"title": "Лекція 12 · GitHub Actions: workflow, jobs, runners, secrets і автоматичний деплой", "section": "Повний workflow: тести з матрицею → Docker-образ у GHCR → деплой зі схваленням", "url": "lectures/week-3/lecture-12.html#full-workflow", "text": "Повний workflow: тести з матрицею → Docker-образ у GHCR → деплой зі схваленням name: CI/CD on: push: branches: [main] pull_request: permissions: contents: read packages: write # публікація образу в GitHub Container Registry env: IMAGE: ghcr.io/${{ github.repository }} jobs: test: runs-on: ubuntu-latest strategy: matrix: python: [\"3.11\", \"3.12\"] # дві паралельні копії job steps: - uses: actions/checkout@v4 - uses: actions/setup-python@v5 with: python-version: ${{ matrix.python }} cache: pip - run: pip install -r requirements.txt - run: pytest --junitxml=report.xml - uses: actions/upload-artifact@v4 if: always() with: name: report-${{ matrix.python }} path: report.xml image: needs: test if: github.event_name == 'push' # для PR лише тести runs-on: ubuntu-latest outputs: tag: ${{ steps.vars.outputs.tag }} steps: - uses: actions/checkout@v4 - id: vars run: echo \"tag=${GITHUB_SHA::7}\" >> \"$GITHUB_OUTPUT\" - uses: docker/login-action@v3 with: registry: ghcr.io username: ${{ github.actor }} password: ${{ secrets.GITHUB_TOKEN }} - uses: docker/build-push-action@v6 with: push: true tags: ${{ env.IMAGE }}:${{ steps.vars.outputs.tag }} deploy-staging: needs: image runs-on: ubuntu-latest environment: staging steps: - run: echo \"deploy ${{ env.IMAGE }}:${{ needs.image.outputs.tag }} to staging\" deploy-production: needs: [image, deploy-staging] runs-on: ubuntu-latest environment: production # зупиниться до схвалення рецензентом concurrency: production steps: - run: echo \"deploy ${{ env.IMAGE }}:${{ needs.image.outputs.tag }} to production\" Що тут відбувається На кожен push у main і кожен pull request запускається test у двох версіях Python паралельно; звіти зберігаються як артефакти навіть при падінні тестів ( if: always() ). Лише для push (не для PR) job image збирає Docker-образ з тегом за коротким хешем коміту і публікує в GHCR, використовуючи вбудований GITHUB_TOKEN з правом packages: write . deploy-staging розгортає автоматично (Continuous Deployment у staging). deploy-production чекає схвалення в середовищі production (Continuous Delivery); concurrency не дає запустити два деплої одночасно. Порівняйте з конвеєром Jenkins з лекції 11: етапи ті самі, різниця — у синтаксисі "}, {"title": "Лекція 12 · GitHub Actions: workflow, jobs, runners, secrets і автоматичний деплой", "section": "Типові помилки", "url": "lectures/week-3/lecture-12.html#mistakes", "text": "Типові помилки Файли, створені в одному job, доступні в наступному. Кожен job стартує на чистому runner. Передавайте файли артефактами, значення — через outputs. Сторонню дію безпечно підключати за тегом @main . Гілку і тег можуть змінити. Фіксуйте дію на SHA коміту або перевірену мажорну версію. Для доступу до AWS треба зберегти ключі в secrets. Краще OIDC: короткоживучі облікові дані видаються на кожен запуск, довгоживучих ключів немає. Файл у .github/workflow/ — і нічого не запускається. Правильний каталог — .github/workflows/ (у множині), формат — YAML ( .yml / .yaml ). Забути actions/checkout і дивуватися, що yarn install не знаходить package.json . Runner стартує порожнім — код треба завантажити першим кроком. uses і run в одному кроці. Кожен крок — або дія ( uses ), або команда ( run ). Розділіть на два кроки. Вставити API-ключ прямо в YAML. Репозиторій (і його історія) може бути публічним. Ключ — у Secrets, у файлі — лише ${{ secrets.NAME }} . Помилки відступів у YAML. YAML чутливий до відступів: лише пробіли, однакова вкладеність для елементів одного рівня."}]};
